(349, 1, 'محمد ناجي', 'chat.settings', 'setting', 'chat', 'مفعّلة · المصدر: qwen', '{"model":"nvidia/nemotron-3-ultra-550b-a55b:free","ownUrl":"","enabled":true,"greeting":{"ar":"أهلًا بك في 5A&M 👋 اسألني عن المولدات أو المعدات البيئية أو قطع الغيار، أو اطلب التحدث مع موظف.","en":"Welcome to 5A&M 👋 Ask me about generators, environmental equipment or spare parts — or ask to talk to our team."},"ownModel":"","provider":"qwen","backupModel":"google/gemma-4-31b-it:free","requireLogin":true,"deepseekModel":"deepseek-v4-pro"}', '{"model":"nvidia/nemotron-3-ultra-550b-a55b:free","ownUrl":"","enabled":true,"greeting":{"ar":"أهلًا بك في 5A&M 👋 اسألني عن المولدات أو المعدات البيئية أو قطع الغيار، أو اطلب التحدث مع موظف.","en":"Welcome to 5A&M 👋 Ask me about generators, environmental equipment or spare parts — or ask to talk to our team."},"ownModel":"","provider":"qwen","backupModel":"minimax/minimax-m3.1-flash:free","requireLogin":true,"deepseekModel":"deepseek-v4-pro"}', '::1', '2026-10-20 05:45:09.183'),
