INSERT INTO `chat_cache` (`id`, `lang`, `question`, `q_norm`, `answer`, `source`, `status`, `issues`, `hits`, `reviewed_by`, `last_hit_at`, `created_at`, `updated_at`) VALUES
(1, 'en', 'What are the specifications of the Rental Power Fleet Solutions?', 'what are the specifications of the rental power fleet solutions', 'Here are the key specifications for our Rental Power Fleet Solutions:\n\n- **Capacity:** 20 to 1000 kVA individual units (multi-MW parallel available)\n- **Configurations:** Sound-proof canopy or road-towable mobile trailer\n- **Support:** 24/7 on-site certified technician and preventive maintenance\n- **Service:** Immediate dispatch across Greater Cairo and all governorates\n- **Terms:** Daily, weekly, monthly, seasonal, or multi-year contracts\n\nAll units are 100% load-bank tested and certified before dispatch.\n\nFor more details, visit [Rental Power Fleet Solutions](/model.html?p=rental-power-generators&lang=en).', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:02', '2026-10-05 08:21:55'),
(2, 'en', 'What are the specifications of the Pelican?', 'what are the specifications of the pelican', 'The Elgin Pelican is a three-wheel mechanical broom street sweeper. Key specifications:\n\n- **Sweep path**: 2,438 mm (one broom) or 3,048 mm (two brooms)\n- **Hopper**: 2.8 m³ capacity, 17-second tilt time\n- **Dumping**: Frontal, up to 2,896 mm height\n- **Engine**: 99 hp (74 kW) @ 2500 rpm\n- **Fuel**: 132.5 L tank\n- **Drive**: Hydrostatic, up to 32 km/h\n- **Lift capacity**: 4,080 kg\n\nSee full details: [Pelican — Elgin](/model.html?p=elgin-pelican&lang=en)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:04', NULL),
(3, 'en', 'What do you offer for About us?', 'what do you offer for about us', '5A&M is an Egyptian company established in 2022, specializing in power generation and industrial equipment. We focus on:\n\n- **Vision**: To be a leading partner in Environmental Equipment and Power Solutions.\n- **Mission**: Delivering integrated solutions with quality products and technical expertise.\n- **Values**: Commitment to quality, reliability, transparency, and continuous improvement.\n\nWe provide 3S services: Sales, Spare parts, and Service.\n\nLearn more about our story: [About us](/about.html?lang=en)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:04', NULL),
(4, 'en', 'What are the specifications of the OPEN TYPE GENERATORS KVA?', 'what are the specifications of the open type generators kva', 'Here are the key specifications for our Open Type Generators (20-3000 kVA):\n\n- **Rating:** 20-3000 kVA\n- **Mounting:** Heavy-duty steel skid with anti-vibration isolators\n- **Engines:** Perkins, Cummins, Doosan, Develon, Volvo, Baudouin\n- **Alternators:** Stamford, Leroy-Somer\n- **Controllers:** DSE, ComAp\n- **Cooling:** Tropical radiator (up to 50°C ambient)\n- **Features:** Full service accessibility, industrial exhaust silencer, and certified lifting points\n\nFor a detailed quote, please contact our sales team. You can view more details here: [Open Type Generators](/model.html?p=open-skid-diesel-generators&lang=en).', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:10', NULL),
(5, 'en', 'What is the 2100i used for?', 'what is the 2100i used for', 'The Vactor 2100i is a combination sewer cleaner and jetting truck. It is designed for:\n\n- Sewer cleaning\n- Catch-basin cleaning\n- Hydro-excavation\n- Infrastructure maintenance\n\nIt pairs powerful vacuum recovery with high-pressure jetting.\n\n[2100i](/model.html?p=vactor-2100i&lang=en)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:12', NULL),
(6, 'ar', 'عايز اعرف تفاصيل عن فلاتر فليت جارد وفلاتر المنظومات الصناعية', 'عايز اعرف تفاصيل عن فلاتر فليت جارد وفلاتر المنظومات الصناعيه', 'عندنا فلاتر أصلية من Fleetguard وDevelon لحماية المحركات في بيئات الغبار المصرية.\n\n- **الأنواع:** فلاتر وقود، زيت، هواء، وسائل تبريد.\n- **المميزات:** ترشيح دقيق (Sub-micron) للحفاظ على حقن الوقود، وتقليل الأعطال.\n- **التسليم:** متوفرة في كيتات صيانة مجدولة لسهولة التركيب.\n\nتحب تعرف على نوع المحرك عندك عشان نأكد على الفلتر المناسب؟\n\nتقدر تشوف التفاصيل هنا: [فلاتر فليت جارد](/model.html?p=filters&lang=ar)', 'qwen', 'new', NULL, 0, NULL, '2026-10-05 07:48:47', '2026-10-05 01:30:13', '2026-10-05 07:48:48'),
(7, 'en', 'Do you have the Rental Power Fleet Solutions?', 'do you have the rental power fleet solutions', 'Yes, we offer **Rental Power Fleet Solutions** ranging from **20 to 1000 kVA**.\n\n- **Immediate dispatch** across Greater Cairo and all governorates.\n- **Configurations:** Sound-proof canopy or road-towable mobile trailer.\n- **Support:** Includes 24/7 on-site technician support and preventive maintenance.\n- **Terms:** Daily, weekly, monthly, seasonal, or multi-year.\n\nFor a specific quote or availability check, please tap the “Talk to a person” button below or visit our [Rental Power Fleet Solutions](/model.html?p=rental-power-generators&lang=en) page.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:15', '2026-10-25 15:18:04'),
(8, 'ar', 'هل كابينة عازلة للصوت ومقاومة للعوامل الجوية متوفر وفيه صيانة؟', 'هل كابينه عازله للصوت ومقاومه للعوامل الجويه متوفر وفيه صيانه', 'أيوه، الكابينة متوفرة عندنا في 5A&M.\n\n- **التصنيع**: بنصنعها في ورشتنا الداخلية بمقاسات العميل.\n- **المواصفات**: عزل صوتي عالي، طلاء مقاوم للصدأ، وأبواب صيانة مريحة.\n- **الصيانة**: بنوفر خدمة بعد البيع والدعم الفني.\n\nتحب تعرف أكتر عن المواصفات؟\n[كابينة عازلة للصوت](/model.html?p=sound-proof-canopy&lang=ar)', 'qwen', 'new', NULL, 0, NULL, '2026-10-05 07:48:47', '2026-10-05 01:30:29', '2026-10-05 07:48:48'),
(9, 'ar', 'ايه مواصفات لوحة تزامن وتوازي المولدات؟', 'ايه مواصفات لوحه تزامن وتوازي المولدات', 'أهلاً بيك، دي أهم مواصفات لوحة التزامن عندنا:\n\n- **عدد المولدات:** بتتحكم في 2 لحد 32 مولد متوازي.\n- **الوحدات المتحكم فيها:** DSE 8610 MKII أو ComAp InteliGen.\n- **المكونات الكهربائية:** قواطع ABB أو Schneider Electric.\n- **المميزات:** مزامنة تلقائية، توزيع أحمال ديناميكي، وشاشة لمس (HMI) لمتابعة الأعطال.\n\nتحب تعرف أكتر عن تطبيقها في مشروعك؟\n[لوحة تزامن وتوازي المولدات](/model.html?p=synchronization-panel&lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:31', NULL),
(10, 'ar', 'عندكم مولدات ديزل مفتوحة صناعية KVA؟', 'عندكم مولدات ديزل مفتوحه صناعيه kva', 'أهلاً بيك، أيوه عندنا.\n\n- المولدات المفتوحة (Skid) متاحة من 20 لحد 3000 KVA.\n- بتتعمل بمحركات أصلية زي Perkins و Cummins و Volvo.\n- التصميم عملي ومرن للتركيب في أي موقع.\n\nتحب تعرف أكتر عن المواصفات؟\n[مولدات ديزل مفتوحة صناعية](/model.html?p=open-skid-diesel-generators&lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:32', NULL),
(11, 'en', 'Do you have the Generator Synchronization Panel?', 'do you have the generator synchronization panel', 'Yes, 5A&M offers the Generator Synchronization Panel. It is designed for running multiple generator sets in parallel, featuring:\n\n- Automatic synchronization and load sharing\n- Support for 2 to 32 generators\n- Controllers from Deep Sea Electronics or ComAp\n- Schneider Electric or ABB switchgear components\n\nFor specific project details, you can view the [Generator Synchronization Panel](/model.html?p=synchronization-panel&lang=en).\n\nDo you have a specific number of generators or load requirement in mind?', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:34', NULL),
(12, 'ar', 'عندكم قطع غيار أصلية؟', 'عندكم قطع غيار اصليه', 'أيوه، عندنا قطع غيار أصلية 100% معتمدة.\n\n- لمحركات الديزل (Cummins, Perkins, Volvo وغيرهم).\n- لمولدات الكهرباء (Stamford, Leroy-Somer).\n- للمعدات الثقيلة والبيئية (Develon, Elgin, Vactor).\n\nعندنا مخزون في القاهرة للتسليم السريع.\nتحب تعرف عن نوع معين؟ أو ممكن تطلب عرض سعر من [صفحة قطع الغيار](/parts.html?lang=ar).', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:37', '2026-10-05 08:21:55'),
(13, 'ar', 'ايه الفرق بين المولد المفتوح وأبو كابينة؟', 'ايه الفرق بين المولد المفتوح وابو كابينه', 'الفرق الأساسي إن المولد المفتوح (Open Skid) متركب على قاعدة معدنية من غير كابينة، فبيديك مرونة في التركيب وسهولة في الصيانة من كل الجهات.\nأما المولد أبو كابينة فبيكون جوه كابينة عازلة للصوت ومقاومة للعوامل الجوية، ودي مناسبة للمناطق اللي محتاجة هدوء وحماية من الطقس.\n\nتحب تعرف أكتر عن مواصفات الكابينة؟\n[كابينة عازلة للصوت](/model.html?p=sound-proof-canopy&lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:38', NULL),
(14, 'ar', 'ازاي احسب قدرة المولد اللي محتاجه؟', 'ازاي احسب قدره المولد اللي محتاجه', 'عشان نحدد قدرة المولد المناسبة ليك، محتاجين نعرف تفاصيل الأحمال.\n\n- إيه نوع الحمل الأساسي (صناعي، تجاري، ولا سكني)؟\n- إيه إجمالي القدرة المطلوبة بالكيلو فولت أمبير (kVA)؟\n\nفريقنا هيساعدك في الحساب الدقيق. ممكن تطلب عرض سعر من هنا: [اطلب عرض سعر](/quote.html?lang=ar) أو تكتب «موظف» للتواصل المباشر.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:39', NULL),
(15, 'en', 'Can I get a quote for the Rental Power Fleet Solutions?', 'can i get a quote for the rental power fleet solutions', 'Yes, you can request a quote for our Rental Power Fleet Solutions (20–1000 kVA).\n\nTo get started, please share:\n- Your required power (kVA)\n- Project location\n- Expected start date and duration\n\nYou can submit these details via our [Request a quote](/quote.html?lang=en) page. For immediate assistance, tap the “Talk to a person” button below to connect with our team.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:40', '2026-10-24 02:00:46'),
(16, 'ar', 'عندكم لوحة التحويل الأوتوماتيكي؟', 'عندكم لوحه التحويل الاوتوماتيكي', 'أيوه، عندنا لوحة التحويل الأوتوماتيكي (ATS) مصممة ومجمعة داخلياً في 5A&M.\n\n- بتعمل نقل تلقائي للأحمال بين الكهرباء الحكومية والمولد عند الانقطاع.\n- بتتصمم حسب أمبير المشروع (حتى 4000 أمبير).\n- فيها حماية من الجهد والتردد وقفل ميكانيكي وكهربائي.\n\nتحب تعرف أكتر عن المواصفات؟\n[لوحة التحويل الأوتوماتيكي (ATS)](/model.html?p=ats-panel&lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:43', NULL),
(17, 'ar', 'هل Classic متوفر وفيه صيانة؟', 'هل classic متوفر وفيه صيانه', 'أهلاً! طبعاً، عندنا شاحنة الشفط الصناعي **Guzzler Classic** متوفرة.\n\nوبالنسبة للصيانة، فريقنا الميداني بيقدم:\n- صيانة دورية ووقائية.\n- استجابة سريعة للأعطال الطارئة.\n- قطع غيار أصلية من مخزوننا.\n\nممكن نساعدك في تفاصيل أكثر عن التطبيق اللي محتاجه؟\n[Classic — Guzzler](/model.html?p=guzzler-classic&lang=ar)\n[صيانة المواقع وعقود الصيانة](/maintenance.html?lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 01:30:44', NULL),
(22, 'en', 'Can I get a quote for the Crosswind?', 'can i get a quote for the crosswind', 'Yes, you can request a quote for the Elgin Crosswind.\n\n- Visit the [Request a quote](/quote.html?lang=en) page.\n- Select "Product / equipment" and specify the Crosswind.\n- Include details like your location and operating conditions to help our team.\n\nOur sales team will reply with pricing and availability. For more specs, see [Crosswind](/model.html?p=elgin-crosswind&lang=en).', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 06:45:28', NULL),
(23, 'ar', 'Crosswind يناسب ايه؟', 'crosswind يناسب ايه', 'الـ Crosswind بتعتمد على تقنية الهواء المتجدد (Regenerative Air).\n\nدي مناسبة جدًا لـ:\n- رفع الأتربة والجسيمات الدقيقة.\n- تنظيف الشقوق والأسطح المرصوفة.\n- بيكون عندها كفاءة عالية في الشفط والتجميع.\n\nتحب تعرف أكتر عن مواصفاتها؟\n[Crosswind — Elgin](/model.html?p=elgin-crosswind&lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 06:45:38', NULL),
(24, 'ar', 'احكيلي عن بيع وإيجار المولدات', 'احكيلي عن بيع وايجار المولدات', 'عندنا في 5A&M بيع وإيجار مولدات ديزل بقدرات من 10 لـ 2,500 kVA.\n- المحركات: أصلية من Perkins، Cummins، Hyundai، وVolvo.\n- الإيجار: متاح بقدرات من 20 لـ 1,000 kVA.\n- التصميم: حسب احتياجك (مظلة، حاوية، أو مفتوح).\n\nتحب تعرف أكتر عن نوع معين؟\n[بيع وإيجار المولدات](/generators.html?lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 06:45:40', NULL),
(25, 'ar', 'ايه مواصفات فلاتر فليت جارد وفلاتر المنظومات الصناعية؟', 'ايه مواصفات فلاتر فليت جارد وفلاتر المنظومات الصناعيه', 'عندنا فلاتر أصلية من Fleetguard و Develon لحماية المحركات:\n\n- أنواع الفلاتر: فصل ماء الوقود، زيت التشحيم، هواء السحب، ومبرد.\n- كفاءة عالية: وسائط Stratapore الاصطناعية بتلتقط الشوائب الدقيقة.\n- حماية قصوى في بيئات الغبار المصرية.\n- بتحمي حقنات Common-rail وضخات الضغط العالي من التلوث.\n- متوفرة في كيتات صيانة مجدولة لسهولة التركيب.\n- ضمان أصلي 100% بدون مخاطر تقليد.\n\nتحب تعرف أكتر عن نوع معين؟ ممكن تكتب «موظف» لو محتاج مساعدة إضافية.\n\n[فلاتر فليت جارد](/model.html?p=filters&lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 06:45:42', '2026-10-05 08:21:55'),
(26, 'ar', 'عايز اعرف اكتر عن خدمات ما بعد البيع', 'عايز اعرف اكتر عن خدمات ما بعد البيع', 'أهلاً بيك! خدماتنا لما بعد البيع شاملة جداً:\n- صيانة وقائية وتصحيحية في موقعك.\n- استجابة سريعة للأعطال الطارئة.\n- عقود صيانة مجدولة تشمل قطع غيار أصلية.\n- تغطية لجميع أنحاء الجمهورية.\n\nتحب تعرف تفاصيل أكتر عن نوع المعدات اللي عندك؟\nأو تقدر تطلب عرض سعر من هنا: [اطلب عرض سعر](/quote.html?lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 06:45:51', NULL),
(27, 'en', 'What do you offer for Store?', 'what do you offer for store', '5A&M offers a comprehensive online store for:\n\n- Diesel generator sets\n- Environmental equipment (Elgin, Vactor, Guzzler)\n- Genuine spare parts\n\nYou can browse all items and add them to a quote request. Our sales team will then contact you with prices and availability.\n\n[Store](/store.html?lang=en)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 06:45:54', NULL),
(28, 'ar', 'ايه مواصفات كابينة عازلة للصوت ومقاومة للعوامل الجوية؟', 'ايه مواصفات كابينه عازله للصوت ومقاومه للعوامل الجويه', 'عندنا كابينة عازلة للصوت ومقاومة للعوامل الجوية بتصنيع كامل في ورشة 5A&M، وأهم مواصفاتها:\n\n- **التصنيع**: قص وثني ولحام صاج CNC داخلي\n- **العزل الصوتي**: صوف صخري عالي الكثافة مع بطانة مجلفنة مثقبة\n- **الحماية السطحية**: دهان بودرة بوليستر كهروستاتيكي متعدد المراحل\n- **الإكسسوارات**: أقفال ومفصلات ستانلس ستيل، أبواب بجوانات مانعة للتسرب\n- **أبواب صيانة**: تفتح 180° لسهولة الوصول\n- **تهوية**: مجاري دخول وتفريغ هواء مع مخمدات صوتية\n- **أمان**: زر طوارئ خارجي، وفتحة وقود قابلة للقفل\n\n[كابينة عازلة للصوت ومقاومة للعوامل الجوية](/model.html?p=sound-proof-canopy&lang=ar)\n\nتحب نعمللك عرض سعر؟ ممكن تكتب «موظف» يتواصل معاك الفريق.', 'backup', 'new', NULL, 3, NULL, '2026-10-10 14:50:49', '2026-10-05 06:46:09', '2026-10-10 14:50:49'),
(29, 'ar', 'عندكم تأجير مولدات؟', 'عندكم تاجير مولدات', 'أيوه، عندنا تأجير مولدات ديزل من 20 لـ 1000 ك.ف.أ.\n- توريد فوري وتركيب كامل بالموقع.\n- دعم فني 24/7 وتموين دوري بالوقود.\n- عقود يومية، أسبوعية، شهرية أو سنوية.\n\nتحب نساعدك في اختيار السعة المناسبة؟ ممكن توضحلي إيه نوع الحمل أو الاستخدام؟\n\n[حلول أسطول تأجير المولدات](/model.html?p=rental-power-generators&lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 06:46:21', '2026-10-05 08:21:55'),
(30, 'ar', 'عايز عرض سعر على حلول أسطول تأجير المولدات', 'عايز عرض سعر علي حلول اسطول تاجير المولدات', 'تمام، عشان نجهزلك عرض سعر دقيق على تأجير المولدات، محتاجين نعرف شوية تفاصيل.\n\n- إيه القدرة المطلوبة (kVA)؟\n- إيه مدة الإيجار المتوقعة؟\n\nممكن تملأ فورم طلب العرض السعر هنا: [اطلب عرض سعر](/quote.html?lang=ar)\n\nأو لو تحب، اضغط زرّ «كلّم موظف» تحت وهنوصلك فريق المبيعات مباشرة.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 06:46:22', '2026-10-24 02:00:46'),
(31, 'ar', 'ايه مواصفات مولدات ديزل على مقطورات متحركة KVA؟', 'ايه مواصفات مولدات ديزل علي مقطورات متحركه kva', 'عندنا مولدات ديزل على مقطورات متحركة بسعة من 20 لـ 1500 KVA.\n\nالمواصفات الأساسية:\n- هيكل مقطورة بمحور مفرد أو مزدوج أو ثلاثي مع فرامل.\n- كابينة مقاومة للعوامل الجوية وعازلة للصوت.\n- خزان وقود كبير مدمج في الهيكل لتشغيل أطول.\n- تعليق معزز للطرق الوعرة والصحراء.\n\nتحب تعرف أكتر عن سعة معينة؟\n[مولدات ديزل على مقطورات متحركة](/model.html?p=mobile-trailer-generators&lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 06:46:24', NULL),
(36, 'en', 'Do you have the Industrial Exhaust, Mufflers & Ventilation?', 'do you have the industrial exhaust mufflers ventilation', 'Yes, 5A&M provides industrial exhaust, mufflers, and ventilation solutions. Our services include:\n\n- **Exhaust components:** Residential silencers, critical grade mufflers, and stainless bellows.\n- **Ventilation:** Galvanized acoustic louvres and motorized dampers.\n- **Insulation:** Ceramic blanket or rockwool with aluminium cladding.\n- **Installation:** On-site routing, ceiling suspension, and wall penetration by our technicians.\n\nThese systems are designed to maintain low backpressure and achieve noise attenuation down to 25–35 dBA.\n\nFor more details, visit: [Industrial Exhaust, Mufflers & Ventilation](/model.html?p=exhaust-and-muffler&lang=en)\n\nDo you have a specific generator room size or noise requirement in mind?', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:03', NULL),
(37, 'en', 'What is the OPEN TYPE GENERATORS KVA used for?', 'what is the open type generators kva used for', 'Open type generators (20-3000 KVA) are ideal for industrial settings where maximum service accessibility is required for fast overhauls and maintenance. They feature:\n\n- Heavy-duty steel skid with anti-vibration isolators\n- Tropical cooling for up to 50°C ambient\n- Direct SAE bell-housing alignment\n- Options for Perkins, Cummins, and other Tier-1 engines\n\n[Open Type Generators](/model.html?p=open-skid-diesel-generators&lang=en)\n\nDo you have a specific load or application in mind?', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:04', NULL),
(38, 'ar', 'ايه خدمات من نحن عندكم؟', 'ايه خدمات من نحن عندكم', 'أهلًا بك في 5A&M!\nعندنا حلول متكاملة في:\n- مولدات الديزل (من 10 لـ 2500 ك.ف.أ).\n- معدات البيئة (مكانس Elgin، صرف Vactor، شفط Guzzler).\n- قطع غيار وفلاتر أصلية.\n- خدمات ما بعد البيع والصيانة.\n\nتحب تعرف أكتر عن نوع معين؟\n[من نحن](/about.html?lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:05', NULL),
(39, 'ar', 'لوحة تزامن وتوازي المولدات يناسب ايه؟', 'لوحه تزامن وتوازي المولدات يناسب ايه', 'لوحة التزامن دي بتشتغل لما عندك أكتر من مولد وتبيهم يشتغلوا سوا على نفس الشبكة.\n\n- بتوزع الحمل تلقائي بين المولدات.\n- بتتحكم في التشغيل والإيقاف حسب الحاجة.\n- بتدعم من 2 لحد 32 مولد.\n\nتحب تعرف أكتر عن مواصفاتها؟\n[لوحة تزامن وتوازي المولدات](/model.html?p=synchronization-panel&lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:12', NULL),
(40, 'ar', 'ايه خدمات التواصل عندكم؟', 'ايه خدمات التواصل عندكم', 'عندنا أكتر من طريقة للتواصل مع فريقنا:\n\n- **اتصال هاتفي**: 011 1397 4600\n- **إيميل**: info@5a-eg.com\n- **زيارة المقر**: المستثمرين الجنوبية، التجمع الخامس، القاهرة الجديدة\n- **مركز الخدمة**: المنطقة الصناعية، مسطرد، القاهرة\n\nتحب نتواصل معاك على إيه بالظبط؟\n[التواصل](/contact.html?lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:15', NULL),
(41, 'ar', 'احكيلي عن صيانة المواقع وعقود الصيانة', 'احكيلي عن صيانه المواقع وعقود الصيانه', 'عندنا في 5A&M فريق خدمة ميدانية محترف بيقدملك صيانة المواقع وعقود الصيانة.\n\n- **زيارات دورية**: صيانة وقائية تكتشف الأعطال قبل ما توقف معدتك.\n- **استجابة سريعة**: تشخيص أعطال ودعم فني في موقعك عند أي طارئ.\n- **قطع غيار أصلية**: بنورّد القطع والفلاتر من مخزوننا مباشرة.\n- **عقد شامل**: خطة واضحة نحدد فيها مواعيد الصيانة ونفضل جاهزين لخدمتك طوال العمر التشغيلي.\n\nتحب تعرف أكتر عن تفاصيل العقد؟ ممكن تسأل عن نوع المعدة أو الحمل.\n\n[صيانة المواقع وعقود الصيانة](/maintenance.html?lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:17', NULL),
(42, 'ar', 'عايز اعرف تفاصيل عن مولدات كهربائية من نوع المظلة KVA', 'عايز اعرف تفاصيل عن مولدات كهرباييه من نوع المظله kva', 'أهلين بك في 5A&M. عندنا مولدات كهربائية من نوع المظلة (Sound-proof canopy) بقدرات من 20 لحد 3000 KVA.\n\nالمميزات الرئيسية:\n- كبائن عازلة للصوت ومقاومة للعوامل الجوية.\n- مستوى الضوضاء ينزل لحد 68 dBA عند مسافة 7 متر.\n- محركات ومولدات أصلية من علامات زي Perkins و Cummins و Stamford.\n- خزان وقود مدمج مع حساس تسريب.\n\nتحب تعرف إيه نوع الحمل اللي هتستخدمه المولد؟\nتقدر تشوف التفاصيل أكتر من هنا: [مولدات كهربائية من نوع المظلة](/model.html?p=sound-proof-canopy-diesel-generators&lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:20', NULL),
(43, 'ar', 'عايز عرض سعر على Crosswind', 'عايز عرض سعر علي crosswind', 'أهلاً بيك! عشان نجهزلك عرض سعر دقيق على مكنسة Elgin Crosswind، محتاجين نعرف تفاصيل بسيطة عن المشروع.\n\n- إيه نوع الموقع اللي هتتم فيه الكنس؟ (شوارع رئيسية، مناطق صناعية، إلخ)\n- هل عندك مساحة محددة أو عدد ساعات تشغيل متوقعة؟\n\nممكن تبعت التفاصيل دي من خلال صفحة [اطلب عرض سعر](/quote.html?lang=ar) أو تكتب «موظف» لو تحب نتواصل مع فريق المبيعات مباشرة.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:22', NULL),
(44, 'ar', 'هل Whirlwind متوفر وفيه صيانة؟', 'هل whirlwind متوفر وفيه صيانه', 'أهلاً بيك،\n- **Whirlwind** متوفرة عندنا وهي مكنسة شوارع بالشفط الخالص من Elgin.\n- بنقدّم **صيانة دورية ووقائية** وعقود صيانة شاملة للمعدات.\n- بنوفر قطع غيار أصلية وفريق خدمة ميدانية في موقعك.\n\nتحب نساعدك في طلب عرض سعر أو تفاصيل الصيانة؟\nيمكنك كتابة «موظف» للتواصل مع فريق المبيعات.\n\n[Whirlwind — Elgin](/model.html?p=elgin-whirlwind&lang=ar)\n[صيانة المواقع وعقود الصيانة](/maintenance.html?lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:23', NULL),
(45, 'ar', 'عايز عرض سعر على Whirlwind', 'عايز عرض سعر علي whirlwind', 'أهلاً بيك. عشان نجهزلك عرض سعر دقيق على مكنسة Elgin Whirlwind، محتاجين نعرف شوية تفاصيل عن الموقع.\n\n- إيه نوع الأرضية اللي هتتنظف (رمل، حصى، شوارع معبّدة)؟\n- فين المشروع تقريباً (مدينة أو منطقة)؟\n\nممكن كمان تضيف أي متطلبات خاصة.\nبعد كده تقدر تطلب العرض مباشرة من هنا: [اطلب عرض سعر](/quote.html?lang=ar)\n\nلو تحب نتكلم مع فريق المبيعات مباشرة، اضغط زرّ «كلّم موظف» تحت.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:25', '2026-10-24 02:00:46'),
(46, 'ar', 'عايز اعرف تفاصيل عن Pelican', 'عايز اعرف تفاصيل عن pelican', 'أهلاً بيك! المكنسة دي من Elgin وميكانيكية بثلاث عجلات.\n\n- **مسح الفرشاة:** 2,438 مم (فرشاة واحدة) أو 3,048 مم (فرشاتين).\n- **حجم الحاوية:** 2.8 م³.\n- **أقصى ارتفاع تفريغ:** 2,896 مم.\n- **المحرك:** 99 حصان.\n- **السرعة:** لحد 32 كم/س.\n\nتقدر تشوف التفاصيل الكاملة من هنا: [Pelican — Elgin](/model.html?p=elgin-pelican&lang=ar)\n\nتحب نساعدك في اختيار الموديل المناسب لموقعك؟', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:27', NULL),
(47, 'ar', 'ايه مواصفات قطع غيار مولدات الكهرباء الأصلية؟', 'ايه مواصفات قطع غيار مولدات الكهرباء الاصليه', 'أهلاً بيك! قطع غيار الدينامو (المولدات) الأصلية عندنا من **Stamford** و **Leroy-Somer**، وبتشمل:\n\n- منظمات الجهد التلقائي (AVR) زي SX460 و AS440.\n- دايودات التصحيح الدوارة وممتصات الصدمات.\n- محامل (Bearing) أصلية.\n\nكل القطع متعاير ومختبرة من المصنع حسب مواصفات OEM، وبتضمن ضبط دقيق للجهد (±0.5% – ±1.0%) حتى تحت الأحمال الثقيلة. كمان بنوفر مخططات توصيل ودعم فني من مهندسينا.\n\nتحب تعرف توافر قطعة معينة؟ ممكن تكتب «موظف» عشان فريق المبيعات يرد عليك.\n\n[قطع غيار مولدات الكهرباء الأصلية](/model.html?p=alternator-parts&lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:31', '2026-10-05 08:21:55'),
(48, 'ar', 'هل أنظمة العوادم وكواتم الصوت والتهوية الصناعية متوفر وفيه صيانة؟', 'هل انظمه العوادم وكواتم الصوت والتهويه الصناعيه متوفر وفيه صيانه', 'أيوه، عندنا أنظمة العوادم وكواتم الصوت والتهوية الصناعية.\n- بنصنعها وبنركبها عشان تناسب غرف المولدات أو المواقع المفتوحة.\n- شغلنا يشمل التوجيه، التعليق، والعزل الحراري.\n- فريقنا الفني بيقدّم الخدمة والدعم والصيانة للمعدات.\n\nتحب تعرف أكتر عن المواصفات؟\n[أنظمة العوادم وكواتم الصوت والتهوية الصناعية](/model.html?p=exhaust-and-muffler&lang=ar)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:32', NULL),
(49, 'en', 'Tell me about your Generator sales & rental', 'tell me about your generator sales rental', '5A&M offers diesel generator sets from 10 to 2500 kVA for prime and standby applications. We also provide a rental fleet ranging from 20 to 1000 kVA for temporary power needs.\n\nKey features:\n- Built with genuine engines from Perkins, Cummins, Hyundai, and Volvo.\n- Sized to your specific load and site conditions.\n- Delivered, installed, and supported by our own team.\n\nFor more details, visit [Generator sales & rental](/generators.html?lang=en).\n\nTo get a specific quote, please share your required power load.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:35', NULL),
(50, 'en', 'Can I get a quote for the Automatic Transfer Switch Panel?', 'can i get a quote for the automatic transfer switch panel', 'Yes, you can request a quote for the Automatic Transfer Switch (ATS) Panel. To provide an accurate quotation, our sales team needs to know the specific project amperage (up to 4000 A) and enclosure requirements.\n\nPlease tap the “Talk to a person” button below or **«موظف»** to connect with our team for a formal quote.\n\nYou can also review the specifications here: [Automatic Transfer Switch (ATS) Panel](/model.html?p=ats-panel&lang=en)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-05 07:41:36', '2026-10-25 15:18:04'),
(55, 'ar', 'انا عايز طقم شنابر و عايز بوجيهات عايز عربية جزلر', 'انا عايز طقم شنابر و عايز بوجيهات عايز عربيه جزلر', 'أهلاً بيك! عندنا قطع غيار أصلية (شنابر وبوجيهات) وشاحنات Guzzler.\n\nعشان نجهزلك عرض سعر دقيق، محتاجين منك:\n- **موديل** الشنابر والبوجيهات.\n- **نوع** شاحنة Guzzler المطلوبة (سعة الخزان ونوع الشفط).\n\nممكن تكتب «موظف» للتواصل مع الفريق مباشرة.\n\n[قطع غيار Guzzler](/guzzler-parts.html?lang=ar)', 'qwen', 'new', 'link', 0, NULL, NULL, '2026-10-05 08:03:33', '2026-10-05 08:21:25'),
(59, 'en', 'Can I get a quote for the Industrial Exhaust, Mufflers & Ventilation?', 'can i get a quote for the industrial exhaust mufflers ventilation', 'Yes — we can prepare a quotation for your exhaust, muffler and ventilation needs. To give the sales team the right details, could you tell me the generator rating (kVA) and whether the installation is indoor or outdoor?', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:41:53', NULL),
(60, 'ar', 'عايز اعرف اكتر عن صيانة المواقع وعقود الصيانة', 'عايز اعرف اكتر عن صيانه المواقع وعقود الصيانه', 'أهلاً بيك! عندنا **صيانة مواقع وعقود صيانة** بتغطي كل حاجة للمعدات عندك:\n\n- **فريق خدمة ميدانية** بييجي لموقعك: تركيب، تشغيل، تشخيص أعطال، استجابة طوارئ\n- **عقد صيانة** بجدول واضح: زيارات دورية، صيانة وقائية، تصحيحية، قطع غيار وفلاتر أصلية من مخازننا\n- **دعم مستمر** طول العمر التشغيلي للمعدة\n\nالتفاصيل الكاملة هنا: [صيانة المواقع وعقود الصيانة](/maintenance.html?lang=ar)\n\nتحب أعمل لك طلب عرض سعر لعقد صيانة؟ ولا محتاج معلومة تانية؟', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:42:02', NULL),
(61, 'ar', 'عايز اعرف اكتر عن المشروعات', 'عايز اعرف اكتر عن المشروعات', 'عندنا صفحة **المشروعات** بتعرض نماذج من أعمالنا في تركيب وتشغيل المولدات لمشروعات قومية وقطاعات البترول والزراعة والمحاجر والإنشاءات.\n\nممكن تشوف التفاصيل هنا: [المشروعات](/projects.html?lang=ar)\n\nتحب أسألك عن نوع المشروع أو القطاع اللي مهتم بيه عشان أقدر أوجهك لأقرب نموذج؟', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:42:04', NULL),
(62, 'ar', 'ايه خدمات مكانس الطرق عندكم؟', 'ايه خدمات مكانس الطرق عندكم', 'عندنا مكانس طرق Elgin بثلاثة أنظمة:\n- **هواء متجدد** (Regenerative Air) — مكنسة **Whirlwind**\n- **شفط كامل** (Pure Vacuum) — مكنسة **Crosswind**\n- **فرشاة ميكانيكية** (Mechanical Broom) — مكنسة **Pelican**\n\nبنرشح المكنسة حسب **نوع المخلفات، طبيعة الطريق، وساعات التشغيل**.  \n[مكانس الطرق](/elgin-sweepers.html?lang=ar)\n\nتحب تقولنا تفاصيل الطريق والمخلفات عشان نرشح لك الأنسب؟', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:42:15', NULL),
(63, 'ar', 'ايه مواصفات مولدات ديزل مفتوحة صناعية KVA؟', 'ايه مواصفات مولدات ديزل مفتوحه صناعيه kva', 'عندنا **مولدات ديزل مفتوحة (Open Skid)** بقدرات **من ٢٠ لـ ٣٠٠٠ KVA**  \n- **قاعدة معدنية** شديدة التحمل مع عوازل اهتزاز  \n- **محركات**: Perkins, Cummins, Doosan, Develon, Volvo, Baudouin  \n- **مولدات (Alternators)**: Stamford, Leroy‑Somer  \n- **كنترول**: Deep Sea (DSE) أو ComAp  \n- **تبريد**: راديتر استوائي يتحمل حتى ٥٠°م  \n- **صيانة**: وصول كامل من كل الجوانب، نقاط رفع معتمدة  \n- **عادم**: كاتم صناعي + بلوف ستانلس مرنة  \n\nالتفاصيل الكاملة: [مولدات ديزل مفتوحة صناعية (20-3000) KVA](/model.html?p=open-skid-diesel-generators&lang=ar)\n\n**إيه الحمل المطلوب؟** (عشان نرشح الكيلوفولت أمبير المناسب)  \nلو محتاج عرض سعر أو مواصفات أدق، اضغط زرّ «كلّم موظف» تحت ونوصلك بالفريق.', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:42:24', '2026-10-25 15:18:04'),
(64, 'ar', 'عايز عرض سعر على قطع غيار المحركات الأصلية', 'عايز عرض سعر علي قطع غيار المحركات الاصليه', 'أهلاً بيك! عندنا قطع غيار محركات أصلية لماركات: Cummins، Perkins، Baudouin، Doosan، Develon، Volvo — بتغطي البستونات، السلندرات، الجوانات، التربو، حقن الوقود، طلمبات المياه، وغيرها. المخزون متاح في مخزن 5A&M بالقاهرة للتصرف السريع.\n\nعشان نقدر نعمل لك عرض سعر بالظبط، محتاجين منك:\n- موديل الماكينة / المولد\n- الرقم التسلسلي (Serial Number)\n- قائمة القطع اللي محتاجها (أو صور للوحة البيانات)\n\nممكن تبعتلنا البيانات دي، أو تملأ نموذج طلب عرض سعر من هنا: [اطلب عرض سعر](/quote.html?lang=ar)\n\nلو عايز تكلم حد من الفريق مباشرة، اضغط زرّ «كلّم موظف» تحت وأحوّلك.', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:42:36', '2026-10-24 02:00:46'),
(65, 'ar', 'ايه خدمات اطلب عرض سعر عندكم؟', 'ايه خدمات اطلب عرض سعر عندكم', 'عندنا نموذج «اطلب عرض سعر» بيغطي كل خدماتنا:\n- **المولدات** (بيع / إيجار) — من 10 لـ 2500 kVA  \n- **المعدات البيئية** — Elgin, Vactor, Guzzler  \n- **قطع الغيار الأصلية** — محركات، مولدات، فلاتر، كنترول  \n- **أعمال الصناعة والتركيبات** — كبائن، لوحات، تانكات، تركيب موقع  \n- **خدمات ما بعد البيع** — صيانة، عقود، دعم فني  \n\nتقدر تملأ النموذج من هنا: [اطلب عرض سعر](/quote.html?lang=ar)  \nأو تضيف منتجات للسلة وتطلب عرض سعر من [المتجر](/store.html?lang=ar).\n\nتحب أبدأ معاك بالبيانات الأساسية (الاسم، التليفون، نوع الخدمة)؟', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:42:40', NULL),
(66, 'en', 'Do you rent generators?', 'do you rent generators', 'Yes, we offer a rental fleet from **20 to 1000 kVA** for short- or long-term needs (shutdowns, seasons, projects, or backup until your own set arrives). Sets are sized to your load and site, then delivered, installed and supported by our team.\n\n[Generator sales & rental](/generators.html?lang=en)\n\nWhat is your approximate load (kW/kVA) and rental period?', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:42:44', NULL),
(67, 'ar', 'عندكم لوحة تزامن وتوازي المولدات؟', 'عندكم لوحه تزامن وتوازي المولدات', 'أيوة، عندنا **لوحة تزامن وتوازي المولدات (Synchronization)** مصممة ومجمعة خصيصاً لمشروعك.\n\n**المميزات الرئيسية:**\n- **وضع التوازي:** Island mode و Mains-parallel peak shaving\n- **التحكم:** Deep Sea Electronics (DSE 8610 MKII) أو ComAp InteliGen\n- **مفاتيح التبديل:** Schneider Electric، ABB (ACB)\n- **عدد المولدات:** من 2 حتى 32 مولد على التوازي\n- مزامنة أوتوماتيكية، توزيع أحمال ديناميكي، و HMI شاشة لمس مع تسجيل الأحداث والأعطال\n\n[لوحة تزامن وتوازي المولدات (Synchronization)](/model.html?p=synchronization-panel&lang=ar)\n\n**تحب نعمل لك عرض سعر؟** ابعتلي بيانات المشروع (عدد المولدات، القدرة، نوع الحمل) أو اضغط زرّ «كلّم موظف» تحت عشان يكلمك المهندس المختص.', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:42:50', '2026-10-25 15:18:04'),
(68, 'en', 'Do you have the Custom Sound-Proof & Weatherproof Canopy?', 'do you have the custom sound proof weatherproof canopy', 'Yes — we fabricate **Custom Sound-Proof & Weatherproof Canopies** entirely in our own sheet-metal workshop to your exact dimensions and specifications.\n\nKey features:\n- In-house CNC cutting, bending & welding  \n- High-density rockwool with perforated galvanized liner  \n- Multi-stage electrostatic polyester powder coating  \n- Stainless-steel locks, hinges & weather-sealed gasket doors  \n- 180° swing maintenance doors, baffled intake/discharge ducts, external E-stop & lockable fuel hatch  \n\n[Custom Sound-Proof & Weatherproof Canopy](/model.html?p=sound-proof-canopy&lang=en)\n\nWhat generator rating (kVA) or enclosure size are you planning for?', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:42:59', NULL),
(69, 'ar', 'هل مولدات داخل حاويات متوفر وفيه صيانة؟', 'هل مولدات داخل حاويات متوفر وفيه صيانه', 'أيوة، عندنا **مولدات داخل حاويات** (20–3000 KVA) — حاويات 20 أو 40 قدم معزولة ومكيفة للظروف القاسية، ومحركات Cummins/Perkins/Volvo/Baudouin مع كنترول DSE.  \n[مولدات داخل حاويات (20 - 3000)](/model.html?p=containerized-generators&lang=ar)\n\nكمان بنعمل **صيانة وعمرات كاملة** (استبدال موتور، فحص المولد والكنترول والشاسيه) داخل مركز الخدمة.  \n[أعمال رفع الكفاءة](/overhaul.html?lang=ar)\n\nتحب تطلب عرض سعر؟ ابعت: القدرة المطلوبة، موقع المشروع، وطبيعة التشغيل، وفريق المبيعات يرد عليك بعرض رسمي.  \n[اطلب عرض سعر](/quote.html?lang=ar)\n\nلو محتاج تتكلم مع مهندس، اضغط زرّ «كلّم موظف» تحت وأحوّلك.', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:43:05', '2026-10-24 02:00:46'),
(70, 'ar', 'مولدات كهربائية من نوع المظلة KVA يناسب ايه؟', 'مولدات كهرباييه من نوع المظله kva يناسب ايه', 'مولدات المظلة (20–3000 KVA) بتتناسب مع:\n- المواقع السكنية والتجارية اللي محتاجة **صوت منخفض** (حتى 68 dBA على بعد 7 متر).\n- التركيب في **الخارج** مباشرة — الكبينة مقاومة للأمطار والصدأ.\n- محركات: Perkins, Cummins, Baudouin, Doosan, Develon, Volvo.\n- كنترول: Deep Sea (DSE) أو ComAp.\n\n[مولدات كهربائية من نوع المظلة (20-3000) KVA](/model.html?p=sound-proof-canopy-diesel-generators&lang=ar)\n\n**إيه الحمل التقريبي بالكيلووات أو الأمبير؟** عشان نرشح الكابينة والموتور المناسبين.', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:43:10', NULL),
(71, 'ar', 'عايز عرض سعر على مولدات ديزل على مقطورات متحركة KVA', 'عايز عرض سعر علي مولدات ديزل علي مقطورات متحركه kva', 'أهلاً بيك! عندنا **مولدات ديزل على مقطورات متحركة** من **20 إلى 1500 KVA** — مصممة للقطر على الطرق، كابينة عازلة للصوت/الطقس، تانك وقود مدمج، ومثبتات زاوية للاستواء.  \n[مولدات ديزل على مقطورات متحركة (20 - 1500 ) KVA](/model.html?p=mobile-trailer-generators&lang=ar)\n\nعشان نقدر نعمل لك **عرض سعر** بالظبط، محتاج منك المعلومتين دول بس:\n1. **القدرة المطلوبة (KVA)** أو نوع الحمل (مثال: موقع إنشاءات، حدث، مضخات…).\n2. **موقع المشروع** وتاريخ البداية المتوقع.\n\nممكن تكتبهم هنا، أو تملأ **نموذج طلب عرض السعر** مباشرة:  \n[اطلب عرض سعر](/quote.html?lang=ar)\n\nلو حابب تتكلم مع مهندس مبيعات، اضغط زرّ «كلّم موظف» تحت وأوصلك بالفريق فوراً.', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:43:19', '2026-10-25 15:18:04'),
(72, 'ar', 'ايه مواصفات Classic؟', 'ايه مواصفات classic', 'المواصفات الأساسية لـ **Guzzler Classic**:\n\n- **فاكيوم بلور**: Positive displacement، dual-lobe أو tri-lobe\n- **نطاق الفاكيوم**: 16 – 27 in Hg\n- **تدفق الهواء**: 5,089 – 5,250 CFM\n- **سعة جسم الحطام**: 18 cu yd (13.76 m³)\n- **سمك جسم الحطام**: 1/4 in (6.35 mm)، الباب الخلفي 1/2 in (12.7 mm) على 3 مفصلات ثقيلة\n- **الترشيح**: 4 مراحل (جسم الحطام، سيكلون، باغهاوس 9.94:1، مايكروستrainer)\n- **تنظيف الأكياس**: نظام نبض 120 psi\n- **بوم تلسكوبي (اختياري)**: وصول 55 ft (16.8 m)\n- **تفريغ بالضغط (اختياري)**: ضغط الجسم 14.5 psi أو شفط حتى 28.5 in Hg\n- **تانك هيدروليك**: 50 gal (189 L)، مضخة من PTO\n- **ضمان**: 12 شهر ضد عيوب التصنيع\n\n[Classic — Guzzler](/model.html?p=guzzler-classic&lang=ar)\n\nتحب نعرف أكتر عن التطبيق بتاعك (نوع المادة، مسافة الشفط، ظروف التشغيل) لنرشحلك الأنسب؟', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:43:29', NULL),
(73, 'ar', 'انتو مين وبتعملوا ايه؟', 'انتو مين وبتعملوا ايه', 'أهلاً بيك! إحنا **5A&M** في مصر، وبنقدّم حلول طاقة ومعدات بيئية:\n\n- **مجموعات توليد ديزل** (Generators) وقطع غيار أصلية + صيانة.\n- **معدات بيئية** من **Federal Signal**: مكانس **Elgin**، شفط **Vactor / Guzzler**.\n- **خدمة ما بعد البيع** وقطع غيار أصلية.\n\nتحب تعرف أكتر عن منتج معين ولا تيجي نعمل لك **عرض سعر**؟ ممكن تكتب «موظف» عشان نوصلك بالفريق.', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:43:33', NULL),
(74, 'ar', 'ايه مواصفات مولدات كهربائية من نوع المظلة KVA؟', 'ايه مواصفات مولدات كهرباييه من نوع المظله kva', 'عندنا **مولدات نوع المظلة (Sound-proof Canopy)** بالتفاصيل دي:\n\n- **نطاق القدرة:** 20 – 3000 KVA  \n- **الكابينة:** مصنعة في ورشتنا، مقاومة للعوامل الجوية وعازلة للصوت (تصل لـ 68 dBA @ 7m)  \n- **المحركات:** Perkins, Cummins, Baudouin, Doosan, Develon, Volvo  \n- **المولدات (Alternators):** Stamford, Leroy-Somer  \n- **التحكم:** Deep Sea Electronics (DSE) أو ComAp  \n- **قاعدة الوقود:** تانك مدمج مع مؤشر ميكانيكي وحساس تسريب  \n- **الدهان:** بودرة كهروستاتيكية مضادة للتآكل  \n\n[مولدات كهربائية من نوع المظلة (20-3000) KVA](/model.html?p=sound-proof-canopy-diesel-generators&lang=ar)\n\nتحب نطلبلك عرض سعر رسمي؟ (اضغط زرّ «كلّم موظف» تحت لو عايز تكلم الفريق مباشرة).', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:43:41', '2026-10-24 02:00:46'),
(75, 'en', 'What is the CANOPY TYPE GENERATORS KVA used for?', 'what is the canopy type generators kva used for', 'Canopy Type generators are equipped with weather-resistant, sound-attenuated enclosures for **quieter operation and enhanced protection in demanding environments**.\n\nKey features:\n- Noise attenuation down to **68 dBA @ 7m** (residential silencer & acoustic insulation)\n- Weather-tight, anti-corrosion powder-coated canopy\n- Integral base fuel tank with leak detection\n- Genuine Tier-1 engines (Perkins, Cummins, Baudouin, Doosan, Develon, Volvo) and alternators (Stamford, Leroy-Somer)\n\nRating range: **20–3000 kVA**.\n\nTypical uses include sites needing low noise and outdoor durability — construction, commercial, industrial, and residential backup.\n\n[CANOPY TYPE GENERATORS (20-3000) KVA](/model.html?p=sound-proof-canopy-diesel-generators&lang=en)\n\nWhat is your application or load requirement?', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:43:49', NULL),
(76, 'ar', 'عايز اعرف اكتر عن الرئيسية', 'عايز اعرف اكتر عن الرييسيه', 'أهلاً بيك! 👋  \nالصفحة الرئيسية بتجمع كل خدمات **5A&M** في مكان واحد:\n\n- **معدات بيئية**: مكانس شوارع **Elgin**، معدات صرف **Vactor**، شاحنات شفط **Guzzler**  \n- **توليد طاقة**: مولدات ديزل **10–2500 kVA** (بيع/إيجار/عمرات)  \n- **تصنيع وتجهيز**: خزانات، قواعد، كبائن  \n- **فلاتر أصلية**: **Develon** و **Fleetguard**  \n- **خدمة ودعم**: فرق ميدانية، قطع غيار، صيانة وقائية/طارئة  \n\n[الرئيسية](/?lang=ar)  \n\nتحب أركز على منتج معين ولا تيجي نطلب عرض سعر؟ (اضغط زرّ «كلّم موظف» تحت لو عايز تتكلم مع الفريق مباشرة).', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:44:09', '2026-10-24 02:00:46'),
(77, 'en', 'What is the Crosswind used for?', 'what is the crosswind used for', 'The **Crosswind** is a **regenerative-air street sweeper** designed for:\n\n- **Wide paved surfaces** (roads, highways, parking lots, industrial sites)\n- **Fine particulate, dust & light debris** — its closed-loop air blast lifts material from surface fissures and porous/textured asphalt\n- **Zero exhaust dust emission** — self-cleaning centrifugal separator keeps the air clean\n\nTypical users: municipalities, contractors, infrastructure & large-scale developments.\n\n[Crosswind – Elgin](/model.html?p=elgin-crosswind&lang=en)  \n[All Elgin sweepers](/elgin-sweepers.html?lang=en)\n\nWhat type of debris and route length are you planning to sweep?', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:44:13', NULL),
(78, 'en', 'Tell me about your Fabrication & installation', 'tell me about your fabrication installation', 'We handle the full fabrication and installation scope in-house:\n\n- **Generator enclosures** – weatherproof, silent and super-silent canopies; modified ISO containers for high-capacity sets  \n- **Electrical panels** – custom-built control and distribution panels  \n- **Fuel tanks & skids** – base-frame tanks, day tanks and integrated fuel systems  \n- **On-site installation** – mechanical, electrical and commissioning by our own team  \n\nDetails: [Fabrication & installation](/fabrication.html?lang=en)  \nRelated: [Power Solutions](/power.html?lang=en)\n\nWhat capacity or site conditions are you planning for?', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:44:18', NULL),
(79, 'en', 'What do you offer for Power Solutions?', 'what do you offer for power solutions', 'We provide complete **Power Solutions** covering:\n\n- **Generator sales & rental** — diesel sets 10–2500 kVA (prime/standby) and gas sets; rental fleet 20–1000 kVA. Built on genuine Baudouin, Perkins, Hyundai, Cummins, Doosan, Develon, Volvo engines.  \n- **Efficiency upgrades & overhauls** — engine replacement (repowering) and full overhauls to restore performance and extend life.  \n- **Fabrication & installation** — sound-proof/weather canopies, containers, mobile trailers, open skids; turnkey delivery, hook-up and commissioning by our team.  \n- **Genuine spare parts & maintenance** — OEM parts, preventive maintenance contracts, 24/7 technician support.\n\nDetails: [Power Solutions](/power.html?lang=en) | [Generator sales & rental](/generators.html?lang=en) | [Efficiency upgrades & overhauls](/overhaul.html?lang=en)\n\nWhat is your application and approximate load (kVA)?', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:44:33', NULL),
(80, 'en', 'Can I get a quote for the Genuine Alternator Spares?', 'can i get a quote for the genuine alternator spares', 'Yes. To prepare a quotation we need a little more information.\n\nPlease tell us:\n- Which alternator brand and model (e.g., Stamford SX460, Leroy‑Somer R438, etc.)?\n- The generator set rating (kVA) and application?\n- Required components (AVR, diodes, bearings, etc.) and quantities?\n- Delivery location in Egypt?\n\nYou can submit the details via our quote form: [Request a quote](/quote.html?lang=en)  \nOr tap the “Talk to a person” button below to connect directly with the sales team.', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:44:42', '2026-10-25 15:18:04'),
(81, 'ar', 'عايز عرض سعر على Classic', 'عايز عرض سعر علي classic', 'أهلاً بيك! عندنا **Guzzler Classic** — معدة شفط صناعي للخدمة الشاقة.\n\nعشان نقدر نعمل لك عرض سعر بالظبط، محتاجين منك شوية بيانات بسيطة:\n- **القدرة/الموديل المطلوب** (لو عندك مواصفات معينة)\n- **موقع المشروع** (العنوان أو المحافظة)\n- **تاريخ البداية المتوقع**\n- **مدة الاستخدام** (شراء / إيجار / مدة الإيجار)\n\nممكن تملأ النموذج من هنا: [اطلب عرض سعر](/quote.html?lang=ar)  \nأو ابعتلي البيانات وأعملها لك بنفسي.\n\nلو حابب تتكلم مع حد من الفريق مباشرة، اضغط زرّ «كلّم موظف» تحت وأوصلك بيهم.', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:44:48', '2026-10-25 15:18:04'),
(82, 'en', 'Do you have the Genuine Engine Parts?', 'do you have the genuine engine parts', 'Yes, we stock **Genuine Engine Parts** for diesel generator sets and heavy equipment at our Cairo warehouse.\n\n**Brands covered:** Cummins, Perkins, Baudouin, Doosan, Develon, Volvo  \n**Key systems:** Pistons, cylinder liners, gaskets, turbochargers, fuel injectors, water pumps  \n**Benefits:** 100% genuine OEM certified, manufacturer warranty, rapid emergency dispatch\n\n🔗 [Genuine Engine Parts](/model.html?p=engine-parts&lang=en)\n\nTo prepare a quotation, could you tell me the **engine brand and model** (or generator set model) you need parts for?', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:44:53', NULL),
(83, 'ar', 'عايز اعرف تفاصيل عن أطقم صيانة الحفارات والمعدات الثقيلة', 'عايز اعرف تفاصيل عن اطقم صيانه الحفارات والمعدات الثقيله', 'أهلاً بيك! عندنا **أطقم صيانة أصلية** للحفارات والمعدات الثقيلة (Develon & Doosan):\n\n- **المعدات المدعومة**: حفارات زاحفة، حفارات بعجلات، لودرات بعجلات  \n- **محتوى الأطقم**: فلاتر هيدروليك (return/pilot)، مستلزمات محرك، بنزات جنزير، كيتات سيلات  \n- **فترات الصيانة**: مجمعة حسب 250 / 500 / 1000 / 2000 ساعة تشغيل  \n- **المصدر**: استيراد مباشر من المصنع + دعم فني من مهندسين خبرة بـ Develon  \n\n[أطقم صيانة الحفارات والمعدات الثقيلة — Develon](/model.html?p=heavy-equipment-parts&lang=ar)\n\nتحب أعرضلك كيت فترة معينة (مثلاً 500 ساعة) ولا عندك موديل/سيريال نمشي عليه؟', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:45:07', NULL),
(84, 'en', 'What do you offer for Road sweepers?', 'what do you offer for road sweepers', 'We supply three Elgin street sweeper ranges in Egypt:\n\n- **Regenerative air** — Crosswind  \n- **Pure vacuum** — Whirlwind  \n- **Mechanical broom** — Pelican  \n\nThese cover municipal roads, highways, industrial sites and large developments.\n\nTo recommend the right model, tell me:\n- Typical debris type  \n- Route conditions (urban, highway, narrow streets)  \n- Daily operating hours  \n\n[Road sweepers](/elgin-sweepers.html?lang=en)  \n[Environmental Solutions](/environment.html?lang=en)', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:45:10', NULL),
(85, 'ar', 'عندكم مقطورة نقل وتثبيت المولدات الثقيلة؟', 'عندكم مقطوره نقل وتثبيت المولدات الثقيله', 'أيوة، عندنا **مقطورة نقل وتثبيت المولدات الثقيلة** — مصممة في ورشة 5A&M للمحطات المتنقلة بين مواقع العمل.\n\nالمواصفات الأساسية:\n- **سعة التحميل**: من 1,500 كجم حتى 18,000 كجم GVW\n- **تكوين المحاور**: محور مفرد، مزدوج، أو ثلاثي (torsion/leaf)\n- **نظام الفرامل**: ميكانيكية overrun أو هوائية pneumatic مع كابل أمان\n- **الإضاءة والسلامة**: LED مطابقة للطرق، عواكس، وسلاسل أمان\n- **الهيكل**: قنوات فولاذية ثقيلة للطرق الصحراوية\n- **التثبيت**: عجلة أمامية قابلة للتعديل + 4 جاكات زاوية ثقيلة\n- **إضافات**: عجلة احتياطية، واقيات طين، سلة كابلات\n- **مصممة خصيصًا** لأبعاد وتوزيع وزن المولد\n\n[مقطورة نقل وتثبيت المولدات الثقيلة](/model.html?p=genset-trailer&lang=ar)\n\nتحب تطلب عرض سعر أو عندك استفسار تاني؟', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:45:15', NULL),
(86, 'ar', 'عايز عرض سعر على قطع غيار مولدات الكهرباء الأصلية', 'عايز عرض سعر علي قطع غيار مولدات الكهرباء الاصليه', 'أهلاً بيك! عندنا قطع غيار أصلية لمولدات الكهرباء (ستامفورد، ليروي سومر، بيركنز، كومينز، فولفو، دووسان، ديفيلون) — AVR، ديودات، رولمان بلي، فلاتر، طلمبات، حاقنات، جوانات، تيربو… إلخ.\n\nعشان نقدر نعمل لك عرض سعر بالظبط، محتاجين منك:\n- **موديل المولد / الماكينة** (أو الماركة والقدرة kVA)\n- **الرقم التسلسلي (Serial Number)** إن وجد\n- **قائمة القطع** اللي محتاجها (أو صور للوحة البيانات / القطعة)\n\nممكن تبعتلنا التفاصيل دي هنا، أو تملأ **نموذج طلب عرض السعر** مباشرة: [اطلب عرض سعر](/quote.html?lang=ar)\n\nلو حابب تتكلم مع فريق المبيعات دلوقتي، اضغط زرّ «كلّم موظف» تحت وأحوّلك.', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:45:21', '2026-10-25 15:18:04'),
(87, 'ar', 'حلول أسطول تأجير المولدات يناسب ايه؟', 'حلول اسطول تاجير المولدات يناسب ايه', 'حلول أسطول تأجير المولدات (20 – 1000 kVA) تناسب:\n- المشاريع المؤقتة أو الموسمية\n- مواقع الإنشاءات والبنية التحتية\n- الفعاليات والمناسبات\n- الطوارئ والاحتياجات العاجلة\n- القطاعات الصناعية والزراعية والتجارية\n\nالمميزات: توريد فوري، تركيب كامل بالموقع، تموين دوري بالوقود، دعم فني 24/7، واختبار حمل كامل قبل التسليم.\n[حلول أسطول تأجير المولدات](/model.html?p=rental-power-generators&lang=ar)\n\nإيه نوع الحمل والموقع عشان نحدد الحجم المناسب؟', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:45:24', NULL),
(88, 'ar', 'بتوصلوا لكل محافظات مصر؟', 'بتوصلوا لكل محافظات مصر', 'أيوة، بنغطي كل محافظات مصر بالتوريد والتركيب والخدمة الميدانية.  \nلو محتاج عرض سعر أو زيارة موقع، اضغط زرّ «كلّم موظف» تحت ونوصلك بالفريق.', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:45:43', '2026-10-24 02:00:46'),
(89, 'ar', 'ايه مواصفات Whirlwind؟', 'ايه مواصفات whirlwind', 'عندنا **Elgin Whirlwind** — مكنسة شفط خالص على شاسيه شاحنة، عالية الأداء للطرق غير المستوية والشوارع الرئيسية:\n\n- **تقنية الكنس**: شفط مباشر (Pure vacuum)\n- **عرض فوهة الشفط**: 813 مم (32 بوصة)\n- **مسار الكنس (فوهة + فرشة جانبية)**: 1,981 مم (78 بوصة)\n- **أقصى مسار كنس**: 3,658 مم (144 بوصة)\n- **قطر الفرشة الجانبية**: 406 مم (16 بوصة)\n- **سعة الهوبر**: 6 م³ (8 ياردة مكعبة)\n- **زاوية التفريغ**: 50°\n- **زاوية أرضية الهوبر**: 10°\n- **رفع الهوبر**: أسطوانة هيدروليكية مزدوجة الفعل\n- **المحرك المساعد**: 4.5 لتر — 74 حصان (55 كيلووات) @ 2400 دورة/دقيقة\n- **العزم**: 304 نيوتن·متر (224 رطل·قدم) @ 1600 دورة/دقيقة\n- **نظام الطاقة المشترك (مسجل)**: الشاسيه يدعم المحرك المساعد\n\n**مميزات**: شفط عالي السرعة للرمال الكثيفة والمخلفات، مسار كنس واسع مع قاعدة عجلات قصيرة للمناورة في الشوارع الضيقة، فرش جانبية مفصلية بتحكم من الكابينة.\n\n[Whirlwind — Elgin](/model.html?p=elgin-whirlwind&lang=ar)\n\nتحب نرشحلك المدى الأنسب حسب نوع المخلفات وطبيعة الطريق وساعات التشغيل؟', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:45:50', NULL),
(90, 'ar', 'Classic يناسب ايه؟', 'classic يناسب ايه', 'الـ **Classic** بيخدم التطبيقات الثقيلة زي:\n- شفط مواد صلبة، مساحيق جافة، مخاليط ثقيلة، وحمأة لزجة\n- مسافات شفط بعيدة\n- استعادة مواد في بيئات صناعية صعبة\n\nعشان نرشّحلك بالظبط: **إيه نوع المادة اللي هتشفطها؟** والمسافة التقريبية؟\n\n[Classic — Guzzler](/model.html?p=guzzler-classic&lang=ar)  \n[معدات الشفط الصناعي](/guzzler-vacuums.html?lang=ar)', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:45:59', NULL),
(91, 'ar', 'عندكم أنظمة العوادم وكواتم الصوت والتهوية الصناعية؟', 'عندكم انظمه العوادم وكواتم الصوت والتهويه الصناعيه', 'أيوة، عندنا **أنظمة العوادم وكواتم الصوت والتهوية الصناعية** — تصميم وتنفيذ كامل لغرف المولدات والمواقع المفتوحة.\n\nأبرز المكونات:\n- كواتم صوت: Residential / Critical grade (إضعاف 25–35 dBA)\n- بلوفات ستانلس مرنة (Stainless bellows) لتمدد الحرارة والاهتزاز\n- مجاري تهوية: صاج مجلفن، لوفرز صوتية، دامبرز موتور\n- عزل حراري: سيراميك / روك وول مع تغليف ألومنيوم\n- تنفيذ موقع: توجيه المسارات، تعليق سقف، اختراق حوائط، دروع حرارية\n\n[أنظمة العوادم وكواتم الصوت والتهوية الصناعية](/model.html?p=exhaust-and-muffler&lang=ar)\n\nتحب أعرض عليك نماذج الكواتم أو نطلب عرض سعر؟ اضغط زرّ «كلّم موظف» تحت لو عايز تتكلم مع المهندس مباشرة.', 'backup', 'new', NULL, 1, NULL, '2026-10-06 04:46:45', '2026-10-06 04:46:24', '2026-10-24 02:00:46'),
(92, 'ar', 'بتعملوا صيانة للمولدات؟', 'بتعملوا صيانه للمولدات', 'أيوة، بنعمل صيانة للمولدات — زيارات دورية، وقائية، وتصحيحية، مع قطع غيار أصلية من مخازننا.\nممكن نعمل **عقد صيانة** يغطي جدولة الأعمال وتوريد القطع والدعم طول العمر التشغيلي.\nتفاصيل أكتر هنا: [صيانة المواقع وعقود الصيانة](/maintenance.html?lang=ar)\n\nإيه قدرة المولد (kVA) ونوع الاستخدام؟', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:46:45', NULL),
(93, 'en', 'What are the specifications of the Crosswind?', 'what are the specifications of the crosswind', 'Based on the Crosswind specifications from our Elgin sweepers range:\n\n**Crosswind — Regenerative Air Street Sweeper**\n\n**Sweeping Performance:**\n- Sweep path (pickup head only): 2,286 mm (90 in)\n- Sweep path (head + one broom): 2,971 mm (117 in)  \n- Sweep path (head + two brooms): 3,658 mm (144 in)\n- Hopper volume: 6 m³ (8 cu yd)\n- Dump angle: 50°\n- Hopper lifting: Hydraulic, two-stage telescoping cylinder\n- Dust separator: Self-cleaning centrifugal\n\n**Chassis Engine:**\n- Engine: Cummins ISB 6.7 — in-line 6 turbo diesel\n- Output: 200 hp (150 kW) @ 2400 rpm\n- Torque: 708 Nm (520 ft-lb) @ 1600 rpm\n- Fuel tank: 189 L (50 gal)\n\n**Key Features:**\n- Closed-loop regenerative air system with zero exhaust dust emission\n- Trapped particulate pick-up from porous and textured asphalt\n\nFor more details or to discuss your specific route requirements: [Crosswind](/model.html?p=elgin-crosswind&lang=en) | [All Elgin Sweepers](/elgin-sweepers.html?lang=en)\n\nWhat type of debris and surface will you be sweeping?', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-06 04:46:57', NULL),
(98, 'ar', 'ممكن اعرف انت اسمك ايه كبوت ai', 'ممكن اعرف انت اسمك ايه كبوت ai', 'أنا مساعد المبيعات الخاص بشركة 5A&M (مصر). أنا هنا لأساعدك في العثور على حلول المولدات المناسبة، سواء كانت للبيع أو التأجير، بالإضافة إلى قطع الغيار الأصلية وخدمات ما بعد البيع.\n\nهل أنت مهتم بشراء أو استئجار مولد؟ وما هو الحمل الذي تحتاجه (بالكيلو فولت أمبير) أو نوع العمل الذي تقوم به؟', 'backup', 'new', NULL, 0, NULL, NULL, '2026-10-09 22:46:21', NULL),
(100, 'ar', 'بتوفروا قطع غيار أصلية؟', 'بتوفروا قطع غيار اصليه', 'أهلاً بيك، نوفر قطع غيار أصلية معتمدة من Cummins, Perkins, Baudouin, Develon, Volvo, Doosan لمولدات الديزل والمعدات الثقيلة. هل تريد معرفة مزيد عن مولدات الكهرباء، أو قطع غيار المولدات، أو أطقم صيانة الحفارات؟ أرسل لنا ما يهمك حتى نراسلك بالمتوفر.', 'debate', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:35:24', '2026-10-10 14:52:06'),
(101, 'ar', 'عندي بلدية صغيرة وشوارعها ضيقة ومحتاج حاجة تنضف الصرف، ايه اللي تنصحني بيه؟', 'عندي بلديه صغيره وشوارعها ضيقه ومحتاج حاجه تنضف الصرف ايه اللي تنصحني بيه', 'لبلدية صغيرة بشوارع ضيقة، أنصحك بـ **Vactor iMPACT** — وحدة مدمجة مشتركة (شفط + ضخ مياه عالي الضغط) بتصميم **Modul-Flex**، بوم هيدروليكي 180°، وتحكّم **IntuiTouch**، بتدور وتشتغل في المساحات الضيقة من غير تعقيد.  \n[تفاصيل iMPACT](/model.html?p=vactor-impact&lang=ar)\n\nإيه سعة حاوية المخلفات اللي تناسبكم؟ (3 أو 5 ياردة³) عشان نكمّل المواصفات ونعملك عرض سعر.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:40:32', NULL),
(102, 'ar', 'عايز عرض سعر على 2100i', 'عايز عرض سعر علي 2100i', 'الوحدة 2100i من فاكتور (Vactor) هي وحدة مشتركة لتنظيف الصرف والضخ بالمياه عالية الضغط، بتجمع بين شفط قوي وضخ مائي عالي الضغط بتحكّم IntuiTouch. عشان نقدر نعملك عرض سعر مظبوط، محتاجين منك: القدرة المطلوبة، موقع المشروع، وتاريخ البداية المتوقع. تقدر تملأ نموذج طلب عرض السعر على الموقع أو تكتب «موظف» عشان يتواصل معاك فريق المبيعات.', 'debate', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:42:00', '2026-10-10 14:52:06'),
(103, 'en', 'Tell me about your About us', 'tell me about your about us', '5A&M is an Egyptian company established in 2022, specialised in power generation and industrial equipment. Our vision is to be a leading partner in Environmental Equipment and Power Solutions, driven by continuous growth, trusted partnerships, and sustainable value creation.\n\n- Company Name: 5A&M for Import, Export and Contracting\n- Established: 2022\n- Business Activity: 3S — sales, spare parts, and service — for generators and heavy equipment.\n\nWe offer:\n- Power Solutions: Complete diesel generator sets from 10 to 2500 kVA for prime and standby applications.\n- Efficiency Upgrades: Engine replacement and complete overhaul solutions to restore efficiency and extend service life.\n- Fabrication & Installation: Generator canopies, electrical panels, fuel tanks, and on-site installation by our own team.\n- Genuine Spare Parts: For generators, heavy equipment, and environmental units.\n\nWe are committed to quality, reliability, and continuous improvement, supported by strong warranty coverage and professional service.\n\nFor details or a quotation, please type «موظف» or "agent" to reach our team.', 'debate', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:42:09', NULL),
(104, 'ar', 'عايز اعرف تفاصيل عن حلول أسطول تأجير المولدات', 'عايز اعرف تفاصيل عن حلول اسطول تاجير المولدات', 'عندنا حلول أسطول تأجير المولدات من 20 حتى 1000 ك.ف.أ بتوريد فوري، مع التركيب الكامل بالموقع والتموين الدوري بالوقود ودعم فني 24/7.\n\n- الوحدات: 20–1000 ك.ف.أ (وحدات فردية) مع إمكانية التوازي لعدة ميجاوات.\n- مدة العقد: يومي، أسبوعي، شهري، موسمي، أو متعدد السنوات.\n- التكوينات: كابينة عازلة للصوت أو مقطورة متنقلة للسحب على الطريق.\n- التغطية: نشر فوري في القاهرة الكبرى وجميع المحافظات.\n- كل وحدة مختبرة بحمل كامل 100% ومعتمدة قبل الإرسال.\n- تسليم مفتاح: فحص الأساس، التركيب الميكانيكي، والتوصيل الكهربائي.\n- الصيانة الدورية (زيوت، فلاتر، مستهلكات) مشمولة.\n- استبدال فوري مضمون في حالة العطل.\n\nللخطوة القادمة: ابعت لنا القدرة المطلوبة، الموقع، ومدة الإيجار المتوقعة عبر نموذج عرض السعر، أو اضغط زرّ «كلّم موظف» تحت ليرد عليك الفريق مباشرة.', 'debate', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:42:19', '2026-10-24 02:00:46'),
(105, 'ar', 'خزانات وقود ديزل ثابتة ومتحركة مناسب لشغل كتير يومي؟', 'خزانات وقود ديزل ثابته ومتحركه مناسب لشغل كتير يومي', 'أهلاً بيك! بنصنّع خزانات ديزل ثابتة ومتحركة بسعات من 500 لتر لغاية 50,000 لتر، مصممة حسب ساعات التشغيل اليومية. الخزانات بتصنيع محلي بصاج كربون ثقيل وطلاء مضاد للصدأ، متاحة بجدار مفرد أو مزدوج مع حوض احتواء مدمج، ومزودة بمضخة نقل آلية بمفاتيح عوامة، على قاعدة مقطورة قابلة للقطر أو قاعدة جيوب شوكية. للاستفسار أو طلب عرض سعر، اضغط زرّ «كلّم موظف» تحت يتواصل معاك فريق المبيعات.', 'debate', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:42:26', '2026-10-24 02:00:46'),
(106, 'ar', 'ليه اختار قطع غيار مولدات الكهرباء الأصلية بالذات؟', 'ليه اختار قطع غيار مولدات الكهرباء الاصليه بالذات', 'قطع الغيار الأصلية من 5A&M معتمدة 100% من المصنّعين (Stamford، Leroy‑Somer، Cummins، Perkins، Baudouin، Doosan، Develon، Volvo، Hyundai Infracore، Develon، Fleetguard).\nمزايا موثقة في الموقع:\n- AVRs أصلية (SX460، AS440، MX321، R250، R438، R450) بدقة تنظيم جهد ±0.5%–±1% تحت أحمال مفاجئة، مع مخططات توصيل ودعم ضبط من مهندسي 5A&M.\n- قطع محركات أصلية (مكابس، بطانات، حشيات، توربو، حاقنات، مضخات مياه) تمنع الأعطال المبكرة وتحافظ على كفاءة الوقود، ومتوفرة في مخزن القاهرة للطوارئ.\n- فلاتر Develon وFleetguard أصلية لتشغيل آمن وعمر أطول.\n- وكيل حصري لقطع Elgin وVactor وGuzzler.\nكل القطع مغطاة بضمان المصنع، وفريق 5A&M يقدّم دعماً فنياً وتركيباً.\nلطلب عرض سعر أو معرفة التوافر: ابعت الموديل والرقم التسلسلي، أو اضغط زرّ «كلّم موظف» تحت.', 'debate', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:42:42', '2026-10-24 02:00:46'),
(107, 'en', 'Tell me about your After-sales services', 'tell me about your after sales services', 'Our after-sales services cover:\n- Field service teams for installation, commissioning, troubleshooting and emergency breakdown response across Egypt.\n- Preventive, periodic and corrective maintenance on contract.\n- Genuine spare parts from stock: Hyundai Infracore, Perkins, Cummins, Volvo, Develon, Fleetguard filters and maintenance kits.\n- Warranty support on every generator we deliver.\n\nFor a tailored maintenance contract or parts list, please request a quotation or type «موظف» to speak with our team.', 'debate', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:42:48', NULL),
(108, 'en', 'Do you have the Heavy Equipment & Excavator Maintenance Kits?', 'do you have the heavy equipment excavator maintenance kits', 'Yes — we stock **Heavy Equipment & Excavator Maintenance Kits** for Develon / Doosan crawler excavators, wheel excavators and wheel loaders.  \nKits are bundled for 250 / 500 / 1000 / 2000-hour intervals and include genuine hydraulic return & pilot filters, engine consumables, track pins and seal kits — direct factory import with technical support from Develon-experienced technicians.  \n[Heavy Equipment & Excavator Maintenance Kits](/model.html?p=heavy-equipment-parts&lang=en)\n\nWhat machine model and hour interval do you need?', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:49:55', NULL),
(109, 'ar', 'احكيلي عن أعمال رفع الكفاءة', 'احكيلي عن اعمال رفع الكفاءه', 'أهلاً بيك! **أعمال رفع الكفاءة** عندنا بتتمثل في **استبدال المحرك القديم بمحرك جديد** مع **إعادة استخدام الموبينة، لوحة التحكم، والشاسيه** بعد فحصهم واختبارهم كويس. ده حل اقتصادي وعملي جداً لما المحرك هو العطلان وباقي المولد سليم.\n\nالخدمة بتتعمل في **مركز الخدمة** على يد فريق متخصص وحسب توصيات الشركة المصنعة وساعات التشغيل، والهدف استعادة الأداء وإطالة العمر الافتراضي.\n\n[أعمال رفع الكفاءة](/overhaul.html?lang=ar)\n\n**إيه قدرة المولد اللي عايز ترفع كفاءته؟** (بالـ kVA) — عشان أقدر أوجهك الصح وأعملك عرض سعر لو حابب.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:50:06', NULL),
(110, 'ar', 'ليه اتعامل معاكم في بيع وإيجار المولدات؟', 'ليه اتعامل معاكم في بيع وايجار المولدات', 'عندنا حلول طاقة متكاملة — بيع وإيجار مولدات ديزل من **10 إلى 2500 kVA** بمحركات أصلية (Perkins, Cummins, Baudouin, Doosan, Develon, Volvo) ومولدات (Stamford, Leroy-Somer) ولوحات تحكم (DSE, ComAp).\n\n- تصنيع الكبائن والخزانات والقواعد **بـ ورشتنا** (دهان كهربائي مضاد للتآكل، عزل صوتي يصل 68 dBA @ 7m).\n- عمرات شاملة ورفع كفاءة، تركيب وتشغيل، وقطع غيار أصلية (Fleetguard, Develon).\n- خدمة ميدانية وفريق دعم في الموقع.\n\nإيه **الحمل المطلوب (kVA)** ونوع التطبيق؟ أبعتله عرض سعر من [صفحة الطلب](/quote.html?lang=ar) أو اضغط زرّ «كلّم موظف» تحت لكلمك حد من الفريق.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:50:09', '2026-10-24 02:00:46'),
(111, 'ar', 'ليه اتعامل معاكم في التواصل؟', 'ليه اتعامل معاكم في التواصل', 'عندنا تواصل مباشر وسريع من غير وسيط:\n- تليفون: **011 1397 4600**\n- إيميل: **info@5a-eg.com**\n- المقر الرئيسي: المستثمرين الجنوبية، التجمع الخامس، القاهرة الجديدة\n- مركز الخدمة: المنطقة الصناعية، ترعة الإسماعيلية، مسطرد، القاهرة\n\nتقدر تفتح صفحة التواصل كاملة من هنا: [تواصل / Contact](/contact.html)\n\nتحب نعمل لك عرض سعر لمولد أو معدة معينة؟ اكتب «عرض سعر» أو «موظف» عشان نوصلك بالفريق.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:50:13', NULL),
(112, 'en', 'Do you have the 2100 Global?', 'do you have the 2100 global', 'Yes — we supply the **Vactor 2100 Global** in Egypt. It’s the world’s most powerful combination sewer cleaner for international markets, with Modul-Flex debris bodies up to 15 yd³, JetRodder® high-pressure jetting (Jack Hammer action), and your choice of centrifugal or positive-displacement vacuum systems.\n\n[2100 Global – Vactor](/model.html?p=vactor-2100-global&lang=en)\n\nWhat line diameters, debris type and network depth are you working with? That lets me confirm the right vacuum/body configuration for you — or you can request a quotation directly.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:50:17', NULL),
(113, 'ar', 'مولدات ديزل مفتوحة صناعية KVA مناسب لشغل كتير يومي؟', 'مولدات ديزل مفتوحه صناعيه kva مناسب لشغل كتير يومي', 'أيوة، **مولدات الديزل المفتوحة (20–3000 kVA)** مصممة للشغل اليومي الثقيل:\n- قاعدة معدنية قوية مع عوازل اهتزاز\n- وصول كامل من كل الجوانب للصيانة السريعة\n- مبرد استوائي يتحمل حتى 50°م\n- محركات أصلية: Perkins, Cummins, Doosan, Develon, Volvo, Baudouin\n- كنترول DSE أو ComAp\n\n[تفاصيل وموديلات](/model.html?p=open-skid-diesel-generators&lang=ar)\n\n**إيه الحمل التقريبي بالـ kVA؟** عشان نرشح الموديل بالظبط ونعملك عرض سعر.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:50:23', NULL),
(114, 'ar', 'ايه خدمات بيع وإيجار المولدات عندكم؟', 'ايه خدمات بيع وايجار المولدات عندكم', 'عندنا **مولدات ديزل من 10 لـ 2,500 kVA** بموتورات أصلية (Perkins, Cummins, Hyundai, Volvo, Baudouin, Doosan/Develon) — للبيع أو للإيجار (20–1,000 kVA).  \nبنركبها **كانوبي، أوبن سكيد، كونتينر، أو موبايل ترايلر** حسب موقعك وطبيعة الشغل.  \nكمان بنعمل **عمرات شاملة، رفع كفاءة، تصنيع تانكات وقواعد وكبائن، وتركيبات كاملة** بفريقنا.\n\n[تفاصيل البيع والإيجار](/generators.html?lang=ar) · [نطاق العمل كامل](/power.html?lang=ar)\n\n**إيه القدرة اللي محتاجها (kVA)؟** أبعتلها لفريق العروض يجهزلك الكوتيشن.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:50:31', NULL),
(115, 'ar', 'أنظمة العوادم وكواتم الصوت والتهوية الصناعية مناسب لشغل كتير يومي؟', 'انظمه العوادم وكواتم الصوت والتهويه الصناعيه مناسب لشغل كتير يومي', 'أيوة، الأنظمة دي مصممة للشغل اليومي الثقيل:\n- كواتم صوت Critical grade بتقلل الضوضاء 25–35 dBA\n- بلوف استانلس مرنة بتتحمل التمدد الحراري والفيبرشن المستمر\n- عزل حراري (Ceramic blanket / Rockwool) مع كلادينج ألومنيوم\n- تركيب ميداني كامل (توجيه المسارات، تعليق بالسقف، اختراق الحوائط) على يد فنيين 5A&M\n- مصممة تحافظ على Backpressure منخفض داخل حدود الشركة المصنعة للمحرك\n\nمناسبة جداً لغرف مولدات بتشتغل فترات طويلة أو مواقع مفتوحة.\n\nتحب أطلبلك عرض سعر؟ أو تكتب «موظف» يكلمك المهندس المختص.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:50:42', NULL),
(116, 'ar', 'ايه الفرق بين مولدات ديزل مفتوحة صناعية KVA وغيره عندكم؟', 'ايه الفرق بين مولدات ديزل مفتوحه صناعيه kva وغيره عندكم', 'الفرق الجوهري هو **الهيكل الخارجي**:\n\n- **المفتوحة (Open Skid)**: محرك + مولد + كنترول على **قاعدة معدنية فقط**، بدون كابينة.  \n  → تركيب مرن، وصول كامل للصيانة، تكلفة أقل، لكن **صوت أعلى** ولا حماية من الطقس.  \n  [تفاصيل](/model.html?p=open-skid-diesel-generators&lang=ar)\n\n- **المظلة (Canopy)**: نفس المكونات داخل **كابينة عازلة صوت ومقاومة للطقس**.  \n  → هادئة (حتى 68 dBA @ 7m)، تحمي الماكينة، جاهزة للتشغيل الخارجي.  \n  [تفاصيل](/model.html?p=sound-proof-canopy-diesel-generators&lang=ar)\n\n- **الحاوية (Containerized)**: داخل **حاوية 20/40 قدم معزولة ومكيفة**، مصممة للمواقع القاسية والتشغيل المتوازي.  \n  [تفاصيل](/model.html?p=containerized-generators&lang=ar)\n\n- **المقطورة (Mobile Trailer)**: على **مقطورة قابلة للقطر** لنقل سريع بين المواقع.  \n  [تفاصيل](/model.html?p=mobile-trailer-generators&lang=ar)\n\n**إيه نوع الحمل والموقع؟** أحولك للنموذج الأنسب وأطلبلك عرض سعر.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:50:49', NULL),
(117, 'ar', 'عايز اعرف اكتر عن حلول البيئة', 'عايز اعرف اكتر عن حلول البييه', 'أهلاً بيك! عندنا في **5A&M** الوكالة الحصرية المعتمدة في مصر لمجموعة **Federal Signal Environmental Solutions**، وبنغطي ثلاث علامات رئيسية:\n\n- **Elgin** — مكانس طرق (ميكانيكية، هواء متجدد، شفط) بخبرة تتجاوز قرن.\n- **Vactor** — معدات تنظيف خطوط الصرف (شفط عالي التدفق + مياه عالية الضغط) مع إمكانية تخصيص.\n- **Guzzler** — معدات شفط صناعي ثقيلة.\n\nكل المعدات بتدعمها قطع غيار أصلية مخزنة محليًا وفرق خدمة ميدانية على مستوى الجمهورية.\n\n[اعرض المعدة](/environment.html?lang=ar)\n\nإيه نوع التطبيق اللي بتدور عليه؟ (كنس شوارع، صرف صحي، شفط صناعي)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:50:56', NULL),
(118, 'en', 'What are the specifications of the Custom Sound-Proof & Weatherproof Canopy?', 'what are the specifications of the custom sound proof weatherproof canopy', 'Based on our in-house fabrication capabilities, the **Custom Sound-Proof & Weatherproof Canopy** specifications include:\n\n- **Manufacturing:** In-house CNC sheet metal cutting, bending, and welding\n- **Acoustic Treatment:** High-density rockwool with perforated galvanized liner\n- **Surface Protection:** Multi-stage electrostatic polyester powder coating\n- **Hardware:** Stainless steel locks, hinges, and weather-sealed gasket doors\n- **Fabrication:** Entirely inside 5A&M workshop to client dimensions\n- **Access:** Ergonomic maintenance access doors with 180° swing radius\n- **Airflow:** Acoustic baffled air intake and discharge attenuation ducts\n- **Safety:** External emergency stop button and lockable fuel filling hatch\n\nThese canopies are built to your exact generator size and site requirements.  \n[Custom Sound-Proof & Weatherproof Canopy](/model.html?p=sound-proof-canopy&lang=en)\n\nWhat kVA rating or engine brand are you pairing it with? That helps us confirm the right fit and prepare a quotation.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:51:03', NULL),
(119, 'ar', 'عايز اعرف اكتر عن المعدات', 'عايز اعرف اكتر عن المعدات', 'عندنا ٣ مجموعات رئيسية بنورّدها وندعمها في مصر:\n\n- **المعدات البيئية** (Elgin, Vactor, Guzzler): كنس شوارع، تنظيف صرف صحي، شفط صناعي.  \n- **توليد الطاقة**: مولدات ديزل ١٠–٢٥٠٠ kVA (مصنّعة عندنا)، طاقة للإيجار، لوحات تحكم/تحويل، أعمال تصنيع.  \n- **قطع غيار أصلية**: محركات، مولدات، وحدات تحكم، فلاتر — مخزون دائم.\n\nتفاصيل كل مجموعة هنا: [المعدات](/equipment.html?lang=ar)\n\nإيه التطبيق اللي بتدور عليه بالظبط؟ (مثلاً: كنس شوارع، صرف صحي، شفط صناعي، أو مولد لحمل معيّن)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:51:14', NULL),
(120, 'ar', 'ليه اتعامل معاكم في صيانة المواقع وعقود الصيانة؟', 'ليه اتعامل معاكم في صيانه المواقع وعقود الصيانه', 'عندنا فريق خدمة ميدانية بيشرف على التركيب والتشغيل، بيشخص الأعطال في الموقع، وبيستجيب للطوارئ — مع عقود صيانة مجدولة (دورية، وقائية، تصحيحية) وقطع غيار وفلاتر أصلية من مخزوننا، ودعم مستمر طول العمر التشغيلي للمعدة.  \n[صيانة المواقع وعقود الصيانة](/maintenance.html?lang=ar)\n\nتحب نطلبلك عرض سعر لعقد صيانة يناسب معداتك؟ أو تكتب «موظف» عشان يكلمك حد من الفريق مباشرة.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:51:34', NULL),
(121, 'ar', 'احكيلي عن خدمات ما بعد البيع', 'احكيلي عن خدمات ما بعد البيع', 'عندنا **خدمات ما بعد البيع** شاملة لكل المعدات (مولدات، معدات ثقيلة، وحدات بيئية):\n\n- **فريق خدمة ميدانية** معتمد يغطي كل الجمهورية — تركيب، تشغيل، تشخيص أعطال، صيانة دورية/وقائية/تصحيحية، واستجابة طوارئ.\n- **عقود صيانة** مجدولة: نحدد المواعيد، نورّد القطع الأصلية، ونبقى جاهزين عشان المعدة تفضل شغالة.\n- **قطع غيار أصلية** من مخزوننا لماركات: Hyundai Infracore، Perkins، Cummins، Volvo، Develon، Elgin، Vactor، Guzzler، وفلاتر Develon/Fleetguard.\n- **دعم فني مستمر** طول العمر التشغيلي للمعدة.\n\n[خدمات ما بعد البيع](/aftersales.html?lang=ar) · [صيانة المواقع وعقود الصيانة](/maintenance.html?lang=ar) · [قطع الغيار الأصلية](/parts.html?lang=ar)\n\nتحب نعمل لك **عرض سعر** لصيانة أو قطع غيار؟ ابعت الموديل والرقم التسلسلي، أو اضغط زرّ «كلّم موظف» تحت عشان تكلم الفريق مباشرة.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:51:42', '2026-10-24 02:00:46'),
(122, 'en', 'Tell me about your Request a quote', 'tell me about your request a quote', 'Our **Request a Quote** page lets you send the details our team needs to prepare a formal quotation — no prices or delivery dates are shown online.\n\n**What you provide**\n- Name, phone, email (optional)  \n- Required power (kVA) or equipment type  \n- Project location & expected start date  \n- Any extra notes (load profile, site conditions, rental duration, etc.)\n\n**How it works**\n1. Fill the form → 2. Review the drafted request → 3. It opens in your email app to send.  \nOur sales team replies during Egyptian business hours with pricing, availability and lead time.\n\nYou can also add several items at once from the **Store** and submit a single quote request.\n\n[Request a quote](/quote.html?lang=en) · [Browse equipment & parts in the Store](/store.html?lang=en)\n\nWhat is the load (kVA) or the equipment you need?', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:52:04', NULL),
(123, 'en', 'Do you have the CANOPY TYPE GENERATORS KVA?', 'do you have the canopy type generators kva', 'Yes — we supply **Canopy Type Generators from 20 to 3000 kVA** with sound-proof acoustic canopies fabricated in-house, Tier-1 engines (Perkins, Cummins, Baudouin, Doosan, Develon, Volvo) and alternators (Stamford, Leroy-Somer), down to 68 dBA @ 7 m.  \n[CANOPY TYPE GENERATORS (20-3000) KVA](/model.html?p=sound-proof-canopy-diesel-generators&lang=en)\n\nWhat kVA rating do you need, and where will it run?', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:52:24', NULL),
(124, 'ar', 'عندي مزرعة ومحتاج طاقة للري', 'عندي مزرعه ومحتاج طاقه للري', 'أهلاً بيك! للري الزراعي بنرشح **مولدات ديزل بقدرات 10–2,500 kVA** بمحركات أصلية (Perkins, Cummins, Volvo…) — مصممة للعمل المستمر في ظروف الموقع.  \nعندنا كمان **تأجير من 20–1,000 kVA** لو محتاج حل مؤقت.  \n[تفاصيل البيع والإيجار](/generators.html?lang=ar)\n\n**إيه القدرة التقريبية اللي محتاجها (kVA)؟**  \n(لو عايز عرض سعر اكتب «عرض سعر» أو «موظف» عشان يكلمك الفريق).', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:52:33', NULL),
(125, 'ar', 'ليه اختار iMPACT بالذات؟', 'ليه اختار impact بالذات', '- **مدمجة وخفّة**: تشتغل في شوارع ضيقة ومواقع صعبة المناورة.  \n- **وحدة واحدة بتعمل الاتنين**: شفط إزاحة موجبة (Roots/Dresser) + ضخ مياه عالي الضغط (Jet Rodder) — بتوفّر ماكينة تانية.  \n- **تحكّم IntuiTouch**: شاشة واحدة بتدير الشفط والضخ والذراع الهيدروليكي (دوران 180°، وصول 5.4 م).  \n- **خزان مياه ألومنيوم 500 جالون** بضمان 10 سنين (اختياري ستانلس 750 جالون).  \n- **سعة حطام 3 ياردة³** (اختياري 5 ياردة³) — بتقلّل تفريغات النقل.  \n- **دعم 5A&M في مصر**: وكيل حصري Federal Signal، قطع غيار أصلية دائمة، خدمة موقع وتدريب.\n\nمناسبة جداً لفرق البلديات والمقاولين اللي محتاجين سرعة تنقل وتنظيف صرف/بيارات في مساحات ضيقة.\n\nتحب أطلبلك عرض سعر؟ أو تكتب «موظف» عشان يكلمك المهندس المختص؟  \n[تفاصيل iMPACT](/model.html?p=vactor-impact&lang=ar)', 'qwen', 'new', 'claim', 0, NULL, NULL, '2026-10-10 14:52:40', '2026-10-10 14:52:40'),
(126, 'ar', 'ايه مواصفات 2100i؟', 'ايه مواصفات 2100i', 'عندنا **Vactor 2100i** — وحدة مشتركة لتنظيف الصرف والضخ بمياه عالية الضغط، بتتحكم بنظام **IntuiTouch**.\n\n**المواصفات الرئيسية:**\n- **نظام الشفط:** مروحة هيدروستاتيكية (مرحلة واحدة أو اثنتين) **أو** بلور *Roots* إزاحة موجبة  \n  - تفريغ يصل **27 بوصة زئبق (685 مم)**  \n  - تدفق دخول حتى **5,000 CFM**\n- **صندوق المخلفات:** 5 – 15 ياردة مكعبة (3.8 – 11.5 م³)\n- **خزان المياه:** 1,000 – 1,500 جالون (3,785 – 5,678 لتر) ألومنيوم، **ضمان 10 سنين**\n- **طلمبة المياه:** Vactor Jet Rodder Multi-Flow، **60 – 100 GPM عند 2,000 – 3,000 PSI**\n- **بكرة الخرطوم:** 15 بوصة تلسكوبية، دوران 270°، حتى **800 قدم × 1 بوصة** (اختياري 1,000 قدم)\n- **الذراع (Boom):** هيدروليكي بالكامل، تحكم تناسبي، دوران 180° (اختياري RDB 1015)\n- **خرطوم الشفط:** قطر 7 أو 8 بوصة\n- **إعادة تدوير المياه:** متاح على موديل PD\n- **تصميم Modul-Flex:** الوحدات تركب حسب طبيعة الشغل\n\n[تفاصيل كاملة](/model.html?p=vactor-2100i&lang=ar)\n\n**إيه نوع الرواسب وأقطار الخطوط عندك؟** كده أقدر أؤكد إن 2100i هي الأنسب أو أرشّح موديل تاني.  \nتحب أطلبلك عرض سعر؟ أو تكتب «موظف» يكلمك مهندس مبيعات.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:53:09', NULL),
(127, 'ar', 'عايز عرض سعر على Pelican', 'عايز عرض سعر علي pelican', 'أهلاً بيك! عندنا **Pelican** من Elgin — مكنسة شوارع ميكانيكية 3 عجلات، رؤية 360°، حاوية 3.6 ياردة³، ونظام كنس قوي للمخلفات الكبيرة.\n\nعشان نطلعلك عرض سعر بالظبط، محتاج منك معلومة واحدة بس:\n- **إيه التطبيق / الموقع اللي هتشتغل فيه؟** (شوارع ضيقة، طرق رئيسية، منطقة صناعية…)\n\nلما تجهز المعلومة، تقدر تطلب العرض من المتجر مباشرة: [المتجر](/store.html?lang=ar)  \nأو تكتب «موظف» وأوصلك بالفريق فوراً.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:53:13', NULL),
(128, 'ar', 'بعد ما اشتري 2100 Global بتوفروا قطع غياره؟', 'بعد ما اشتري 2100 global بتوفروا قطع غياره', 'أيوة، بنوفّر قطع الغيار الأصلية لـ **Vactor 2100 Global** — بصفتنا الوكيل الحصري المعتمد في مصر، عندنا مخزون مخصص للقطع والمستهلكات، وبنلاقيلك القطعة بالموديل والرقم التسلسلي.\n\n[قطع غيار الوحدات البيئية](/parts.html?lang=ar)\n\nتحب تطلب عرض سعر لقطع معينة؟ أو تكتب «موظف» عشان يكلمك فريق القطع مباشرة.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:53:30', NULL),
(129, 'ar', 'ليه اختار مولدات ديزل مفتوحة صناعية KVA بالذات؟', 'ليه اختار مولدات ديزل مفتوحه صناعيه kva بالذات', 'المولدات المفتوحة (Open Skid) بتيجي على قاعدة معدنية قوية مع عوازل اهتزاز، من غير كابينة — فبالتالي:\n- **أرخص في السعر** من الموديلات المظللة أو المقطورة\n- **صيانة أسهل وأسرع** من كل الجهات\n- **مركبة على سكيد** مع نقاط رفع معتمدة للنقل والتركيب\n- محركات أصلية: Perkins, Cummins, Doosan, Develon, Volvo, Baudouin\n- كنترول DSE أو ComAp، ومبرد استوائي يتحمل حتى 50°م\n- مدى القدرة: **20–3000 kVA**\n\nمناسبة جداً لغرف مولدات مغطاة أو مواقع فيها حماية من العوامل الجوية.\n\n👉 [تفاصيل ومواصفات كاملة](/model.html?p=open-skid-diesel-generators&lang=ar)\n\n**إيه الحمل المطلوب بالكيفا (kVA)؟** عشان نرشح الموديل بالظبط ونعملك عرض سعر.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:53:56', NULL),
(130, 'ar', 'عايز اعرف تفاصيل عن مقطورة نقل وتثبيت المولدات الثقيلة', 'عايز اعرف تفاصيل عن مقطوره نقل وتثبيت المولدات الثقيله', 'عندنا **مقطورة نقل وتثبيت المولدات الثقيلة** — مصممة خصيصًا لنقل المولدات بين المواقع، بتصنيع ورشة 5A&M.\n\n**المواصفات الأساسية:**\n- **سعة التحميل:** من 1,500 كجم حتى 18,000 كجم GVW\n- **محاور:** مفرد، مزدوج، أو ثلاثي (torsion/leaf heavy-duty)\n- **فرامل:** ميكانيكية overrun أو هوائية pneumatic مع كابل أمان\n- **إضاءة وأمان:** LED مطابقة للطرق، عواكس، سلاسل أمان\n- **هيكل:** كمر فولاذ ثقيل يتحمل المسارات الصحراوية\n- **تثبيت:** عجلة أمامية قابلة للتعديل + 4 جاكات زاوية ثقيلة\n- **إضافات:** عجلة احتياطية، واقيات طين، سلة كابلات\n- **تخصيص:** تُبنى بمقاسات المولد وتوزيع وزنه بالضبط\n\n[مقطورة نقل وتثبيت المولدات الثقيلة](/model.html?p=genset-trailer&lang=ar)\n\n**إيه قدرة المولد (kVA) اللي هتنقله؟** عشان نطابق المقطورة بالظبط — أو تقدر تطلب عرض سعر/تكتب «موظف» للتواصل مع الفريق.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:54:00', NULL),
(131, 'ar', 'ايه مواصفات قطع غيار المحركات الأصلية؟', 'ايه مواصفات قطع غيار المحركات الاصليه', 'عندنا **قطع غيار محركات أصلية 100%** معتمدة من المصنّعين (OEM) ومخزّنة في مستودع 5A&M بالقاهرة لتسليم طوارئ سريع.\n\n**الماركات المدعومة:** Cummins, Perkins, Baudouin, Doosan, Develon, Volvo  \n**المنظومات:** مكابس، بطانات أسطوانات، جوان، تيربو، حاقنات وقود، مضخات مياه  \n**الضمان:** ضمان مصنّع أصلي — يحافظ على كفاءة استهلاك الوقود ويمنع الأعطال المبكرة  \n**الدعم الفني:** مهندسو عمرة محركات 5A&M متاحون للمساعدة\n\n[قطع غيار المحركات الأصلية](/model.html?p=engine-parts&lang=ar)\n\n**إيه الموديل والرقم التسلسلي للمحرك؟** أبعتله التوافر والسعر على طول.  \n(لو عايز تتكلم مع فريق المبيعات اضغط زرّ «كلّم موظف» تحت أو "agent")', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:54:27', '2026-10-24 02:00:46'),
(132, 'en', 'What do you offer for Site maintenance & maintenance contracts?', 'what do you offer for site maintenance maintenance contracts', 'We provide **on-site periodic, preventive, and corrective maintenance** under a contract that keeps your equipment in our care for its entire operating life.\n\n**What’s included**\n- Scheduled periodic maintenance visits  \n- Preventive maintenance to catch faults before they stop the set  \n- Corrective maintenance and emergency breakdown response  \n- Experienced field service team at your site  \n- Parts supply and on-call support  \n\n[Site maintenance & maintenance contracts](/maintenance.html?lang=en)\n\nWhat is the generator rating (kVA) and site location so we can prepare a quotation?', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:54:29', NULL),
(133, 'ar', 'ايه الخطوات من الطلب لحد التسليم؟', 'ايه الخطوات من الطلب لحد التسليم', 'الخطوات باختصار:\n1. **تحدد الحاجة** (الحمل بالـ kVA، نوع المعدة، موقع التشغيل).\n2. **تبعت طلب عرض سعر** من [صفحة الطلب](/quote.html?lang=ar) أو تكتب «موظف»/«agent» عشان نكمّل معاك.\n3. **فريق المبيعات يراجع التفاصيل** ويرسل العرض الفني والمالي.\n4. **بعد الموافقة** بنبدأ التصنيع/التجهيز (لو مولدات: قاعدة، خزان، كابينة — عندنا [تصنيع وتجهيز](/fabrication.html?lang=ar)).\n5. **نركب ونشغّل في الموقع** على يد [فريق الخدمة الميدانية](/maintenance.html?lang=ar).\n6. **التسليم والاستلام** مع تشغيل تجريبي وتدريب سريع.\n7. **دعم ما بعد البيع** مستمر: صيانة دورية، طوارئ، وقطع غيار أصلية — [تفاصيل](/aftersales.html?lang=ar).\n\n**محتاج نبدأ؟** ابعت لي الحمل (kVA) ونوع التطبيق، أو اضغط [اطلب عرض سعر](/quote.html?lang=ar).', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:54:33', NULL),
(134, 'ar', 'قطع غيار المحركات الأصلية مناسب لشغل كتير يومي؟', 'قطع غيار المحركات الاصليه مناسب لشغل كتير يومي', 'أيوة، قطع غيار المحركات الأصلية من 5A&M مصممة للشغل اليومي الثقيل — مخزنة في مخزن القاهرة للتصرف السريع، ومغطاة بضمان المصنع، وبتساعد تمنع الأعطال المفاجئة وتحافظ على كفاءة استهلاك الوقود. الماركات المدعومة: Cummins, Perkins, Baudouin, Doosan, Develon, Volvo.\n\nتحب أطلبلك عرض سعر لقطع معينة؟ ممكن تبعتلنا الموديل والرقم التسلسلي للمحرك، أو تكتب «موظف» عشان يكلمك فريق المبيعات.', 'qwen', 'new', 'claim', 0, NULL, NULL, '2026-10-10 14:54:38', '2026-10-10 14:54:38'),
(135, 'ar', 'عايز اعرف تفاصيل عن iMPACT', 'عايز اعرف تفاصيل عن impact', 'عندنا **Vactor iMPACT** — وحدة مشتركة مدمجة لتنظيف الصرف والضخ بمياه عالية الضغط، مناسبة للأماكن الضيقة.\n\n**المواصفات الأساسية:**\n- **تصميم:** Vactor Modul-Flex الحصري\n- **نظام الشفط:** Roots / Dresser إزاحة موجبة — حتى 15 بوصة زئبق، 2,400 CFM\n- **الذراع الهيدروليكي:** تحكم تناسبي، دوران 180°، مدى 5.4 م\n- **خرطوم الشفط:** 6 بوصة (152 مم)\n- **سعة جسم الحطام:** 3 ياردة³ (2.3 م³) — متاح 5 ياردة³ (3.8 م³)\n- **خزان المياه:** 500 جالون (1,893 لتر) ألومنيوم بضمان 10 سنوات — متاح 750 جالون ستانلس ستيل\n- **مضخة المياه:** Vactor Jet Rodder Multi-Flow\n- **أداء الضخ:** 40 GPM عند 2,500 PSI — أو 35 GPM عند 3,000 PSI اختياري\n- **التشغيل:** تدفق مستمر، تحكم بنظام IntuiTouch\n\n[تفاصيل iMPACT](/model.html?p=vactor-impact&lang=ar)\n\nتحب تطلب عرض سعر؟ ابعتلي القدرة المطلوبة وموقع المشروع، أو اضغط زرّ «كلّم موظف» تحت عشان يكلمك الفريق مباشرة.', 'qwen', 'new', 'claim', 0, NULL, NULL, '2026-10-10 14:55:18', '2026-10-24 02:00:46'),
(136, 'en', 'Do you have the Industrial Filtration Kits?', 'do you have the industrial filtration kits', 'Yes — we supply **Industrial Filtration Kits** (Fleetguard & Develon genuine) covering fuel water separators, lube oil, heavy-duty air intake and coolant filters, packaged in scheduled service-interval kits for fast turnaround.  \n[Industrial Filtration Kits](/model.html?p=filters&lang=en)\n\nWhat equipment or engine model are they for? I’ll confirm the exact kit and send a quotation.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:55:20', NULL),
(137, 'en', 'Do you offer generator maintenance?', 'do you offer generator maintenance', 'Yes. 5A&M provides **full after-sales service** including:\n\n- Preventive & corrective maintenance contracts  \n- Genuine spare parts (engines, alternators, controllers, filters, etc.)  \n- Field service by factory-trained technicians  \n- Load-bank testing, overhauls & efficiency upgrades  \n\nWe support every set we supply — Perkins, Cummins, Doosan, Develon, Volvo, Baudouin — plus Stamford/Leroy-Somer alternators and DSE/ComAp controllers.\n\nTo size the right service plan, what is the **kVA rating and typical running hours** of your generator(s)?  \n(Or tap the “Talk to a person” button below to speak with the service team directly.)', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:55:40', '2026-10-25 15:18:04'),
(138, 'ar', 'مقطورة نقل وتثبيت المولدات الثقيلة يناسب ايه؟', 'مقطوره نقل وتثبيت المولدات الثقيله يناسب ايه', 'مقطورة نقل وتثبيت المولدات الثقيلة مصممة خصيصاً لـ:\n- نقل المولدات بين مواقع العمل المختلفة\n- تثبيت المولدات الثقيلة بأمان\n- التحمل في ظروف الصحراء والطرق الوعرة\n\n**المواصفات الرئيسية:**\n- سعة تحميل: 1,500 كجم حتى 18,000 كجم GVW\n- محاور: مفرد، مزدوج، أو ثلاثي (torsion/leaf)\n- فرامل: ميكانيكية أو هوائية مع كابل أمان\n- إضاءة LED مطابقة للطرق السريعة\n- مصنعة من كمرات فولاذية ثقيلة\n- رافعات تسوية زاوية، عجلة جوك أمامية، سلة كابلات\n\nمناسبة للمولدات الكبيرة اللي بتتنقل كتير بين المواقع (مشاريع بناء، محاجر، بترول).\n\nإيه حجم المولد اللي عايز تنقله؟ (الوزن أو الكيفا) عشان أقدر أؤكد إنها تناسبك.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:55:46', NULL),
(139, 'ar', 'بعد ما اشتري Whirlwind بتوفروا قطع غياره؟', 'بعد ما اشتري whirlwind بتوفروا قطع غياره', 'أيوة، إحنا الوكيل الحصري لـ **Elgin** في مصر وبنوفّر كل قطع الغيار الأصلية لـ **Whirlwind** من المخزن في القاهرة — فلاتر، فرش، مضخات، منظومة الشفط والهواء، وكل المستهلكات.  \nبنرد عليك بالتوافر والسعر بمجرد ما تبعتلنا **الموديل والرقم التسلسلي** للمعدة.\n\n[قطع غيار الوحدات البيئية](/parts.html?lang=ar#environmental-parts)  \n[خدمات ما بعد البيع](/aftersales.html?lang=ar)\n\nتحب تطلب عرض سعر لقطعة معينة؟ ابعت الموديل والسيريال ونكمل.', 'qwen', 'new', NULL, 0, NULL, NULL, '2026-10-10 14:55:55', NULL),
(140, 'ar', 'ايه هو Crosswind؟', 'ايه هو crosswind', 'Crosswind — Elgin: تقدم مكانس الجين بتقنية الهواء المتجدد (Regenerative Air) أداءً قويًا ومرونة عالية في أعمال الكنس والتنظيف.\r\nتتميز الجين Crosswind بكفاءة عالية في تنظيف المساحات المرصوفة الواسعة، مثل الشوارع ومواقف السيارات ومدارج المطارات، مع قدرة ممتازة على المناورة بفضل تركيبها على شاسيه قصير.\r\nالمميزات:\r\n- وحدة  شفط عالية السرعة بتسع ريش مع هيكل مبطن بالمطاط لمتانة أعلى وعمر تشغيلي أطول.\r\n- نظام تبطين خزان المخلفات LifeLiner لإطالة عمر الخزان، وتعزيز متانته، وتسهيل عملية التفريغ.\r\n- مسار كنس بعرض 12 قدمًا (3,658 مم) مع رأس كنس بعرض 90 بوصة (2,286 مم) وفرشتين جانبيتين بنظام هيدروليكي مقاس 42 بوصة (1,067 مم).\r\n-  أداء شفط مُحسّن لالتقاط المخلفات الخفيفة وكبيرة الحجم بكفاءة، بما في ذلك المخلفات بجوار الأرصفة.\n[صفحة Crosswind](/model.html?p=elgin-crosswind&lang=ar)\nتحب نجهّزلك عرض سعر؟ اضغط زرّ «كلّم موظف» تحت أو املأ طلب عرض السعر من الموقع.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(141, 'ar', 'ايه مواصفات Crosswind؟', 'ايه مواصفات crosswind', 'دي المواصفات الأساسية لـ Crosswind:\n- تقنية الكنس: هواء متجدد — دائرة هواء مغلقة\n- مسار الكنس — رأس الشفط فقط: 2,286 مم\n- مسار الكنس — رأس وفرشاة واحدة: 2,971 مم\n- مسار الكنس — رأس وفرشاتان: 3,658 مم\n- سعة حوض المخلفات: 6 م³\n- زاوية التفريغ: 50°\n- رفع الحوض: هيدروليكي — اسطوانة تلسكوبية على مرحلتين\n- فاصل الأتربة: طرد مركزي ذاتي التنظيف\n- محرك الشاسيه: Cummins ISB 6.7 — 6 سلندر تيربو ديزل\n- قدرة المحرك: 200 حصان (150 kW) عند 2400 لفة/دقيقة\n[صفحة Crosswind](/model.html?p=elgin-crosswind&lang=ar)\nتحب نجهّزلك عرض سعر؟ اضغط زرّ «كلّم موظف» تحت أو املأ طلب عرض السعر من الموقع.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(142, 'ar', 'عندكم كتالوج لـ Crosswind؟', 'عندكم كتالوج ل crosswind', 'أيوه، ملفات Crosswind متاحة للتحميل:\n- [ورقة مواصفات Crosswind¹ (PDF)](/assets/img/elgin/crosswind/spec-sheet.pdf)\n- [كتيّب Crosswind 1 (PDF)](/assets/img/elgin/crosswind/brochure.pdf)\n- [ورقة المواصفات — إصدار FSX (PDF)](/assets/img/elgin/crosswind/spec-sheet-fsx.pdf)\n- [ورقة التعريف — إصدار GRS (PDF)](/assets/img/elgin/crosswind/sell-sheet-grs.pdf)\n[صفحة Crosswind](/model.html?p=elgin-crosswind&lang=ar)', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', NULL),
(143, 'en', 'What is the Crosswind?', 'what is the crosswind', 'Crosswind — Elgin: Elgin Regenerative Air Sweepers deliver powerful performance and versatility across a wide range of sweeping and cleaning applications.\r\nThe Elgin Crosswind efficiently cleans large, paved areas such as streets, parking lots, and airport runways, while its short-wheelbase truck chassis provides excellent maneuverability.\r\nFeatures:\r\n- 9-vane high-velocity turbine fan with a rubber-lined housing for enhanced durability and extended service life.\r\n- LifeLiner hopper liner system for extended hopper life, durability, and smoother dumping.\r\n- 12-ft. (3,658 mm) sweep path with a 90-in. (2,286 mm) pickup head and dual 42-in. (1,067 mm) hydraulic side brooms.\r\n- Enhanced vacuum performance for efficient pickup of light and bulky debris, including curbside areas.\n[Crosswind page](/model.html?p=elgin-crosswind&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(144, 'en', 'What are the advantages of the Crosswind?', 'what are the advantages of the crosswind', 'What sets the Crosswind apart:\n- Closed-loop regenerative air system with zero exhaust dust emission\n- Trapped particulate pick-up from porous and textured asphalt\n- Large 8-yard hopper allows extended shifts without frequent dumping\n- Dual trailing-arm gutter brooms with tilt adjustment\n[Crosswind page](/model.html?p=elgin-crosswind&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(145, 'en', 'Do you have a brochure for the Crosswind?', 'do you have a brochure for the crosswind', 'Yes, files for the Crosswind:\n- [Crosswind¹ spec sheet (PDF)](/assets/img/elgin/crosswind/spec-sheet.pdf)\n- [Crosswind 1 brochure (PDF)](/assets/img/elgin/crosswind/brochure.pdf)\n- [Spec sheet — FSX version (PDF)](/assets/img/elgin/crosswind/spec-sheet-fsx.pdf)\n- [Sell sheet — GRS version (PDF)](/assets/img/elgin/crosswind/sell-sheet-grs.pdf)\n[Crosswind page](/model.html?p=elgin-crosswind&lang=en)', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', NULL),
(146, 'ar', 'Whirlwind ده ايه؟', 'whirlwind ده ايه', 'Whirlwind — Elgin: أحدثت الجين Whirlwind نقلة نوعية في أداء مكانس الشفط المثبتة على الشاحنات، بفضل تصميمها المتطور ومرونتها العالية. ويجمع تصميمها منخفض الصيانة وبين مسار كنس واسع وقاعدة عجلات قصيرة، مما يوفر قدرة فائقة على المناورة والتكيف مع مختلف التطبيقات.\r\nمنذ عام 1969، تواصل Whirlwind ريادتها في مجال مكانس الشفط، بفضل فوهة الشفط الفريدة وتصميمها القوي والمتين، لتوفر أداءً موثوقًا في مختلف تطبيقات تنظيف وصيانة الشوارع.\r\nالمميزات:\r\n- وحدة شفط عالية السرعة ذات تسع ريش مصنوعة من فولاذ Hardox لمتانة عالية وتدفق هواء قوي.\r\n- تدفق هواء عالي الحجم والسرعة لالتقاط المخلفات بكفاءة من المرور الأول.\r\n- فوهة شفط مقاومة للتآكل مقاس 32 بوصة (813 مم) لتنظيف أكثر كفاءة بجوار الأرصفة.\r\n- خزان مخلفات عالي السعة 8 ياردة³ (6 م³) مع حواجز من الفولاذ المقاوم للتآكل لتحميل المخلفات بكفاءة والاستفادة القصوى من السعة.\r\n- خزان مخلفات متين بجدران من فولاذ 10  درجات وأرضية بسُمك ¼ بوصة (6.35 مم) وزاوية تفريغ 50° لتفريغ سريع وكامل وسهولة التنظيف.\n[صفحة Whirlwind](/model.html?p=elgin-whirlwind&lang=ar)\nلو حابب التفاصيل كاملة أو عرض سعر، اضغط زرّ «كلّم موظف» تحت.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(147, 'ar', 'عايز المواصفات الفنية لـ Whirlwind', 'عايز المواصفات الفنيه ل whirlwind', 'دي المواصفات الأساسية لـ Whirlwind:\n- تقنية الكنس: شفط خالص — سحب مباشر\n- عرض فوهة الشفط: 813 مم\n- مسار الكنس — فوهة وفرشاة امتداد: 1,981 مم\n- مسار الكنس — الحد الأقصى: 3,658 مم\n- قطر فرشاة الامتداد: 406 مم\n- سعة حوض المخلفات: 6 م³\n- زاوية التفريغ: 50°\n- زاوية أرضية الحوض: 10°\n- رفع الحوض: اسطوانة هيدروليكية مزدوجة الفعل\n- المحرك المساعد: 4.5 لتر — 74 حصان (55 kW) عند 2400 لفة/دقيقة\n[صفحة Whirlwind](/model.html?p=elgin-whirlwind&lang=ar)\nلو حابب التفاصيل كاملة أو عرض سعر، اضغط زرّ «كلّم موظف» تحت.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(149, 'en', 'Tell me about the Whirlwind', 'tell me about the whirlwind', 'Whirlwind — Elgin: The Elgin Whirlwind has revolutionized truck-mounted vacuum sweeping performance with its advanced design and exceptional flexibility. Its low-maintenance design combines a wide sweeping path with a short wheelbase, providing outstanding maneuverability and versatility across a wide range of applications.\r\nSince 1969, Whirlwind has remained at the forefront of the vacuum sweeping market, featuring a unique vacuum nozzle and robust, durable construction that delivers dependable performance across a variety of street cleaning and maintenance applications.\r\nFeatures:\r\n-High-velocity 9-vane Blower with Hardox® steel vanes. \r\n-High-volume, high-velocity airflow for efficient one-pass pickup.\r\n-32-inch (813 mm) abrasion-resistant suction nozzle for improved curbside cleaning.\r\n-8 yd³ (6 m³) high-capacity hopper with abrasion-resistant steel deflectors for efficient debris loading and maximum capacity utilization.\r\n-hopper with 10-gauge steel walls, a ¼-inch (6.35 mm) floor, and a 50° dump angle for fast, complete unloading and easy cleanup.\n[Whirlwind page](/model.html?p=elgin-whirlwind&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(150, 'en', 'Technical specs for the Whirlwind?', 'technical specs for the whirlwind', 'Key specifications of the Whirlwind:\n- Sweeping technology: Pure vacuum — direct suction\n- Suction nozzle width: 813 mm (32 in)\n- Sweep path — nozzle + extension broom: 1,981 mm (78 in)\n- Sweep path — maximum: 3,658 mm (144 in)\n- Extension broom diameter: 406 mm (16 in)\n- Hopper volume: 6 m³ (8 cu yd)\n- Dump angle: 50°\n- Hopper floor angle: 10°\n- Hopper lifting: Double-acting hydraulic cylinder\n- Auxiliary engine: 4.5 L — 74 hp (55 kW) @ 2400 rpm\n[Whirlwind page](/model.html?p=elgin-whirlwind&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(151, 'en', 'Why choose the Whirlwind?', 'why choose the whirlwind', 'What sets the Whirlwind apart:\n- High-velocity vacuum pick-up for dense sand and debris\n- Wide sweep path with short wheelbase for tight urban navigation\n- Articulating side brooms with in-cab tilt control\n- Heavy-duty abrasion-resistant stainless steel hopper\n[Whirlwind page](/model.html?p=elgin-whirlwind&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(152, 'en', 'When should I choose the Whirlwind?', 'when should i choose the whirlwind', 'The Whirlwind fits:\n- Municipal roads and highways\n- Urban arterial thoroughfares\n- Construction site clean-up\n- Industrial compounds\n[Whirlwind page](/model.html?p=elgin-whirlwind&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(153, 'en', 'Is there a datasheet for the Whirlwind?', 'is there a datasheet for the whirlwind', 'Yes, files for the Whirlwind:\n- [Whirlwind spec sheet (PDF)](/assets/img/elgin/whirlwind/spec-sheet.pdf)\n- [Whirlwind brochure (PDF)](/assets/img/elgin/whirlwind/brochure.pdf)\n[Whirlwind page](/model.html?p=elgin-whirlwind&lang=en)', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', NULL),
(154, 'ar', 'احكيلي عن Pelican', 'احكيلي عن pelican', 'Pelican — Elgin: تتمتع شركة الجين بخبرة تتجاوز قرنًا في تصنيع معدات كنس الشوارع، وتقدم مجموعة متكاملة من المكانس، تشمل الطرازات الميكانيكية، والهواء المتجدد، والشفط، مع التزامها بتقديم أفضل مستويات الخدمة والدعم لعملائها.\r\nتُعد بلكان مكنسة ميكانيكية ثلاثية العجلات، مبنية على أحد أقدم تصميمات مكانس الشوارع، والذي شهد تطويرًا مستمرًا منذ عام 1914 ليلبي أعلى معايير الكفاءة والأداء.\r\nوتجمع Pelican بين سهولة المناورة، ووضوح الرؤية، والكفاءة التشغيلية، وسهولة الصيانة، إلى جانب نظام كنس قوي قادر على التعامل بكفاءة مع المخلفات كبيرة الحجم والمتراكمة، مع إمكانية التفريغ في مسار واحد.\r\nالمميزات :\r\nرؤية شاملة بزاوية 360° للمشغل لتعزيز الأمان وسهولة التشغيل\r\nتوجيه خلفي يوفر قدرة استثنائية على المناورة في المساحات الضيقة.\r\nحاوية أمامية متغيرة الارتفاع للتفريغ بسعة 3.6 ياردة³ (2.8 م³).\r\nسير ناقل Chevron حصري من الجين مصمم لتحقيق كفاءة عالية في جمع ونقل المخلفات.\r\nسهولة الوصول إلى معظم نقاط الصيانة.\r\nعدادات ومؤشرات داخل كابينة القيادة وخارجها لمراقبة مستويات السوائل.\n[صفحة Pelican](/model.html?p=elgin-pelican&lang=ar)\nعايز عرض سعر على المواصفات دي؟ اضغط زرّ «كلّم موظف» تحت وفريق المبيعات هيتواصل معاك.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(155, 'ar', 'Pelican مواصفاته ايه؟', 'pelican مواصفاته ايه', 'دي المواصفات الأساسية لـ Pelican:\n- تقنية الكنس: فرشاة ميكانيكية مع حفّار عمودي\n- مسار الكنس — فرشاة جانبية واحدة: 2,438 مم\n- مسار الكنس — فرشاتان جانبيتان: 3,048 مم\n- سعة حوض المخلفات: 2.8 م³\n- أقصى ارتفاع تفريغ: 2,896 مم\n- زمن إمالة الحوض: 17 ثانية\n- قدرة الرفع التصميمية: 4,080 كجم\n- التفريغ: أمامي — قياسي\n- قدرة المحرك: 99 حصان (74 kW) عند 2500 لفة/دقيقة\n- سعة خزان الوقود: 132.5 لتر\n[صفحة Pelican](/model.html?p=elgin-pelican&lang=ar)\nعايز عرض سعر على المواصفات دي؟ اضغط زرّ «كلّم موظف» تحت وفريق المبيعات هيتواصل معاك.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(156, 'ar', 'عندكم كتالوج لـ Pelican؟', 'عندكم كتالوج ل pelican', 'أيوه، ملفات Pelican متاحة للتحميل:\n- [ورقة مواصفات Pelican (PDF)](/assets/img/elgin/pelican/spec-sheet.pdf)\n- [كتيّب Pelican 2026 (PDF)](/assets/img/elgin/pelican/brochure.pdf)\n- [كتيّب Pelican للتطبيقات الصناعية (PDF)](/assets/img/elgin/pelican/industrial-brochure.pdf)\n- [ورقة نظام Waterless (PDF)](/assets/img/elgin/pelican/waterless-sell-sheet.pdf)\n- [ورقة مواصفات Eco-Infused (PDF)](/assets/img/elgin/pelican/spec-sheet-ecoinfused.pdf)\n- [لوحة الوصول السريع للتنظيف (PDF)](/assets/img/elgin/pelican/quick-clean-panel.pdf)\n[صفحة Pelican](/model.html?p=elgin-pelican&lang=ar)', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', NULL),
(157, 'en', 'What is the Pelican?', 'what is the pelican', 'Pelican — Elgin: The Elgin Pelican broom sweeper is a three-wheel mechanical sweeper based on one of the original street sweeper designs, which has been continuously improved since 1914, meeting the highest sweeper standards. Maneuverability, visibility, economy, serviceability, and single-lane dumping with a sweep system that easily handles heavily compacted dirt and bulky debris are\r\nFeatures:\r\n• Market leader offering 360 degrees of operator visibility.\r\n• Rear steer for outstanding maneuverability.\r\n• Front mounted, variable high dump 3.6 yd3 (2.8 m3) hopper.\r\n• Elgin exclusive chevron conveyor belt.\r\n• Access to service points is simple with most accessible from ground level.\r\n• The unit is equipped with a combination of in-cab and site gauges to monitor.\n[Pelican page](/model.html?p=elgin-pelican&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(158, 'en', 'What are the advantages of the Pelican?', 'what are the advantages of the pelican', 'What sets the Pelican apart:\n- Unmatched turning radius for narrow residential and downtown streets\n- Front-mounted variable-height dump directly into standard dump trucks\n- Heavy-duty chevron-belt conveyor with no-jam reversible action\n- Full visibility panoramic cab engineered for driver safety\n[Pelican page](/model.html?p=elgin-pelican&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(159, 'en', 'What is the Pelican used for?', 'what is the pelican used for', 'The Pelican fits:\n- Historic & dense urban quarters\n- Residential neighbourhoods\n- Curb and gutter maintenance\n- Compacted sand and gravel collection\n[Pelican page](/model.html?p=elgin-pelican&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(160, 'en', 'Do you have a brochure for the Pelican?', 'do you have a brochure for the pelican', 'Yes, files for the Pelican:\n- [Pelican export spec sheet (PDF)](/assets/img/elgin/pelican/spec-sheet.pdf)\n- [Pelican brochure 2026 (PDF)](/assets/img/elgin/pelican/brochure.pdf)\n- [Pelican industrial brochure (PDF)](/assets/img/elgin/pelican/industrial-brochure.pdf)\n- [Waterless Pelican sell sheet (PDF)](/assets/img/elgin/pelican/waterless-sell-sheet.pdf)\n- [Eco-Infused spec sheet (PDF)](/assets/img/elgin/pelican/spec-sheet-ecoinfused.pdf)\n- [Quick-Clean access panel (PDF)](/assets/img/elgin/pelican/quick-clean-panel.pdf)\n[Pelican page](/model.html?p=elgin-pelican&lang=en)', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', NULL),
(161, 'ar', 'ايه هو 2100i؟', 'ايه هو 2100i', '2100i — Vactor: المرجع العالمي لوحدات تنظيف الصرف المشتركة، تجمع بين شفط قوي بالإزاحة الموجبة وضخ مائي عالي الضغط، بتحكّم عبر نظام IntuiTouch.\n[صفحة 2100i](/model.html?p=vactor-2100i&lang=ar)\nتحب نجهّزلك عرض سعر؟ اضغط زرّ «كلّم موظف» تحت أو املأ طلب عرض السعر من الموقع.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(162, 'ar', 'ايه مزايا 2100i؟', 'ايه مزايا 2100i', 'أهم اللي يميّز 2100i:\n- تصميم Modul-Flex الحصري: الوحدات تُرتَّب حسب طبيعة الشغل، مش العكس\n- تحكّم IntuiTouch بشاشة تدور على قوس ⁦90°⁩، مع ذراع تحكّم (جويستيك) لبكرة الخرطوم والذراع\n- مضخة Jet Rodder Multi-Flow: تدفّق مستمر أو نبض Jack Hammer، محمية من التشغيل الجاف لمدة ⁦30⁩ دقيقة\n- ذراع الانتشار السريع RDB 1015 يمتد ⁦10⁩ أقدام ويُنزل ⁦15⁩ قدماً من الخرطوم داخل الغرفة\n- إعادة تدوير المياه بتسترجع مياه الضخ في الموقع، فتقلّ مرّات إعادة ملء الخزان كتير\n- خزانات مياه ألومنيوم بضمان ⁦10⁩ سنوات\n[صفحة 2100i](/model.html?p=vactor-2100i&lang=ar)\nتحب نجهّزلك عرض سعر؟ اضغط زرّ «كلّم موظف» تحت أو املأ طلب عرض السعر من الموقع.', 'facts', 'new', 'claim', 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(163, 'ar', 'ممكن بروشور 2100i؟', 'ممكن بروشور 2100i', 'أيوه، ملفات 2100i متاحة للتحميل:\n- [بروشور ⁦2100i⁩ ⁦2025⁩ (PDF)](/assets/img/vactor/2100i/brochure.pdf)\n- [ذراع الانتشار السريع ⁦RDB 1015⁩ (PDF)](/assets/img/vactor/2100i/rdb-1015.pdf)\n[صفحة 2100i](/model.html?p=vactor-2100i&lang=ar)', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', NULL),
(164, 'en', 'Tell me about the 2100i', 'tell me about the 2100i', '2100i — Vactor: The global benchmark for combination sewer cleaners, pairing powerful positive-displacement vacuum recovery with high-pressure jetting operated via IntuiTouch controls.\n[2100i page](/model.html?p=vactor-2100i&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(165, 'en', 'Technical specs for the 2100i?', 'technical specs for the 2100i', 'Key specifications of the 2100i:\n- Air mover: Single or dual-stage hydrostatic fan, or Roots positive-displacement blower\n- Vacuum rating (PD): Up to 27 in (685 mm) Hg\n- Inlet volume (PD): Up to 5,000 CFM\n- Debris body capacity: 5 – 15 cu yd (3.8 – 11.5 m³)\n- Water tank capacity: 1,000 – 1,500 gal (3,785 – 5,678 L) aluminium, 10-year warranty\n- Water pump: Vactor Jet Rodder Multi-Flow, 60 – 100 gpm at 2,000 – 3,000 psi\n- Hose reel: 15 in telescope, 270° rotation, 800 ft × 1 in (244 m) — up to 1,000 ft (305 m)\n- Boom: Fully hydraulic, proportional controls, 180° rotation; RDB 1015 optional\n- Pickup hose: 7 in or 8 in diameter\n- Water recycling: Available on the PD model\n[2100i page](/model.html?p=vactor-2100i&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(166, 'en', 'Why choose the 2100i?', 'why choose the 2100i', 'What sets the 2100i apart:\n- Exclusive Modul-Flex design: modules configured around the job, not the other way round\n- IntuiTouch controls with a screen that swivels on a 90° arc, plus joystick hose-reel and boom control\n- Jet Rodder Multi-Flow pump: continuous flow or Jack Hammer action, run-dry protected for 30 minutes\n- RDB 1015 Rapid Deployment Boom telescopes 10 ft out and pays 15 ft of hose down the manhole\n- Water recycling recovers jetting water on site, so the tank is refilled far less often\n- Aluminium water tanks carrying a 10-year warranty\n[2100i page](/model.html?p=vactor-2100i&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(167, 'en', 'When should I choose the 2100i?', 'when should i choose the 2100i', 'The 2100i fits:\n- Municipal sanitary sewer mains\n- Stormwater culverts and catch basins\n- Utility daylighting and slot trenching\n- Emergency water-main break remediation\n[2100i page](/model.html?p=vactor-2100i&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(168, 'en', 'Is there a datasheet for the 2100i?', 'is there a datasheet for the 2100i', 'Yes, files for the 2100i:\n- [2100i brochure 2025 (PDF)](/assets/img/vactor/2100i/brochure.pdf)\n- [RDB 1015 rapid deployment boom (PDF)](/assets/img/vactor/2100i/rdb-1015.pdf)\n[2100i page](/model.html?p=vactor-2100i&lang=en)', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', NULL),
(169, 'ar', 'iMPACT ده ايه؟', 'impact ده ايه', 'iMPACT — Vactor: وحدة مشتركة مدمجة لتنظيف الصرف بنفس القوة: شفط بالإزاحة الموجبة، وضخ مياه بضغط عالي بطلمبة Jet Rodder، وتحكّم عبر نظام IntuiTouch، مع قدرة مناورة للشغل في الأماكن الضيقة.\n[صفحة iMPACT](/model.html?p=vactor-impact&lang=ar)\nلو حابب التفاصيل كاملة أو عرض سعر، اضغط زرّ «كلّم موظف» تحت.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(170, 'ar', 'عايز المواصفات الفنية لـ iMPACT', 'عايز المواصفات الفنيه ل impact', 'دي المواصفات الأساسية لـ iMPACT:\n- التصميم: تصميم Modul-Flex الحصري من Vactor\n- مولّد الشفط: إزاحة موجبة Roots / Dresser\n- قدرة الشفط: حتى 15 بوصة (381 مم) زئبق\n- حجم السحب: حتى 2,400 قدم³/دقيقة\n- نظام الإدارة: من محرك الشاسيه، إدارة هيدروستاتيكية عبر مأخذ القدرة (PTO)\n- الذراع: هيدروليكي بالكامل بتحكم تناسبي ودوران 180°، وتغطية ممتدة 5.4 م\n- خرطوم السحب: قطر 6 بوصة (152 مم)\n- سعة صندوق المخلفات: 2.3 م³، و3.8 م³ اختياري\n- خزان المياه: 1,893 لتر ألومنيوم بضمان 10 سنوات، و2,840 لتر ستانلس ستيل اختياري\n- مضخة المياه: نظام Vactor Jet Rodder Multi-Flow\n[صفحة iMPACT](/model.html?p=vactor-impact&lang=ar)\nلو حابب التفاصيل كاملة أو عرض سعر، اضغط زرّ «كلّم موظف» تحت.', 'facts', 'new', 'claim', 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(171, 'ar', 'ليه اختار iMPACT؟', 'ليه اختار impact', 'أهم اللي يميّز iMPACT:\n- وحدة صرف مشتركة مدمجة: بتعمل تقريبًا أي شغل بتعمله الوحدات الكبيرة، باقتصاد أعلى وقدرة مناورة في الأماكن الضيقة\n- تحكّم IntuiTouch: تشغيل مأخذ القدرة (PTO) بلمسة واحدة، وأوضاع السير والتشغيل المشترك وإعادة التدوير بضغطة زر\n- شفط بالإزاحة الموجبة يُدار هيدروستاتيكيًا من محرك الشاسيه، لسحب المواد لمسافات بعيدة\n- مضخة مياه Jet Rodder قليلة الصيانة، بخاصية «Jackhammer» لتفتيت أصعب الانسدادات\n- نظام JETRight: تحدد ضغط المياه المطلوب والنظام يثبّته مهما تغيّرت سرعة المحرك\n- ريموت لاسلكي محمول وباليد بنقل بيانات في الاتجاهين: ضغط المياه والتدفق وطول الخرطوم\n[صفحة iMPACT](/model.html?p=vactor-impact&lang=ar)\nلو حابب التفاصيل كاملة أو عرض سعر، اضغط زرّ «كلّم موظف» تحت.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(172, 'ar', 'iMPACT يناسب ايه؟', 'impact يناسب ايه', 'iMPACT مناسب لـ:\n- وحدة احتياطية سريعة الاستجابة للطوارئ في البلديات\n- التنظيف الدوري لخطوط الصرف الصحي ومياه الأمطار في المدن والتجمعات الأصغر\n- المقاولين وشركات المرافق اللي محتاجة تعدد استخدامات بتكلفة شراء أقل\n- الشوارع والمواقع الضيقة اللي الوحدات الكبيرة متقدرش تتحرك فيها\n[صفحة iMPACT](/model.html?p=vactor-impact&lang=ar)\nلو حابب التفاصيل كاملة أو عرض سعر، اضغط زرّ «كلّم موظف» تحت.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(173, 'ar', 'عندكم كتالوج لـ iMPACT؟', 'عندكم كتالوج ل impact', 'أيوه، ملفات iMPACT متاحة للتحميل:\n- [كتالوج iMPACT 2026 (PDF)](/assets/img/vactor/impact/brochure.pdf)\n[صفحة iMPACT](/model.html?p=vactor-impact&lang=ar)', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', NULL),
(174, 'en', 'What is the iMPACT?', 'what is the impact', 'iMPACT — Vactor: A compact combination sewer cleaner with no less power: positive-displacement vacuum, Jet Rodder high-pressure jetting and IntuiTouch controls, with the manoeuvrability to work in tight spaces.\n[iMPACT page](/model.html?p=vactor-impact&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(175, 'en', 'What are the specifications of the iMPACT?', 'what are the specifications of the impact', 'Key specifications of the iMPACT:\n- Design: Exclusive Vactor Modul-Flex\n- Air mover: Roots / Dresser positive displacement\n- Vacuum rating: Up to 15 in (381 mm) Hg\n- Inlet volume: Up to 2,400 CFM\n- Drive: Chassis-driven, hydrostatic drive via PTO\n- Boom: Fully hydraulic, proportional controls, 180° rotation; 17¾ ft (5.4 m) extendable coverage\n- Pickup hose: 6 in (152 mm) diameter\n- Debris body capacity: 3 yd³ (2.3 m³) — 5 yd³ (3.8 m³) optional\n- Water tank: 500 gal (1,893 L) aluminium, 10-year warranty — 750 gal (2,840 L) stainless steel optional\n- Water pump: Vactor Jet Rodder Multi-Flow system\n[iMPACT page](/model.html?p=vactor-impact&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(176, 'en', 'What are the advantages of the iMPACT?', 'what are the advantages of the impact', 'What sets the iMPACT apart:\n- Compact combination sewer cleaner: tackles virtually any job a big machine can do, with greater economy and manoeuvrability in tight spaces\n- IntuiTouch controls: one-touch PTO engagement, and road, combo and recirculation modes at the push of a button\n- Positive-displacement vacuum driven hydrostatically from the chassis engine, for pulling material long distances\n- Low-maintenance Jet Rodder water pump with "Jackhammer" action to break up the toughest blockages\n- JETRight: set a target water pressure and the system holds it regardless of throttle settings\n- Wireless belly-pack and handheld remotes with two-way data: water pressure, flow and hose footage\n[iMPACT page](/model.html?p=vactor-impact&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(177, 'en', 'What is the iMPACT used for?', 'what is the impact used for', 'The iMPACT fits:\n- Fast-response emergency back-up vehicle for municipalities\n- Regular cleaning of sanitary and storm water lines in smaller communities\n- Contractors and utilities that need versatility with a lower purchase price\n- Tight streets and sites where a larger unit cannot manoeuvre\n[iMPACT page](/model.html?p=vactor-impact&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(178, 'en', 'Do you have a brochure for the iMPACT?', 'do you have a brochure for the impact', 'Yes, files for the iMPACT:\n- [iMPACT brochure 2026 (PDF)](/assets/img/vactor/impact/brochure.pdf)\n[iMPACT page](/model.html?p=vactor-impact&lang=en)', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', NULL),
(179, 'ar', 'احكيلي عن 2100 Global', 'احكيلي عن 2100 global', '2100 Global — Vactor: أقوى وحدة مشتركة لتنظيف الصرف في العالم للأسواق الدولية: صناديق مخلفات Modul-Flex حتى 11.5 م³، وضخ مائي عالي الضغط بطلمبة JetRodder® بخاصية Jack Hammer، واختيار بين نظام شفط بالمروحة أو بالإزاحة الموجبة.\n[صفحة 2100 Global](/model.html?p=vactor-2100-global&lang=ar)\nعايز عرض سعر على المواصفات دي؟ اضغط زرّ «كلّم موظف» تحت وفريق المبيعات هيتواصل معاك.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(180, 'ar', '2100 Global مواصفاته ايه؟', '2100 global مواصفاته ايه', 'دي المواصفات الأساسية لـ 2100 Global:\n- التصميم: تصميم Modul-Flex الحصري من Vactor\n- مولّد الشفط: مروحة طرد مركزي بمرحلة أو مرحلتين، أو منفاخ إزاحة موجبة Roots\n- قدرة الشفط (طراز PD): حتى 18 بوصة (457 مم) زئبق\n- حجم الهواء الداخل (طراز PD): حتى 4,500 قدم³/دقيقة عند 0 بوصة زئبق\n- المروحة الطاردة المركزية: ألومنيوم 965 مم، مرحلة واحدة 125 حصان / مرحلتين 185 حصان بمحرك ديزل مساعد\n- سعة صندوق المخلفات: 3.8 – 11.5 م³ من صلب Ex-Ten المقاوم للتآكل والتأكسد\n- تفريغ صندوق المخلفات: إمالة 50° بإسطوانة هيدروليكية مزدوجة الأثر؛ تفريغ عالي قياسي\n- خزان المياه: من ⁦1,000⁩ إلى ⁦1,500⁩ جالون (⁦3,785⁩ – ⁦5,678⁩ لتر) ألومنيوم بضمان ⁦10⁩ سنوات\n- مضخة المياه: نظام Vactor JetRodder® Multi-Flow، حتى 100 جالون/دقيقة عند 3,000 psi\n- طريقة الضخ: تدفق مستمر أو نبضات Jack Hammer\n[صفحة 2100 Global](/model.html?p=vactor-2100-global&lang=ar)\nعايز عرض سعر على المواصفات دي؟ اضغط زرّ «كلّم موظف» تحت وفريق المبيعات هيتواصل معاك.', 'facts', 'new', 'claim', 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(181, 'ar', '2100 Global مميز بإيه؟', '2100 global مميز بايه', 'أهم اللي يميّز 2100 Global:\n- تصميم Modul-Flex الحصري: صناديق مخلفات من 3.8 لحد 11.5 م³ بتتظبط حسب الشغل\n- ذراع هيدروليكي تلسكوبي بيمتد 3.45 م بدوران 180° وتغطية 8.4 م من محور الوحدة\n- طلمبة JetRodder® بخاصية «Jack Hammer» الأوتوماتيكية، حتى 100 جالون/دقيقة عند 3,000 psi — إدارة هيدروليكية بدون سيور\n- بكرة خرطوم أمامية بتمتد 381 مم للأمام وبتلف 270° للتوجيه المثالي من غير ما تحرّك الشاحنة\n- تفريغ عالي قياسي: 1.2 م (محور واحد) / 1.5 م (محورين) — تفريغ مباشر في حاويات الموقع\n- اختيار نظام الشفط: مروحة طرد مركزي بمرحلة أو مرحلتين، أو منفاخ إزاحة موجبة للسحب لمسافات بعيدة\n[صفحة 2100 Global](/model.html?p=vactor-2100-global&lang=ar)\nعايز عرض سعر على المواصفات دي؟ اضغط زرّ «كلّم موظف» تحت وفريق المبيعات هيتواصل معاك.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(182, 'ar', 'امتى اختار 2100 Global؟', 'امتي اختار 2100 global', '2100 Global مناسب لـ:\n- خطوط الصرف الصحي الرئيسية ومياه الأمطار في البلديات\n- تنظيف غرف التفتيش والاستجابة للطوارئ\n- كشف المرافق تحت الأرض وتنظيف المواقع الصناعية\n- سحب المواد لمسافات بعيدة بنظام الإزاحة الموجبة\n[صفحة 2100 Global](/model.html?p=vactor-2100-global&lang=ar)\nعايز عرض سعر على المواصفات دي؟ اضغط زرّ «كلّم موظف» تحت وفريق المبيعات هيتواصل معاك.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(183, 'ar', 'ممكن بروشور 2100 Global؟', 'ممكن بروشور 2100 global', 'أيوه، ملفات 2100 Global متاحة للتحميل:\n- [كتالوج 2100 Global (PDF)](/assets/img/vactor/2100-global/brochure.pdf)\n- [الوصف الفني 2100 Global (PDF)](/assets/img/vactor/2100-global/tech-specs.pdf)\n[صفحة 2100 Global](/model.html?p=vactor-2100-global&lang=ar)', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', NULL),
(184, 'en', 'Tell me about the 2100 Global', 'tell me about the 2100 global', '2100 Global — Vactor: The world’s most powerful combination sewer cleaner for international markets: Modul-Flex debris bodies up to 15 yd³, JetRodder® high-pressure jetting with Jack Hammer action, and a choice of centrifugal or positive-displacement vacuum systems.\n[2100 Global page](/model.html?p=vactor-2100-global&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(185, 'en', 'Technical specs for the 2100 Global?', 'technical specs for the 2100 global', 'Key specifications of the 2100 Global:\n- Design: Exclusive Vactor Modul-Flex\n- Air mover: Single or dual-stage centrifugal compressor (fan), or Roots positive-displacement blower\n- Vacuum rating (PD): Up to 18 in (457 mm) Hg\n- Inlet volume (PD): Up to 4,500 CFM at 0 in Hg\n- Centrifugal fan: 38 in (965 mm) aluminium, single-stage 125 HP / dual-stage 185 HP auxiliary diesel engine\n- Debris body capacity: 5 – 15 yd³ (3.8 – 11.5 m³) Ex-Ten steel\n- Debris body dump: 50° tilt, double-acting hydraulic cylinder; high dump standard\n- Water tank: 1,000 – 1,500 gal (3,785 – 5,678 L) aluminium, 10-year warranty\n- Water pump: Vactor JetRodder® Multi-Flow, up to 100 GPM at 3,000 PSI\n- Pump action: Continuous flow or Jack Hammer\n[2100 Global page](/model.html?p=vactor-2100-global&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(186, 'en', 'Why choose the 2100 Global?', 'why choose the 2100 global', 'What sets the 2100 Global apart:\n- Exclusive Modul-Flex design: debris body capacities from 5 to 15 yd³ (3.8–11.5 m³) configured around the job\n- Telescoping hydraulic boom extends up to 10 ft (3.45 m) with 180° rotation and 27.6 ft (8.4 m) reach off centreline\n- JetRodder® water pump with automatic "Jack Hammer" action, up to 100 GPM at 3,000 PSI — hydraulically driven, no belts\n- Front-mounted hose reel telescopes 15 in (381 mm) forward and rotates 270° for optimal positioning without moving the truck\n- Standard high dump: 48 in (1.2 m) single axle / 60 in (1.5 m) tandem axle — unload directly into roll-off containers on site\n- Choice of vacuum system: single or dual-stage centrifugal compressor (fan) or positive-displacement blower for long-distance pulls\n[2100 Global page](/model.html?p=vactor-2100-global&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(187, 'en', 'When should I choose the 2100 Global?', 'when should i choose the 2100 global', 'The 2100 Global fits:\n- Municipal sanitary sewer mains and stormwater lines\n- Catch basin cleaning and emergency remediation\n- Utility daylighting and industrial site clean-up\n- Long-distance material recovery with PD blower option\n[2100 Global page](/model.html?p=vactor-2100-global&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(188, 'en', 'Is there a datasheet for the 2100 Global?', 'is there a datasheet for the 2100 global', 'Yes, files for the 2100 Global:\n- [2100 Global brochure (PDF)](/assets/img/vactor/2100-global/brochure.pdf)\n- [2100 Global technical description (PDF)](/assets/img/vactor/2100-global/tech-specs.pdf)\n[2100 Global page](/model.html?p=vactor-2100-global&lang=en)', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', NULL),
(189, 'ar', 'ايه هو Classic؟', 'ايه هو classic', 'Classic — Guzzler: المعيار الصناعي المُثبَت لسحب المواد الصلبة والمساحيق الجافة والمخاليط الثقيلة والحمأة الصناعية اللزجة عبر مسافات شفط بعيدة.\n[صفحة Classic](/model.html?p=guzzler-classic&lang=ar)\nتحب نجهّزلك عرض سعر؟ اضغط زرّ «كلّم موظف» تحت أو املأ طلب عرض السعر من الموقع.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(190, 'ar', 'ايه مزايا Classic؟', 'ايه مزايا classic', 'أهم اللي يميّز Classic:\n- بتسحب المواد الصلبة والمساحيق الجافة والسوائل والروبة الثقيلة من غير ما تغيّر إعدادات المعدة\n- فلترة على أربع مراحل: أول مرحلتين لوحدهم بيشيلوا ⁦98%⁩ من المواد من تيار الهواء\n- السيكلون بيشتغل كمزيل رطوبة في الشغل المبلول، وبيتفرّغ مع الحمولة الرئيسية في نفس الوقت\n- كل أجزاء الفلترة قابلة للوصول بالكامل، مع مجمّع هيدروليكي مركزي واحد للصيانة\n- لوحة عدادات ألومنيوم محكمة: عدّاد لفّات النافخة وحرارتها، وعدّاد الساعات، وعدادات الهيدروليك والشفط وضغط الهواء\n- زر الطوارئ عند محطات التشغيل بيقطع الشفط والهيدروليك وبيهدّي موتور الشاسيه\n[صفحة Classic](/model.html?p=guzzler-classic&lang=ar)\nتحب نجهّزلك عرض سعر؟ اضغط زرّ «كلّم موظف» تحت أو املأ طلب عرض السعر من الموقع.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(191, 'ar', 'عندكم كتالوج لـ Classic؟', 'عندكم كتالوج ل classic', 'أيوه، ملفات Classic متاحة للتحميل:\n- [بروشور ⁦Guzzler Classic⁩ (PDF)](/assets/img/guzzler/classic/brochure.pdf)\n[صفحة Classic](/model.html?p=guzzler-classic&lang=ar)', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', NULL),
(192, 'en', 'What is the Classic?', 'what is the classic', 'Classic — Guzzler: The proven industrial standard for extracting solids, dry bulk powders, heavy slurries, and viscous industrial sludge over extreme suction distances.\n[Classic page](/model.html?p=guzzler-classic&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(193, 'en', 'What are the specifications of the Classic?', 'what are the specifications of the classic', 'Key specifications of the Classic:\n- Vacuum blower: Positive displacement, dual-lobe or tri-lobe\n- Vacuum range: 16 – 27 in Hg\n- Airflow range: 5,089 – 5,250 CFM\n- Debris body volume: 18 cu yd (13.76 m³)\n- Debris body construction: 1/4 in (6.35 mm) wall, 1/2 in (12.7 mm) rear door on three heavy-duty hinges\n- Filtration: Four stages: debris body, cyclone chamber, baghouse (9.94:1 air-to-cloth), microstrainer\n- Bag cleaning: 120 psi pulsation system\n- Telescoping boom (optional): Pendant reach 55 ft (16.8 m), stored with the hose attached\n- Vane pressure offload (optional): Pressurises the body to 14.5 psi, or draws up to 28.5 in Hg\n- Hydraulic tank: 50 gal (189 L), pump driven from the PTO\n[Classic page](/model.html?p=guzzler-classic&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(194, 'en', 'What are the advantages of the Classic?', 'what are the advantages of the classic', 'What sets the Classic apart:\n- Recovers solids, dry bulk powders, liquids and heavy slurries without reconfiguring the machine\n- Four-stage filtration: the first two stages alone remove 98% of material from the airstream\n- Cyclone doubles as a demister on wet work, and empties together with the main payload\n- All filter components fully accessible, with a single central hydraulic manifold for servicing\n- Sealed aluminium instrument panel: blower tachometer and temperature, hourmeter, hydraulic, vacuum and air gauges\n- E-Stop at the operator stations cuts vacuum and hydraulics and throttles the chassis engine down\n[Classic page](/model.html?p=guzzler-classic&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(195, 'en', 'What is the Classic used for?', 'what is the classic used for', 'The Classic fits:\n- Petroleum refineries and chemical plants\n- Cement, steel, and lime manufacturing\n- Power plant fly-ash and boiler cleaning\n- Environmental disaster remediation\n[Classic page](/model.html?p=guzzler-classic&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(196, 'en', 'Do you have a brochure for the Classic?', 'do you have a brochure for the classic', 'Yes, files for the Classic:\n- [Guzzler Classic brochure (PDF)](/assets/img/guzzler/classic/brochure.pdf)\n[Classic page](/model.html?p=guzzler-classic&lang=en)', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', NULL),
(197, 'ar', 'مولدات كهربائية من نوع المظلة  (20-3000) KVA ده ايه؟', 'مولدات كهرباييه من نوع المظله 20 3000 kva ده ايه', 'مولدات كهربائية من نوع المظلة  (20-3000) KVA — 5A&M: المولدات الكهربائية المغلقة مزودة بكبائن مقاومة للعوامل الجوية وعازلة للصوت، لتوفير تشغيل أكثر هدوءًا وحماية أعلى للمعدة في مختلف ظروف التشغيل.\n[صفحة مولدات كهربائية من نوع المظلة  (20-3000) KVA](/model.html?p=sound-proof-canopy-diesel-generators&lang=ar)\nلو حابب التفاصيل كاملة أو عرض سعر، اضغط زرّ «كلّم موظف» تحت.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(198, 'en', 'Tell me about the CANOPY TYPE GENERATORS (20-3000) KVA', 'tell me about the canopy type generators 20 3000 kva', 'CANOPY TYPE GENERATORS (20-3000) KVA — 5A&M: Canopy Type generators are equipped with weather-resistant, sound-attenuated enclosures for quieter operation and enhanced protection in demanding environments\n[CANOPY TYPE GENERATORS (20-3000) KVA page](/model.html?p=sound-proof-canopy-diesel-generators&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(199, 'en', 'Technical specs for the CANOPY TYPE GENERATORS (20-3000) KVA?', 'technical specs for the canopy type generators 20 3000 kva', 'Key specifications of the CANOPY TYPE GENERATORS (20-3000) KVA:\n- Rating range: CANOPY TYPE GENERATORS (20-3000) KVA\n- Enclosure type: Sound-proof acoustic canopy fabricated in-house\n- Engine options: Perkins, Cummins, Baudouin, Doosan, Develon, Volvo\n- Alternator options: Stamford, Leroy-Somer\n- Controller options: Deep Sea Electronics (DSE), ComAp\n- Noise attenuation: Residential silencer & acoustic insulation down to 68 dBA @ 7m\n[CANOPY TYPE GENERATORS (20-3000) KVA page](/model.html?p=sound-proof-canopy-diesel-generators&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(200, 'en', 'Why choose the CANOPY TYPE GENERATORS (20-3000) KVA?', 'why choose the canopy type generators 20 3000 kva', 'What sets the CANOPY TYPE GENERATORS (20-3000) KVA apart:\n- Manufactured in 5A&M in-house sheet metal and powder coating workshop\n- Weather-tight, anti-corrosion electrostatic powder-coated acoustic canopy\n- Built with genuine Tier-1 engines and alternators directly sourced from OEM partners\n- Integral base fuel tank with mechanical fuel gauge and leak detection sensor\n- Supervised installation, cable connection, and load-bank commissioning included\n[CANOPY TYPE GENERATORS (20-3000) KVA page](/model.html?p=sound-proof-canopy-diesel-generators&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(201, 'en', 'When should I choose the CANOPY TYPE GENERATORS (20-3000) KVA?', 'when should i choose the canopy type generators 20 3000 kva', 'The CANOPY TYPE GENERATORS (20-3000) KVA fits:\n- Hospitals and healthcare complexes\n- Commercial towers, hotels, and shopping malls\n- Residential compounds and gated communities\n- Embassies and administrative headquarters\n[CANOPY TYPE GENERATORS (20-3000) KVA page](/model.html?p=sound-proof-canopy-diesel-generators&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(202, 'ar', 'احكيلي عن مولدات داخل حاويات (20 - 3000)', 'احكيلي عن مولدات داخل حاويات 20 3000', 'مولدات داخل حاويات (20 - 3000) — 5A&M: مولدات كهربائية داخل حاويات 20 و40 قدمًا، مصممة لتحمل ظروف التشغيل القاسية وتوفير طاقة مستمرة وعالية السعة للأحمال الصناعية الثقيلة.\n[صفحة مولدات داخل حاويات (20 - 3000)](/model.html?p=containerized-generators&lang=ar)\nعايز عرض سعر على المواصفات دي؟ اضغط زرّ «كلّم موظف» تحت وفريق المبيعات هيتواصل معاك.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(203, 'en', 'What is the CONTAINERAIZED GENERATORS (20   - 3000) KVA?', 'what is the containeraized generators 20 3000 kva', 'CONTAINERAIZED GENERATORS (20   - 3000) KVA — 5A&M: 20ft and 40ft containerized generator sets, designed to withstand demanding operating conditions and deliver continuous, high-capacity power for heavy industrial loads.\n[CONTAINERAIZED GENERATORS (20   - 3000) KVA page](/model.html?p=containerized-generators&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(204, 'en', 'What are the specifications of the CONTAINERAIZED GENERATORS (20   - 3000) KVA?', 'what are the specifications of the containeraized generators 20 3000 kva', 'Key specifications of the CONTAINERAIZED GENERATORS (20   - 3000) KVA:\n- Rating range: (20   - 3000) KVA\n- Container body: 20 ft or 40 ft CSC-plated heavy structural ISO container\n- Thermal management: Motorized intake & exhaust louvres, 50°C tropical ambient cooling\n- Engine options: Cummins, Perkins, Volvo, Baudouin\n- Alternator options: Stamford, Leroy-Somer\n- Controller options: Deep Sea Electronics (DSE) with automatic multi-set synchronization\n[CONTAINERAIZED GENERATORS (20   - 3000) KVA page](/model.html?p=containerized-generators&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(205, 'en', 'What are the advantages of the CONTAINERAIZED GENERATORS (20   - 3000) KVA?', 'what are the advantages of the containeraized generators 20 3000 kva', 'What sets the CONTAINERAIZED GENERATORS (20   - 3000) KVA apart:\n- Heavy-duty CSC-certified container for rough transport and harsh outdoor sites\n- Acoustic sound-baffling and multi-stage air filtration for desert conditions\n- Internal walk-in service corridor with industrial lighting and AC distribution\n- Engineered for parallel multi-megawatt configurations with remote SCADA telemetry\n- Delivered ready to drop on foundation and power the facility immediately\n[CONTAINERAIZED GENERATORS (20   - 3000) KVA page](/model.html?p=containerized-generators&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(206, 'en', 'What is the CONTAINERAIZED GENERATORS (20   - 3000) KVA used for?', 'what is the containeraized generators 20 3000 kva used for', 'The CONTAINERAIZED GENERATORS (20   - 3000) KVA fits:\n- Oil & gas extraction facilities\n- Major infrastructure & construction megaprojects\n- Industrial manufacturing plants\n- Data centres and critical utilities\n[CONTAINERAIZED GENERATORS (20   - 3000) KVA page](/model.html?p=containerized-generators&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(207, 'ar', 'ايه هو مولدات ديزل مفتوحة صناعية (20-3000) KVA؟', 'ايه هو مولدات ديزل مفتوحه صناعيه 20 3000 kva', 'مولدات ديزل مفتوحة صناعية (20-3000) KVA — 5A&M: المولدات الكهربائية المفتوحة، والمعروفة أيضًا بالمولدات المثبتة على قاعدة ، تتكون من المحرك والموبينة ووحدة التحكم مثبتة على قاعدة معدنية، دون وجود كابينة خارجية، مما يوفر تصميمًا عمليًا ومرونة أكبر في التركيب وفقًا لمتطلبات الموقع.\n[صفحة مولدات ديزل مفتوحة صناعية (20-3000) KVA](/model.html?p=open-skid-diesel-generators&lang=ar)\nتحب نجهّزلك عرض سعر؟ اضغط زرّ «كلّم موظف» تحت أو املأ طلب عرض السعر من الموقع.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(208, 'en', 'Tell me about the OPEN TYPE GENERATORS (20-3000) KVA', 'tell me about the open type generators 20 3000 kva', 'OPEN TYPE GENERATORS (20-3000) KVA — 5A&M: Open type generators also known as skid-mounted generators, are units without any enclosure. They consist of just the engine, alternator, and control systems mounted on a frame or skid\n[OPEN TYPE GENERATORS (20-3000) KVA page](/model.html?p=open-skid-diesel-generators&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(209, 'en', 'Technical specs for the OPEN TYPE GENERATORS (20-3000) KVA?', 'technical specs for the open type generators 20 3000 kva', 'Key specifications of the OPEN TYPE GENERATORS (20-3000) KVA:\n- Rating range: (20-3000) KVA\n- Mounting: Heavy-duty fabricated steel skid with elastomeric anti-vibration isolators\n- Engine options: Perkins, Cummins, Doosan, Develon, Volvo, Baudouin\n- Alternator options: Stamford, Leroy-Somer\n- Controller options: Deep Sea Electronics (DSE), ComAp\n- Cooling system: Set-mounted tropical radiator (up to 50°C ambient)\n[OPEN TYPE GENERATORS (20-3000) KVA page](/model.html?p=open-skid-diesel-generators&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(210, 'en', 'Why choose the OPEN TYPE GENERATORS (20-3000) KVA?', 'why choose the open type generators 20 3000 kva', 'What sets the OPEN TYPE GENERATORS (20-3000) KVA apart:\n- Maximum service accessibility from all sides for fast overhauls and maintenance\n- Heavy structural steel base frame with certified crane lifting points\n- Supplied with industrial exhaust silencer, flexible stainless bellows, and vibration mounts\n- Direct SAE bell-housing precision alignment ensuring zero driveline deflection\n[OPEN TYPE GENERATORS (20-3000) KVA page](/model.html?p=open-skid-diesel-generators&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(211, 'en', 'When should I choose the OPEN TYPE GENERATORS (20-3000) KVA?', 'when should i choose the open type generators 20 3000 kva', 'The OPEN TYPE GENERATORS (20-3000) KVA fits:\n- Dedicated basement generator rooms\n- Factory mechanical rooms\n- Agricultural pumping stations & pivots\n- Centralized utility enclosures\n[OPEN TYPE GENERATORS (20-3000) KVA page](/model.html?p=open-skid-diesel-generators&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(212, 'ar', 'مولدات ديزل على مقطورات متحركة (20 - 1500 ) KVA ده ايه؟', 'مولدات ديزل علي مقطورات متحركه 20 1500 kva ده ايه', 'مولدات ديزل على مقطورات متحركة (20 - 1500 ) KVA — 5A&M: مولدات كهربائية متنقلة قابلة للقطر على الطرق، مثبتة على مقطورات مصممة خصيصًا بمحور مفرد أو محور مزدوج، لتوفير سرعة النقل وسهولة الانتقال والتشغيل بين المواقع.\n[صفحة مولدات ديزل على مقطورات متحركة (20 - 1500 ) KVA](/model.html?p=mobile-trailer-generators&lang=ar)\nلو حابب التفاصيل كاملة أو عرض سعر، اضغط زرّ «كلّم موظف» تحت.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(213, 'en', 'What is the Mobile Trailer Generators (20 - 1500 ) KVA?', 'what is the mobile trailer generators 20 1500 kva', 'Mobile Trailer Generators (20 - 1500 ) KVA — 5A&M: Fully road-towable mobile generator sets, mounted on custom-engineered trailers, designed for rapid mobilization and easy deployment between sites.\n[Mobile Trailer Generators (20 - 1500 ) KVA page](/model.html?p=mobile-trailer-generators&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(214, 'en', 'What are the specifications of the Mobile Trailer Generators (20 - 1500 ) KVA?', 'what are the specifications of the mobile trailer generators 20 1500 kva', 'Key specifications of the Mobile Trailer Generators (20 - 1500 ) KVA:\n- Rating range: 20 – 1500  kVA\n- Chassis: Single, tandem or triple-axle trailer with inertia / pneumatic braking\n- Enclosure: Heavy-duty weather/sound proof canopy fabricated in-house\n- Fuel autonomy: High-capacity extended runtime fuel tank integrated into chassis\n- Towing hitch: Standard NATO pintle ring or ball coupling with safety chains\n[Mobile Trailer Generators (20 - 1500 ) KVA page](/model.html?p=mobile-trailer-generators&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(215, 'en', 'What are the advantages of the Mobile Trailer Generators (20 - 1500 ) KVA?', 'what are the advantages of the mobile trailer generators 20 1500 kva', 'What sets the Mobile Trailer Generators (20 - 1500 ) KVA apart:\n- Engineered and fabricated in the 5A&M trailer manufacturing workshop\n- Reinforced off-road suspension for rough desert, quarry, and construction terrain\n- Fast deployment exterior connection lugs and lockable cable storage compartments\n- Corner mechanical stabilizer jacks for stable levelling on uneven grade\n[Mobile Trailer Generators (20 - 1500 ) KVA page](/model.html?p=mobile-trailer-generators&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(216, 'en', 'What is the Mobile Trailer Generators (20 - 1500 ) KVA used for?', 'what is the mobile trailer generators 20 1500 kva used for', 'The Mobile Trailer Generators (20 - 1500 ) KVA fits:\n- Road construction and bridge projects\n- Emergency power restoration & disaster response\n- Seasonal agricultural harvesting and irrigation\n- Remote exploration camps\n[Mobile Trailer Generators (20 - 1500 ) KVA page](/model.html?p=mobile-trailer-generators&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(217, 'ar', 'احكيلي عن حلول أسطول تأجير المولدات (20 – 1000 kVA)', 'احكيلي عن حلول اسطول تاجير المولدات 20 1000 kva', 'حلول أسطول تأجير المولدات (20 – 1000 kVA) — 5A&M: مولدات للإيجار من 20 حتى 1000 ك.ف.أ بتوريد فوري، مع التركيب الكامل بالموقع والتموين الدوري بالوقود ودعم فني على مدار الساعة.\n[صفحة حلول أسطول تأجير المولدات (20 – 1000 kVA)](/model.html?p=rental-power-generators&lang=ar)\nعايز عرض سعر على المواصفات دي؟ اضغط زرّ «كلّم موظف» تحت وفريق المبيعات هيتواصل معاك.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(218, 'en', 'Tell me about the Rental Power Fleet Solutions (20 – 1000 kVA)', 'tell me about the rental power fleet solutions 20 1000 kva', 'Rental Power Fleet Solutions (20 – 1000 kVA) — 5A&M: Immediate-dispatch rental power generators from 20 to 1000 kVA, delivered with full on-site installation, periodic fuel supply, and 24/7 technician support.\n[Rental Power Fleet Solutions (20 – 1000 kVA) page](/model.html?p=rental-power-generators&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(219, 'en', 'Technical specs for the Rental Power Fleet Solutions (20 – 1000 kVA)?', 'technical specs for the rental power fleet solutions 20 1000 kva', 'Key specifications of the Rental Power Fleet Solutions (20 – 1000 kVA):\n- Fleet capacity: 20 kVA to 1000 kVA individual units (multi-MW parallel available)\n- Contract duration: Daily, weekly, monthly, seasonal, or multi-year terms\n- Configurations: Sound-proof canopy or road-towable mobile trailer\n- Dispatch coverage: Immediate deployment across Greater Cairo and all governorates\n- Support coverage: 24/7 on-site certified technician and preventive maintenance included\n[Rental Power Fleet Solutions (20 – 1000 kVA) page](/model.html?p=rental-power-generators&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(220, 'en', 'Why choose the Rental Power Fleet Solutions (20 – 1000 kVA)?', 'why choose the rental power fleet solutions 20 1000 kva', 'What sets the Rental Power Fleet Solutions (20 – 1000 kVA) apart:\n- 100% full load-bank tested and certified before dispatch\n- Turnkey delivery: foundation check, mechanical placement, and electrical hook-up\n- Comprehensive lube, filter, and consumables maintenance covered by 5A&M\n- Guaranteed immediate replacement set in the unlikely event of malfunction\n[Rental Power Fleet Solutions (20 – 1000 kVA) page](/model.html?p=rental-power-generators&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(221, 'en', 'When should I choose the Rental Power Fleet Solutions (20 – 1000 kVA)?', 'when should i choose the rental power fleet solutions 20 1000 kva', 'The Rental Power Fleet Solutions (20 – 1000 kVA) fits:\n- Temporary construction power\n- Peak seasonal load shaving\n- Main transformer scheduled shutdown backup\n- Industrial maintenance turnarounds\n[Rental Power Fleet Solutions (20 – 1000 kVA) page](/model.html?p=rental-power-generators&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46');
INSERT INTO `chat_cache` (`id`, `lang`, `question`, `q_norm`, `answer`, `source`, `status`, `issues`, `hits`, `reviewed_by`, `last_hit_at`, `created_at`, `updated_at`) VALUES
(222, 'ar', 'ايه هو لوحة التحويل الأوتوماتيكي (ATS)؟', 'ايه هو لوحه التحويل الاوتوماتيكي ats', 'لوحة التحويل الأوتوماتيكي (ATS) — 5A&M: لوحة تحويل أوتوماتيكي مصممة ومجمعة داخلياً لنقل الأحمال تلقائياً بين مصدر الكهرباء الحكومي والمولد.\n[صفحة لوحة التحويل الأوتوماتيكي (ATS)](/model.html?p=ats-panel&lang=ar)\nتحب نجهّزلك عرض سعر؟ اضغط زرّ «كلّم موظف» تحت أو املأ طلب عرض السعر من الموقع.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(223, 'en', 'What is the Automatic Transfer Switch (ATS) Panel?', 'what is the automatic transfer switch ats panel', 'Automatic Transfer Switch (ATS) Panel — 5A&M: Automatic transfer switch panel designed and assembled in-house to transfer load between mains and generator supply.\n[Automatic Transfer Switch (ATS) Panel page](/model.html?p=ats-panel&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(224, 'en', 'What are the specifications of the Automatic Transfer Switch (ATS) Panel?', 'what are the specifications of the automatic transfer switch ats panel', 'Key specifications of the Automatic Transfer Switch (ATS) Panel:\n- Switching technology: 4-pole motorized changeover or contactor pairs\n- Switchgear OEM: Schneider Electric, ABB\n- Current rating: Engineered to exact project amperage (up to 4000 A)\n- Enclosure grade: IP54 / IP65 powder-coated sheet metal enclosure\n[Automatic Transfer Switch (ATS) Panel page](/model.html?p=ats-panel&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(225, 'en', 'What are the advantages of the Automatic Transfer Switch (ATS) Panel?', 'what are the advantages of the automatic transfer switch ats panel', 'What sets the Automatic Transfer Switch (ATS) Panel apart:\n- Designed and manufactured by experienced 5A&M electrical engineering team\n- Mechanical and electrical interlocking preventing mains/generator back-feed\n- Digital phase monitoring, under/over voltage, and frequency protection\n- Seamless integration with DSE and ComAp generator control modules\n[Automatic Transfer Switch (ATS) Panel page](/model.html?p=ats-panel&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(226, 'en', 'What is the Automatic Transfer Switch (ATS) Panel used for?', 'what is the automatic transfer switch ats panel used for', 'The Automatic Transfer Switch (ATS) Panel fits:\n- Standby power automatic changeover\n- Hospitals and life safety infrastructure\n- Commercial towers and server facilities\n[Automatic Transfer Switch (ATS) Panel page](/model.html?p=ats-panel&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(227, 'ar', 'لوحة تزامن وتوازي المولدات (Synchronization) ده ايه؟', 'لوحه تزامن وتوازي المولدات synchronization ده ايه', 'لوحة تزامن وتوازي المولدات (Synchronization) — 5A&M: لوحة مزامنة لتشغيل عدة مولدات على التوازي مصممة ومجمعة خصيصاً طبقاً لمتطلبات المشروع.\n[صفحة لوحة تزامن وتوازي المولدات (Synchronization)](/model.html?p=synchronization-panel&lang=ar)\nلو حابب التفاصيل كاملة أو عرض سعر، اضغط زرّ «كلّم موظف» تحت.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(228, 'en', 'Tell me about the Generator Synchronization Panel', 'tell me about the generator synchronization panel', 'Generator Synchronization Panel — 5A&M: Synchronisation panel for running multiple generator sets in parallel, designed and assembled to the project requirement.\n[Generator Synchronization Panel page](/model.html?p=synchronization-panel&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(229, 'en', 'Technical specs for the Generator Synchronization Panel?', 'technical specs for the generator synchronization panel', 'Key specifications of the Generator Synchronization Panel:\n- Paralleling mode: Multi-genset island mode and mains-parallel peak shaving\n- Controllers: Deep Sea Electronics (DSE 8610 MKII), ComAp InteliGen\n- Switchgear components: Schneider Electric, ABB motorized air circuit breakers (ACB)\n- Number of sets: Configured from 2 up to 32 generators in parallel\n[Generator Synchronization Panel page](/model.html?p=synchronization-panel&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(230, 'en', 'Why choose the Generator Synchronization Panel?', 'why choose the generator synchronization panel', 'What sets the Generator Synchronization Panel apart:\n- Automatic synchronization, phase matching, and frequency locking\n- Dynamic proportional load sharing and spinning reserve management\n- Priority-based auto start/stop depending on site electrical demand\n- Touchscreen graphical HMI with full event logging and fault diagnostics\n[Generator Synchronization Panel page](/model.html?p=synchronization-panel&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(231, 'en', 'When should I choose the Generator Synchronization Panel?', 'when should i choose the generator synchronization panel', 'The Generator Synchronization Panel fits:\n- Multi-megawatt power plants\n- Heavy industrial complexes with variable loads\n- Critical data centers requiring N+1 redundancy\n[Generator Synchronization Panel page](/model.html?p=synchronization-panel&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(232, 'ar', 'احكيلي عن كابينة عازلة للصوت ومقاومة للعوامل الجوية', 'احكيلي عن كابينه عازله للصوت ومقاومه للعوامل الجويه', 'كابينة عازلة للصوت ومقاومة للعوامل الجوية — 5A&M: كابينة عازلة لصوت المولدات مُصنعة بورشة الصاج المتطورة بشركة 5A&M طبقاً للمواصفات الفنية المطلوبة.\n[صفحة كابينة عازلة للصوت ومقاومة للعوامل الجوية](/model.html?p=sound-proof-canopy&lang=ar)\nعايز عرض سعر على المواصفات دي؟ اضغط زرّ «كلّم موظف» تحت وفريق المبيعات هيتواصل معاك.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(233, 'en', 'What is the Custom Sound-Proof & Weatherproof Canopy?', 'what is the custom sound proof weatherproof canopy', 'Custom Sound-Proof & Weatherproof Canopy — 5A&M: Acoustic generator enclosure fabricated in the 5A&M sheet metal workshop and finished to the customer specification.\n[Custom Sound-Proof & Weatherproof Canopy page](/model.html?p=sound-proof-canopy&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(234, 'en', 'What are the advantages of the Custom Sound-Proof & Weatherproof Canopy?', 'what are the advantages of the custom sound proof weatherproof canopy', 'What sets the Custom Sound-Proof & Weatherproof Canopy apart:\n- Fabricated entirely inside 5A&M workshop to client dimensions\n- Ergonomic maintenance access doors with 180° swing radius\n- Acoustic baffled air intake and discharge attenuation ducts\n- External emergency stop button and lockable fuel filling hatch\n[Custom Sound-Proof & Weatherproof Canopy page](/model.html?p=sound-proof-canopy&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(235, 'en', 'What is the Custom Sound-Proof & Weatherproof Canopy used for?', 'what is the custom sound proof weatherproof canopy used for', 'The Custom Sound-Proof & Weatherproof Canopy fits:\n- Acoustic retrofits on existing open gensets\n- Residential and hospital installations\n- Outdoor roof-top power plants\n[Custom Sound-Proof & Weatherproof Canopy page](/model.html?p=sound-proof-canopy&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(236, 'ar', 'ايه هو خزانات وقود ديزل ثابتة ومتحركة؟', 'ايه هو خزانات وقود ديزل ثابته ومتحركه', 'خزانات وقود ديزل ثابتة ومتحركة — 5A&M: خزانات وقود ثابتة ومتحركة مصنعة محلياً بسعات محسوبة بدقة طبقاً لساعات التشغيل المستهدفة.\n[صفحة خزانات وقود ديزل ثابتة ومتحركة](/model.html?p=fuel-tank&lang=ar)\nتحب نجهّزلك عرض سعر؟ اضغط زرّ «كلّم موظف» تحت أو املأ طلب عرض السعر من الموقع.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(237, 'en', 'Tell me about the Mobile & Stationary Fuel Storage Tanks', 'tell me about the mobile stationary fuel storage tanks', 'Mobile & Stationary Fuel Storage Tanks — 5A&M: Mobile and stationary fuel tanks fabricated in-house and sized to the required run time.\n[Mobile & Stationary Fuel Storage Tanks page](/model.html?p=fuel-tank&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(238, 'en', 'Technical specs for the Mobile & Stationary Fuel Storage Tanks?', 'technical specs for the mobile stationary fuel storage tanks', 'Key specifications of the Mobile & Stationary Fuel Storage Tanks:\n- Configuration: Single or double-wall bunded stationary & mobile skids\n- Capacity range: 500 L up to 50,000 L fabricated to project specifications\n- Material: Heavy carbon steel sheet metal with anti-corrosion coating\n- Fittings: Mechanical/electronic level gauges, vents, drain, and inspection manhole\n[Mobile & Stationary Fuel Storage Tanks page](/model.html?p=fuel-tank&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(239, 'en', 'Why choose the Mobile & Stationary Fuel Storage Tanks?', 'why choose the mobile stationary fuel storage tanks', 'What sets the Mobile & Stationary Fuel Storage Tanks apart:\n- Engineered and welded in 5A&M metal workshop to international safety standards\n- Integrated containment bund preventing soil or groundwater contamination\n- Automated fuel transfer pump with high/low float switch integration\n- Available on road-towable chassis or forklift-pocketed base skid\n[Mobile & Stationary Fuel Storage Tanks page](/model.html?p=fuel-tank&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(240, 'en', 'When should I choose the Mobile & Stationary Fuel Storage Tanks?', 'when should i choose the mobile stationary fuel storage tanks', 'The Mobile & Stationary Fuel Storage Tanks fits:\n- Extended runtime power stations\n- Remote agricultural desert farming\n- Construction site bulk diesel storage\n[Mobile & Stationary Fuel Storage Tanks page](/model.html?p=fuel-tank&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(241, 'ar', 'مقطورة نقل وتثبيت المولدات الثقيلة ده ايه؟', 'مقطوره نقل وتثبيت المولدات الثقيله ده ايه', 'مقطورة نقل وتثبيت المولدات الثقيلة — 5A&M: مقطورة مخصصة لنقل المولدات مصنعة في ورشة 5A&M للمحطات المتنقلة بين مواقع العمل المختلفة.\n[صفحة مقطورة نقل وتثبيت المولدات الثقيلة](/model.html?p=genset-trailer&lang=ar)\nلو حابب التفاصيل كاملة أو عرض سعر، اضغط زرّ «كلّم موظف» تحت.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(242, 'en', 'What is the Heavy-Duty Genset Transport Trailer?', 'what is the heavy duty genset transport trailer', 'Heavy-Duty Genset Transport Trailer — 5A&M: Generator trailer fabricated in the 5A&M workshop for sets that need to move between sites.\n[Heavy-Duty Genset Transport Trailer page](/model.html?p=genset-trailer&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(243, 'en', 'What are the specifications of the Heavy-Duty Genset Transport Trailer?', 'what are the specifications of the heavy duty genset transport trailer', 'Key specifications of the Heavy-Duty Genset Transport Trailer:\n- Axle configuration: Single, tandem, or triple heavy-duty torsion/leaf axles\n- Load capacity: From 1,500 kg up to 18,000 kg GVW\n- Braking system: Overrun mechanical or pneumatic air brakes with breakaway cable\n- Lighting & safety: Highway-compliant LED lights, reflectors, and safety chains\n[Heavy-Duty Genset Transport Trailer page](/model.html?p=genset-trailer&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(244, 'en', 'What are the advantages of the Heavy-Duty Genset Transport Trailer?', 'what are the advantages of the heavy duty genset transport trailer', 'What sets the Heavy-Duty Genset Transport Trailer apart:\n- Fabricated from heavy channel steel beams engineered for desert tracks\n- Adjustable front jockey wheel and four heavy corner levelling jacks\n- Integrated spare wheel, mudguards, and cable storage basket\n- Custom built to match exact generator dimensions and weight distribution\n[Heavy-Duty Genset Transport Trailer page](/model.html?p=genset-trailer&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(245, 'en', 'What is the Heavy-Duty Genset Transport Trailer used for?', 'what is the heavy duty genset transport trailer used for', 'The Heavy-Duty Genset Transport Trailer fits:\n- Rental fleets mobilization\n- Contractors moving between construction sectors\n- Emergency disaster mobile power\n[Heavy-Duty Genset Transport Trailer page](/model.html?p=genset-trailer&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(246, 'ar', 'احكيلي عن أنظمة العوادم وكواتم الصوت والتهوية الصناعية', 'احكيلي عن انظمه العوادم وكواتم الصوت والتهويه الصناعيه', 'أنظمة العوادم وكواتم الصوت والتهوية الصناعية — 5A&M: أنظمة عوادم وكواتم صوت ومسارات هواء مصنعة ومركبة لتلائم غرف المولدات والمواقع المفتوحة.\n[صفحة أنظمة العوادم وكواتم الصوت والتهوية الصناعية](/model.html?p=exhaust-and-muffler&lang=ar)\nعايز عرض سعر على المواصفات دي؟ اضغط زرّ «كلّم موظف» تحت وفريق المبيعات هيتواصل معاك.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(247, 'en', 'Tell me about the Industrial Exhaust, Mufflers & Ventilation', 'tell me about the industrial exhaust mufflers ventilation', 'Industrial Exhaust, Mufflers & Ventilation — 5A&M: Exhaust systems, mufflers and air pipes fabricated and installed to suit the generator room or outdoor installation.\n[Industrial Exhaust, Mufflers & Ventilation page](/model.html?p=exhaust-and-muffler&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(248, 'en', 'Technical specs for the Industrial Exhaust, Mufflers & Ventilation?', 'technical specs for the industrial exhaust mufflers ventilation', 'Key specifications of the Industrial Exhaust, Mufflers & Ventilation:\n- Exhaust components: Residential silencers, critical grade mufflers, stainless bellows\n- Ventilation ducts: Galvanized sheet metal acoustic louvres and motorized dampers\n- Thermal insulation: Ceramic blanket / rockwool with aluminium cladding\n- Installation scope: On-site routing, ceiling suspension, and wall penetration\n[Industrial Exhaust, Mufflers & Ventilation page](/model.html?p=exhaust-and-muffler&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(249, 'en', 'Why choose the Industrial Exhaust, Mufflers & Ventilation?', 'why choose the industrial exhaust mufflers ventilation', 'What sets the Industrial Exhaust, Mufflers & Ventilation apart:\n- Designed to maintain low backpressure within manufacturer engine limits\n- Critical grade noise attenuation down to 25–35 dBA insertion loss\n- Flexible stainless expansion bellows absorb thermal expansion and vibration\n- Complete mechanical installation and heat shielding performed by 5A&M technicians\n[Industrial Exhaust, Mufflers & Ventilation page](/model.html?p=exhaust-and-muffler&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(250, 'en', 'When should I choose the Industrial Exhaust, Mufflers & Ventilation?', 'when should i choose the industrial exhaust mufflers ventilation', 'The Industrial Exhaust, Mufflers & Ventilation fits:\n- Basement power room retrofits\n- Commercial building exhaust shafts\n- Enclosed generator installations\n[Industrial Exhaust, Mufflers & Ventilation page](/model.html?p=exhaust-and-muffler&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(251, 'ar', 'ايه هو قطع غيار المحركات الأصلية؟', 'ايه هو قطع غيار المحركات الاصليه', 'قطع غيار المحركات الأصلية — 5A&M: قطع غيار أصلية لمولدات الكهرباء والمعدات الثقيلة تشمل المنظومات الميكانيكية والتبريد والحقن والوقود.\n[صفحة قطع غيار المحركات الأصلية](/model.html?p=engine-parts&lang=ar)\nتحب نجهّزلك عرض سعر؟ اضغط زرّ «كلّم موظف» تحت أو املأ طلب عرض السعر من الموقع.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(252, 'en', 'What is the Genuine Engine Parts?', 'what is the genuine engine parts', 'Genuine Engine Parts — 5A&M: Genuine engine parts for generator sets and heavy equipment, covering mechanical, cooling and fuel systems.\n[Genuine Engine Parts page](/model.html?p=engine-parts&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(253, 'en', 'What are the specifications of the Genuine Engine Parts?', 'what are the specifications of the genuine engine parts', 'Key specifications of the Genuine Engine Parts:\n- Partner brands supported: Cummins, Perkins, Baudouin, Doosan, Develon, Volvo\n- Systems covered: Pistons, cylinder liners, gaskets, turbochargers, fuel injectors, water pumps\n- Availability: Stocked in 5A&M Cairo warehouse for rapid emergency dispatch\n[Genuine Engine Parts page](/model.html?p=engine-parts&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(254, 'en', 'What are the advantages of the Genuine Engine Parts?', 'what are the advantages of the genuine engine parts', 'What sets the Genuine Engine Parts apart:\n- 100% genuine OEM certified parts backed by manufacturer warranty\n- Prevents premature engine failure and preserves original fuel efficiency\n- Stocked inventory minimizes equipment downtime across agricultural and industrial sites\n- Technical assistance provided by 5A&M engine overhaul specialists\n[Genuine Engine Parts page](/model.html?p=engine-parts&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(255, 'en', 'What is the Genuine Engine Parts used for?', 'what is the genuine engine parts used for', 'The Genuine Engine Parts fits:\n- Scheduled 250h / 1000h servicing\n- Major top and complete engine overhauls\n- Emergency breakdown repairs\n[Genuine Engine Parts page](/model.html?p=engine-parts&lang=en)\nWant a quotation? tap the “Talk to a person” button below or use the quote request on the site.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(256, 'ar', 'فلاتر فليت جارد وفلاتر المنظومات الصناعية ده ايه؟', 'فلاتر فليت جارد وفلاتر المنظومات الصناعيه ده ايه', 'فلاتر فليت جارد وفلاتر المنظومات الصناعية — Fleetguard: فلاتر ديفيلون الأصلية وفلاتر فليت جارد المعتمدة لحماية المحركات ومضاعفة عمرها الافتراضي.\n[صفحة فلاتر فليت جارد وفلاتر المنظومات الصناعية](/model.html?p=filters&lang=ar)\nلو حابب التفاصيل كاملة أو عرض سعر، اضغط زرّ «كلّم موظف» تحت.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(257, 'en', 'Tell me about the Industrial Filtration Kits', 'tell me about the industrial filtration kits', 'Industrial Filtration Kits — Fleetguard: Genuine Develon filters and Fleetguard filtration, to protect the engine and extend its life.\n[Industrial Filtration Kits page](/model.html?p=filters&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(258, 'en', 'Technical specs for the Industrial Filtration Kits?', 'technical specs for the industrial filtration kits', 'Key specifications of the Industrial Filtration Kits:\n- Filtration brands: Fleetguard, Develon Genuine\n- Filter types: Fuel water separators, lube oil filters, heavy-duty air intake filters, coolant filters\n- Efficiency rating: Stratapore synthetic media capturing sub-micron contaminants\n[Industrial Filtration Kits page](/model.html?p=filters&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
(259, 'en', 'Why choose the Industrial Filtration Kits?', 'why choose the industrial filtration kits', 'What sets the Industrial Filtration Kits apart:\n- Maximum engine protection in high-dust Egyptian desert operating environments\n- Preserves common-rail injectors and high-pressure pumps against fuel contamination\n- Packaged in convenient scheduled service interval kits for fast technician turnaround\n- Verified genuine OEM certification with zero counterfeit risk\n[Industrial Filtration Kits page](/model.html?p=filters&lang=en)\nFor full details or a quotation, tap the “Talk to a person” button below.', 'facts', 'new', NULL, 0, NULL, NULL, '2026-10-10 16:57:47', '2026-10-24 02:00:46'),
