INSERT INTO `chat_messages` (`id`, `conversation_id`, `role`, `user_id`, `text`, `files`, `reply_to`, `source`, `cache_id`, `created_at`, `read_at`) VALUES
(1, 1, 'user', NULL, 'عامل ايه', NULL, NULL, NULL, NULL, '2026-10-05 07:43:48', '2026-10-21 18:11:25'),
(2, 1, 'bot', NULL, 'أهلاً بيك! 👋\nعاملين تمام، شكراً لسؤالك.\nإزاي نقدر نساعدك النهارده؟ عندنا مجموعات توليد ديزل، حلول طاقة، معدات بيئية (Elgin, Vactor, Guzzler)، قطع غيار أصلية، وخدمة ما بعد البيع.', NULL, NULL, 'backup', NULL, '2026-10-05 07:44:06', '2026-10-21 01:36:24'),
(3, 1, 'user', NULL, 'عاوز اعرف عندكم طقم شنابر', NULL, NULL, NULL, NULL, '2026-10-05 07:45:06', '2026-10-21 18:11:25'),
(4, 1, 'bot', NULL, 'نعم، عندنا قطع غيار أصلية.\nبصفتنا الوكيل المعتمد لمعدات Elgin وVactor وGuzzler، نوفر مخزون مخصص من قطع الغيار الأصلية والمستهلكات لضمان استمرارية التشغيل.\n\nتحب تعرف تفاصيل عن نوع معين أو تطلب عرض سعر؟\nيمكنك طلب عرض سعر من فريق المبيعات، أو كتابة «موظف» للتواصل المباشر.\n\n[خدمات ما بعد البيع](/aftersales.html?lang=ar)', NULL, NULL, 'qwen', NULL, '2026-10-05 07:45:07', '2026-10-21 01:36:24'),
(29, 1, 'user', NULL, 'كيف الحال', NULL, NULL, NULL, NULL, '2026-10-05 07:53:31', '2026-10-21 18:11:25'),
(30, 1, 'bot', NULL, 'الحمد لله تمام، شكراً لسؤالك.\nإيه اللي تحب تسأل عنه؟ ممكن نساعدك في المولدات، المعدات البيئية، أو قطع الغيار.', NULL, NULL, 'qwen', NULL, '2026-10-05 07:53:33', '2026-10-21 01:36:24'),
(31, 1, 'user', NULL, 'عاوز اشتري عربية جازلير', NULL, NULL, NULL, NULL, '2026-10-05 07:53:53', '2026-10-21 18:11:25'),
(32, 1, 'bot', NULL, 'أهلاً بيك! 👋\nنحن الوكيل الحصري لـ **Guzzler** في مصر، وعندنا شاحنات الشفط الصناعي (Guzzler) بمواصفات عالية للأداء الثقيل.\n\nعشان نقدر نرشحلك الموديل المناسب، محتاجين منك معلومتين بس:\n1. **نوع المادة** اللي هتشفطها (سوايل، حمأة، مواد جافة، خطرة…).\n2. **سعة الخزان** المطلوبة (متر مكعب / جالون).\n\nممكن تطلب عرض سعر رسمي من فريق المبيعات، أو تكتب «موظف» للتواصل المباشر.\n\n[شاحنة الشفط الصناعي Guzzler](/guzzler.html?lang=ar)', NULL, NULL, 'backup', NULL, '2026-10-05 07:54:01', '2026-10-21 01:36:24'),
(38, 1, 'user', NULL, 'ازيك عامل ايه', NULL, NULL, NULL, NULL, '2026-10-05 08:02:05', '2026-10-21 18:11:25'),
(39, 1, 'bot', NULL, 'الحمد لله تمام، شكراً على سؤالك.\nإيه اللي تحب تسأل عنه؟ ممكن نساعدك في المولدات، المعدات البيئية، أو قطع الغيار.', NULL, NULL, 'qwen', NULL, '2026-10-05 08:02:15', '2026-10-21 01:36:24'),
(40, 1, 'user', NULL, 'ايه الاخبار طيب', NULL, NULL, NULL, NULL, '2026-10-05 08:02:39', '2026-10-21 18:11:25'),
(41, 1, 'bot', NULL, 'الحمد لله تمام، شكراً لسؤالك.\nإيه اللي تحب تسأل عنه؟ ممكن نساعدك في المولدات، المعدات البيئية، أو قطع الغيار.', NULL, NULL, 'qwen', NULL, '2026-10-05 08:02:40', '2026-10-21 01:36:24'),
(42, 1, 'user', NULL, 'انا عايز طقم شنابر و عايز بوجيهات عايز عربية جزلر', NULL, NULL, NULL, NULL, '2026-10-05 08:03:23', '2026-10-21 18:11:25'),
(43, 1, 'bot', NULL, 'أهلاً بيك! عندنا قطع غيار أصلية (شنابر وبوجيهات) وشاحنات Guzzler.\n\nعشان نجهزلك عرض سعر دقيق، محتاجين منك:\n- **موديل** الشنابر والبوجيهات.\n- **نوع** شاحنة Guzzler المطلوبة (سعة الخزان ونوع الشفط).\n\nممكن تكتب «موظف» للتواصل مع الفريق مباشرة.\n\n[قطع غيار Guzzler](/guzzler-parts.html?lang=ar)', NULL, NULL, 'qwen', 55, '2026-10-05 08:03:33', '2026-10-21 01:36:24'),
(44, 1, 'user', NULL, 'ديفليون', NULL, NULL, NULL, NULL, '2026-10-05 08:03:50', '2026-10-21 18:11:25'),
(45, 1, 'bot', NULL, 'أهلاً بيك! عندنا قطع غيار أصلية لـ **Elgin** (الكناس) و **Vactor** و **Guzzler**.\n\nعشان نقدر نحددلك شنابر وبوجيهات وشاحنة Guzzler المناسبة، محتاجين منك:\n- **موديل** الماكينة أو رقم الشاصي (VIN).\n- **سعة الخزان** ونوع الشفط لشاحنة Guzzler.\n\nممكن تكتب «موظف» للتواصل مع الفريق مباشرة.\n\n[قطع غيار Elgin](/elgin-parts.html?lang=ar) | [قطع غيار Vactor](/vactor-parts.html?lang=ar) | [قطع غيار Guzzler](/guzzler-parts.html?lang=ar)', NULL, NULL, 'backup', NULL, '2026-10-05 08:04:00', '2026-10-21 01:36:24'),
(46, 1, 'user', NULL, 'موظف', NULL, NULL, NULL, NULL, '2026-10-05 08:04:22', '2026-10-21 18:11:25'),
(47, 1, 'bot', NULL, 'أكيد! اكتب اسمك ورقم موبايلك في الخانات اللي ظهرت، وهيكلمك حد من فريقنا في أقرب وقت. 🙏', NULL, NULL, NULL, NULL, '2026-10-05 08:04:22', '2026-10-21 01:36:24'),
(48, 1, 'system', NULL, 'Your request reached our team — someone will reply here in this chat or call you.', NULL, NULL, NULL, NULL, '2026-10-05 08:04:30', '2026-10-21 01:36:24'),
(49, 1, 'agent', 1, 'اهلا وسهللا بحضرتك', NULL, NULL, NULL, NULL, '2026-10-05 08:05:12', '2026-10-21 01:36:24'),
(50, 1, 'agent', 1, 'حضرتك محتاج ايه بالظبط', NULL, NULL, NULL, NULL, '2026-10-05 08:05:30', '2026-10-21 01:36:24'),
(51, 1, 'user', NULL, 'الحمد لله بخير', NULL, NULL, NULL, NULL, '2026-10-05 08:05:52', '2026-10-21 18:11:25'),
(52, 1, 'system', NULL, 'رجعت للمساعد الآلي.', NULL, NULL, NULL, NULL, '2026-10-05 08:06:25', '2026-10-21 01:36:24'),
(53, 1, 'agent', 1, 'الحمد لله على السلامة.\n\nإزاي أقدر أساعدك النهارده؟\n- محتاج عرض سعر لقطعة غيار؟\n- عندك مشكلة في الماكينة؟\n- بتدور على نوع معين من المعدات؟\n\nقولي التفاصيل وأنا معاك.', NULL, NULL, NULL, NULL, '2026-10-05 08:06:37', '2026-10-21 01:36:24'),
(54, 1, 'user', NULL, 'عايز تيشيرت', NULL, NULL, NULL, NULL, '2026-10-05 08:06:56', '2026-10-21 18:11:25'),
(55, 1, 'bot', NULL, 'عذراً، مش متأكد إن عندنا تيشيرتات في الموقع ده. إحنا متخصصين في الديزل، المعدات البيئية (Elgin, Vactor, Guzzler)، وقطع الغيار الأصلية.\n\nلو تقصد قطعة غيار معينة، ممكن توضح لي الموديل؟\nأو لو عايز تتواصل مع الفريق، اضغط زرّ «كلّم موظف» تحت.', NULL, NULL, 'qwen', NULL, '2026-10-05 08:07:04', '2026-10-21 01:36:24'),
(56, 1, 'agent', 1, 'أنا مش متأكد إن عندنا تيشيرتات في الموقع ده.\n\nالموقع متخصص في:\n- مولدات الديزل\n- معدات البيئة (كنس، شفط)\n- قطع غيار أصلية\n- خدمات ما بعد البيع\n\nلو تقصد حاجة تانية، ممكن توضحلي؟ أو لو عايز تتكلم مع حد من الفريق، اضغط زرّ «كلّم موظف» تحت.', NULL, NULL, NULL, NULL, '2026-10-05 08:07:14', '2026-10-21 01:36:24'),
(57, 1, 'user', NULL, 'السلام عليكم', NULL, NULL, NULL, NULL, '2026-10-05 08:58:39', '2026-10-21 18:11:25'),
(58, 1, 'bot', NULL, 'أهلًا بك في 5A&M 👋 اسألني عن المولدات أو المعدات البيئية أو قطع الغيار، أو اطلب التحدث مع موظف.', NULL, NULL, NULL, NULL, '2026-10-05 08:58:39', '2026-10-21 01:36:24'),
(59, 1, 'agent', 1, 'اهلا بيك عامل ايه', NULL, NULL, NULL, NULL, '2026-10-05 09:01:29', '2026-10-21 01:36:24'),
(60, 1, 'agent', 1, 'عايوز تشتري ايه', NULL, NULL, NULL, NULL, '2026-10-05 09:01:52', '2026-10-21 01:36:24'),
(61, 1, 'agent', 1, 'أهلًا بك في 5A&M 👋 اسألني عن المولدات أو المعدات البيئية أو قطع الغيار، أو اطلب التحدث مع موظف.', NULL, NULL, NULL, NULL, '2026-10-05 09:02:47', '2026-10-21 01:36:24'),
