(1, 'environment', 'sections', 0, 1, 'Environmental Solutions', 'حلول البيئة', NULL, 'Environmental Solutions — 5A&M', NULL, 'Elgin, Vactor and Guzzler equipment supplied in Egypt by 5A&M, the exclusive authorized dealer for Federal Signal Environmental Solutions Group.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/range/env-vactor.jpg","lede":{"ar":"شركة 5A&M هي الوكيل الحصري المعتمد في مصر لعلامات رائدة ضمن مجموعة Federal Signal Environmental Solutions (Elgin, Vactor, Guzzler).","en":"5A&M is the Exclusive Authorized Dealer in Egypt for leading brands within Federal Signal Environmental Solutions Group (Elgin, Vactor, Guzzler)."},"title":{"ar":"حلول البيئة","en":"Environmental Solutions"},"kicker":{"ar":"وكيل حصري معتمد — مصر","en":"Exclusive authorized dealer — Egypt"}}', NULL, 'environmental', NULL, '2026-09-30 22:47:02', '2026-09-30 22:47:02'),
(2, 'power', 'sections', 1, 1, 'Power Solutions', 'حلول الطاقة', NULL, 'Power Solutions — 5A&M', NULL, 'Generator sales and rental, overhauls, fabrication, installation, spare parts and maintenance by 5A&M.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/range/genset-canopy.jpg","lede":{"ar":"المولدات الكهربائية مصممة لتوفير أداء ثابت وموثوق في ظل درجات الحرارة المرتفعة والأتربة والرطوبة ومختلف ظروف التشغيل، مع دعم تطبيقات الطاقة المستمرة والاحتياطية والمؤقتة في مختلف القطاعات. ","en":"Generator sales and rental, efficiency upgrades and full overhauls, and fabrication and installation by our own team."},"title":{"ar":"حلول الطاقة","en":"Power Solutions"},"kicker":{"ar":"نطاق العمل","en":"Scope of work"}}', NULL, 'power', NULL, '2026-09-30 22:47:02', '2026-10-18 21:54:30'),
(3, 'generators', 'sections', 2, 1, 'Generator sales & rental', 'بيع وإيجار المولدات', 'power', 'Generator sales & rental — 5A&M', NULL, 'Diesel generator sets from 10 to 2500 kVA, built with genuine Perkins, Cummins, Hyundai and Volvo engines.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/range/genset-canopy.jpg","title":{"ar":"بيع وإيجار المولدات","en":"Generator sales & rental"},"kicker":{"ar":"حلول الطاقة","en":"Power Solutions"}}', NULL, 'power', NULL, '2026-09-30 22:47:02', '2026-10-20 03:33:47'),
(4, 'rental', 'sections', 3, 1, 'Generator rental', 'إيجار المولدات', 'power', 'Generator rental — 5A&M', NULL, 'Rental power generators from 20 kVA up to 1000 kVA, delivered, installed and supported by 5A&M.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/range/genset-rental.jpg","lede":{"ar":"مولدات للإيجار من 20 حتى 1000 kVA.","en":"Rental power generators from 20 kVA up to 1000 kVA."},"title":{"ar":"إيجار المولدات","en":"Generator rental"},"kicker":{"ar":"حلول الطاقة","en":"Power Solutions"}}', NULL, 'rental', 'generators.html#rental', '2026-09-30 22:47:02', '2026-09-30 22:47:02'),
(5, 'overhaul', 'sections', 4, 1, 'Efficiency upgrades & overhauls', 'أعمال رفع الكفاءة', 'power', 'Efficiency upgrades & overhauls — 5A&M', NULL, 'Replace the old engine with a new one and reuse the tested alternator, control and chassis.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/photos/genset-workshop.jpg","lede":{"ar":"توفر حلول استبدال المحركات والعمرات الشاملة كفاءة تشغيلية عالية، من خلال استعادة أداء المولدات المستهلكة وإطالة عمرها التشغيلي.","en":"Engine replacement and complete overhaul solutions deliver enhanced operating performance by restoring the efficiency of generator sets and extending their service life."},"title":{"ar":"أعمال رفع الكفاءة","en":"Repowering and Overhauls"},"kicker":{"ar":"حلول الطاقة","en":"Power Solutions"}}', NULL, 'repowering', NULL, '2026-09-30 22:47:02', '2026-10-04 13:21:15'),
(6, 'fabrication', 'sections', 5, 1, 'Fabrication & installation', 'أعمال الصناعة والتركيبات', 'power', 'Fabrication & installation — 5A&M', NULL, 'Generator canopies, electrical panels, fuel tanks and on-site installation by the 5A&M team.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/photos/card-installation.jpg","lede":{"ar":"أعمال الصاج وأعمال الموقع بفريقنا: كبائن المولدات، واللوحات الكهربائية، وتانكات الوقود ومشتملاتها، وتركيب المولدات وتجهيزها للعمل.","en":"Sheet metal works and site works by our own team: generator canopies, electrical panels, fuel tanks and accessories, and the installation that puts a generator to work."},"title":{"ar":"أعمال الصناعة والتركيبات","en":"Fabrication & installation"},"kicker":{"ar":"حلول الطاقة","en":"Power Solutions"}}', NULL, 'engineering', NULL, '2026-09-30 22:47:02', '2026-09-30 22:47:02'),
(7, 'aftersales', 'sections', 6, 1, 'After-sales services', 'خدمات ما بعد البيع', NULL, 'After-sales services — 5A&M', NULL, 'After-sales and field service teams, emergency breakdown response and warranty support.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/photos/genset-workshop.jpg","lede":{"ar":"دعم فني متخصص لما بعد البيع، قطع غيار أصلية وصيانة احترافية.","en":"A trained after-sales team, genuine spare parts from stock, on-site maintenance under contract, and a solid warranty on every generator we deliver."},"title":{"ar":"خدمات ما بعد البيع","en":"After-sales services"},"kicker":{"ar":"دعم يستمر بعد التسليم","en":"Support beyond delivery"}}', '["parts","maintenance"]', 'service', NULL, '2026-09-30 22:47:02', '2026-10-04 14:50:56'),
(8, 'maintenance', 'sections', 7, 1, 'Site maintenance & maintenance contracts', 'صيانة المواقع وعقود الصيانة', 'aftersales', 'Site maintenance & maintenance contracts — 5A&M', NULL, 'Periodic, preventive and corrective maintenance at your site, on contract.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/photos/site-installation.jpg","lede":{"ar":"فريق خدمة ميدانية ذو خبرة في موقعك، وعقد صيانة يُبقي معداتك في رعايتنا طوال عمرها التشغيلي.","en":"An experienced field service team at your site, and a maintenance contract that keeps your equipment in our care for its whole operating life."},"title":{"ar":"صيانة المواقع وعقود الصيانة","en":"Site maintenance & maintenance contracts"},"kicker":{"ar":"خدمات ما بعد البيع","en":"After-sales services"}}', '["parts","aftersales"]', 'service', NULL, '2026-09-30 22:47:02', '2026-09-30 22:47:02'),
(9, 'projects', 'sections', 8, 1, 'Projects', 'المشروعات', NULL, 'Projects — 5A&M', NULL, 'Generator installation, repowering, canopy fabrication, fuel systems, control panels and field service delivered by 5A&M.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/photos/site-installation.jpg","lede":{"ar":"وراء كل نجاح التزام بتقديم الحل الأمثل .","en":"Behind Every Success, a Commitment to Deliver the Ideal Solution"},"title":{"ar":"حلول حقيقية. أثر حقيقي.","en":"Real solutions. Real impact."}}', NULL, NULL, NULL, '2026-09-30 22:47:02', '2026-10-04 14:52:09'),
(10, 'about', 'sections', 9, 1, 'About us', 'من نحن', NULL, 'About — 5A&M for Import, Export and Contracting', NULL, '5A&M is an Egyptian company established in 2022, specialised in power generation and industrial equipment — our vision, mission, values and story.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/photos/genset-workshop.jpg","title":{"ar":"من نحن","en":"About us"}}', NULL, NULL, NULL, '2026-09-30 22:47:02', '2026-09-30 22:47:02'),
(11, 'parts', 'sections', 10, 1, 'Genuine spare parts', 'قطع الغيار الأصلية', 'aftersales', 'Genuine spare parts — 5A&M', NULL, 'Genuine parts and filters for generators, heavy equipment and environmental units.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/photos/card-overhaul.jpg","title":{"ar":"قطع الغيار الأصلية","en":"Genuine spare parts"},"kicker":{"ar":"خدمات ما بعد البيع","en":"After-sales services"}}', '["aftersales","maintenance"]', 'parts', NULL, '2026-09-30 22:47:02', '2026-09-30 22:47:02'),
(12, 'sectors', 'sections', 11, 1, 'Sectors', 'القطاعات', NULL, 'Sectors — 5A&M', NULL, 'Oil & gas, agricultural development and industry — the sectors 5A&M serves across Egypt.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/photos/site-installation.jpg","lede":{"ar":"نفس الثلاثة: المعدة، والتركيب، والخدمة — مصمّمة حسب طبيعة تشغيل كل قطاع.","en":"The same three things — equipment, installation and service — shaped around what each sector actually runs."},"title":{"ar":"القطاعات التي نخدمها","en":"Sectors we serve"},"kicker":{"ar":"الأسواق","en":"Markets"}}', NULL, NULL, 'projects.html', '2026-09-30 22:47:02', '2026-09-30 22:47:02'),
(13, 'sector-oil', 'sections', 12, 1, 'Oil & gas', 'قطاع البترول', 'sectors', 'Oil & gas — 5A&M', NULL, 'Vacuum equipment and power generation for oil & gas field and facility operations.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/range/guzzler-guzzcavator.jpg","lede":{"ar":"معدات شفط للتعامل مع المخلفات الصلبة والرواسب في مواقع البترول والغاز، إلى جانب توليد الطاقة بالديزل والغاز لعمليات الحقول والمنشآت.","en":"Vacuum equipment for solid waste and residue handling at oil & gas sites, plus diesel and gas power generation for field and facility operations."},"title":{"ar":"قطاع البترول","en":"Oil & gas"},"kicker":{"ar":"القطاعات","en":"Sectors"}}', '["generators","rental","environment","maintenance"]', NULL, 'projects.html#oil', '2026-09-30 22:47:02', '2026-09-30 22:47:02'),
(14, 'sector-agri', 'sections', 13, 1, 'Agricultural development', 'قطاع التنمية الزراعية', 'sectors', 'Agricultural development — 5A&M', NULL, 'Power generation for farms, irrigation and pumping.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/photos/card-sector-agri.jpg","lede":{"ar":"حلول توليد الطاقة للمزارع والري والضخ والعمليات الزراعية — وهو القطاع الذي بدأت منه 5A&M بتوريد قطع الغيار قبل المولدات.","en":"Power generation solutions for farms, irrigation, pumping and agricultural operations — the sector 5A&M started in, supplying spare parts before it supplied generators."},"title":{"ar":"قطاع التنمية الزراعية","en":"Agricultural development"},"kicker":{"ar":"القطاعات","en":"Sectors"}}', '["generators","overhaul","parts","maintenance"]', NULL, 'projects.html#agri', '2026-09-30 22:47:02', '2026-09-30 22:47:02'),
(15, 'sector-industry', 'sections', 14, 1, 'Industry', 'قطاع الصناعة', 'sectors', 'Industry — 5A&M', NULL, 'Power generation, panels and industrial cleaning equipment for plants and facilities.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/photos/genset-workshop.jpg","lede":{"ar":"أعمال التنظيف الثقيل وتطبيقات الشفط ومعدات توليد الطاقة للمنشآت الصناعية والمواقع التجارية والمؤسسات.","en":"Heavy-duty cleaning, vacuum applications and power generation equipment for industrial facilities, commercial sites and institutions."},"title":{"ar":"قطاع الصناعة","en":"Industry"},"kicker":{"ar":"القطاعات","en":"Sectors"}}', '["generators","fabrication","maintenance"]', NULL, 'projects.html#industry', '2026-09-30 22:47:02', '2026-09-30 22:47:02'),
(16, 'contact', 'sections', 15, 1, 'Contact', 'التواصل', NULL, 'Contact — 5A&M', NULL, 'Head office and workshop in the 5th Settlement, New Cairo. Phone, email and directions.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, '{"img":"assets/img/photos/field-service.jpg","lede":{"ar":"اتصل بنا، أو راسلنا، أو زُرنا في مقرنا الرئيسي بالقاهرة الجديدة أو مركز الخدمة في مسطرد.","en":"Call us, email us, or visit our head office in New Cairo and our service center in Mostorod."},"title":{"ar":"تواصل مع 5A&M","en":"Contact 5A&M"}}', NULL, NULL, NULL, '2026-09-30 22:47:02', '2026-09-30 22:47:02'),
(17, 'index', 'onepage', 16, 1, 'Home', 'الرئيسية', NULL, '5A&M for Import, Export and Contracting — Power Generation & Environmental Solutions in Egypt', NULL, '5A&M supplies Elgin, Vactor and Guzzler environmental equipment and diesel generator sets from 10 to 2500 kVA across Egypt, backed by engineering, spare parts and after-sales service.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, NULL, NULL, NULL, NULL, '2026-09-30 22:47:13', '2026-10-20 04:37:20'),
(18, 'model', 'product', 17, 1, 'Equipment', 'المعدات', NULL, 'Equipment specification — 5A&M', NULL, 'Specification, features and applications for equipment supplied and supported by 5A&M in Egypt.', NULL, 'https://www.5a-eg.com/assets/img/photos/genset-5am-canopy.jpg', 0, NULL, NULL, NULL, NULL, '2026-09-30 22:47:13', '2026-09-30 22:47:13'),
(19, 'quote', 'quote', 18, 1, 'Request a quote', 'اطلب عرض سعر', NULL, 'Request a quote — 5A&M', NULL, 'Send us the load, the site and the operating conditions, and our team will come back with a quotation.', NULL, NULL, 0, '{"img":"assets/img/photos/site-installation.jpg","lede":{"ar":"تفاصيل بسيطة تساعد فريقنا على فهم احتياجك من المعدات أو خدمات الموقع.","en":"A few details help our team understand your equipment, project or service needs."},"title":{"ar":"اطلب عرض سعر أو خدمة","en":"Request a quote or service"}}', NULL, NULL, NULL, '2026-09-30 22:47:13', '2026-09-30 22:47:13'),
(20, 'equipment', 'equipment', 19, 1, 'Equipment', 'المعدات', NULL, 'Equipment we supply — 5A&M', NULL, 'The equipment 5A&M supplies and supports in Egypt: Elgin, Vactor and Guzzler environmental machines, diesel generator sets from 10 to 2500 kVA built in-house, and genuine spare parts.', NULL, NULL, 0, '{"img":"assets/img/photos/genset-workshop.jpg","lede":{"ar":"⁦5A&M⁩ هي الوكيل الحصري المعتمد في مصر لمجموعة Federal Signal Environmental Solutions، وبتبني مولداتها بنفسها من 10 إلى ⁦2500 kVA⁩، وبتحتفظ بقطع غيار أصلية لكل ما توردّه. كل ماكينة تحت بتتحدد مواصفتها حسب التطبيق قبل ما يتقدّم أي عرض.","en":"5A&M is the exclusive authorised dealer in Egypt for Federal Signal Environmental Solutions Group, builds its own generator sets from 10 to 2500 kVA, and holds genuine parts for what it sells. Every machine below is specified against the application before it is quoted."},"title":{"ar":"المعدات اللي بنوردّها، وبنقف وراها","en":"The equipment we supply, and stand behind"}}', NULL, NULL, NULL, '2026-09-30 22:47:13', '2026-09-30 22:47:13'),
(28, 'elgin-sweepers', 'sections', 22, 1, 'Road sweepers', 'مكانس الطرق', 'environment', 'Elgin road sweepers — Crosswind, Whirlwind and Pelican | 5A&M', NULL, 'The three Elgin street sweeper ranges 5A&M supplies in Egypt: regenerative air, pure vacuum and mechanical broom.', NULL, NULL, 0, '{"img":"assets/img/range/env-elgin.jpg","lede":{"ar":"حلول كنس احترافية للطرق والشوارع والبلديات والبنية التحتية والمشروعات الكبرى.","en":"Professional sweeping solutions for roads, streets, municipalities, infrastructure and large-scale developments."},"title":{"ar":"مكانس الطرق","en":"Road sweepers"}}', NULL, NULL, NULL, '2026-10-01 22:36:28', '2026-10-06 11:40:24'),
(51, 'vactor-units', 'sections', 23, 1, 'Road & infrastructure units', 'وحدات الطرق والبنية التحتية', 'environment', 'Vactor sewer & infrastructure units | 5A&M', NULL, 'Vactor combination units 5A&M supplies in Egypt for sewer cleaning, catch-basin cleaning and hydro-excavation.', NULL, NULL, 0, '{"img":"assets/img/range/env-vactor.jpg","lede":{"ar":"معدات متخصصة لتنظيف شبكات الصرف وبيارات التجميع والحفر بالشفط المائي وصيانة البنية التحتية.","en":"Specialized equipment for sewer cleaning, catch-basin cleaning, hydro-excavation and infrastructure maintenance."},"title":{"ar":"وحدات الطرق والبنية التحتية","en":"Road & infrastructure units"}}', NULL, NULL, NULL, '2026-10-04 12:23:15', '2026-10-04 12:23:15'),
(52, 'guzzler-vacuums', 'sections', 23, 1, 'Industrial vacuum equipment', 'معدات الشفط الصناعي', 'environment', 'Guzzler industrial vacuum loaders | 5A&M', NULL, 'Guzzler industrial vacuum loaders 5A&M supplies in Egypt for industrial, environmental and material-recovery work.', NULL, NULL, 0, '{"img":"assets/img/range/env-guzzler.jpg","lede":{"ar":"حلول شفط عالية الأداء للتطبيقات الصناعية والبيئية واستعادة المواد في ظروف التشغيل الصعبة.","en":"High-performance vacuum solutions for industrial, environmental and demanding material recovery applications."},"title":{"ar":"معدات الشفط الصناعي","en":"Industrial vacuum equipment"}}', NULL, NULL, NULL, '2026-10-04 12:23:15', '2026-10-04 12:23:15'),
(53, 'store', 'store', 24, 1, 'Store', 'المتجر', NULL, 'Store — Equipment & Spare Parts | 5A&M', 'المتجر — المعدات وقطع الغيار | 5A&M', 'Browse 5A&M generators, environmental equipment and genuine spare parts, and request a quote for several items at once.', 'تصفح مولدات 5A&M والمعدات البيئية وقطع الغيار الأصلية، واطلب عرض سعر لأكثر من منتج مرة واحدة.', NULL, 0, '{"lede":{"ar":"كل المولدات والمعدات البيئية وقطع الغيار الأصلية التي نوردها في مكان واحد. أضف ما تحتاجه لطلب عرض السعر، ويرد عليك فريق المبيعات بالأسعار والتوافر.","en":"Every generator, environmental unit and genuine spare part we supply — in one place. Add what you need to your quote request and our sales team will reply with prices and availability."},"title":{"ar":"المعدات وقطع الغيار","en":"Equipment & spare parts"},"kicker":{"ar":"المتجر","en":"Store"}}', NULL, NULL, NULL, '2026-10-04 19:58:22', '2026-10-04 19:58:22');
