INSERT INTO `products` (`id`, `ref`, `slug`, `brand_id`, `category`, `subcategory`, `position`, `published`, `name_en`, `name_ar`, `type_en`, `type_ar`, `description_en`, `description_ar`, `hero_image`, `data`, `created_at`, `updated_at`, `sku`, `store_hidden`) VALUES
(1, 'elgin-crosswind', 'elgin-crosswind', 2, 'environmental', 'Regenerative Air', 0, 1, 'Crosswind', NULL, 'Regenerative air high-velocity street sweeper', 'مكنسة شوارع عالية الأداء بنظام الهواء المتجدد', 'Elgin Regenerative Air Sweepers deliver powerful performance and versatility across a wide range of sweeping and cleaning applications.\r\nThe Elgin Crosswind efficiently cleans large, paved areas such as streets, parking lots, and airport runways, while its short-wheelbase truck chassis provides excellent maneuverability.\r\nFeatures:\r\n- 9-vane high-velocity turbine fan with a rubber-lined housing for enhanced durability and extended service life.\r\n- LifeLiner hopper liner system for extended hopper life, durability, and smoother dumping.\r\n- 12-ft. (3,658 mm) sweep path with a 90-in. (2,286 mm) pickup head and dual 42-in. (1,067 mm) hydraulic side brooms.\r\n- Enhanced vacuum performance for efficient pickup of light and bulky debris, including curbside areas.', 'تقدم مكانس الجين بتقنية الهواء المتجدد (Regenerative Air) أداءً قويًا ومرونة عالية في أعمال الكنس والتنظيف.\r\nتتميز الجين Crosswind بكفاءة عالية في تنظيف المساحات المرصوفة الواسعة، مثل الشوارع ومواقف السيارات ومدارج المطارات، مع قدرة ممتازة على المناورة بفضل تركيبها على شاسيه قصير.\r\nالمميزات:\r\n- وحدة  شفط عالية السرعة بتسع ريش مع هيكل مبطن بالمطاط لمتانة أعلى وعمر تشغيلي أطول.\r\n- نظام تبطين خزان المخلفات LifeLiner لإطالة عمر الخزان، وتعزيز متانته، وتسهيل عملية التفريغ.\r\n- مسار كنس بعرض 12 قدمًا (3,658 مم) مع رأس كنس بعرض 90 بوصة (2,286 مم) وفرشتين جانبيتين بنظام هيدروليكي مقاس 42 بوصة (1,067 مم).\r\n-  أداء شفط مُحسّن لالتقاط المخلفات الخفيفة وكبيرة الحجم بكفاءة، بما في ذلك المخلفات بجوار الأرصفة.', 'media/img/chatgpt-image-sep-27-2026-05_15_19-am-1-efa77279.png', '{"meta":[{"k":"Application","v":"Street & Airport Sweeping"},{"k":"Product Type","v":"Regenerative Air Sweeper"}],"videos":[{"ar":"سبب إضافي لاختيار Crosswind","en":"One more reason to choose Crosswind","yt":"EECvS0rzyRk","len":"0:31","src":"assets/video/elgin/crosswind/one-more-reason.mp4","poster":"assets/video/elgin/crosswind/one-more-reason.jpg"},{"ar":"المكنسة أثناء العمل","en":"Sweeping in the field","yt":"EiVFBS8IMOo","len":"0:49","src":"assets/video/elgin/crosswind/sweeping.mp4","poster":"assets/video/elgin/crosswind/sweeping.jpg"},{"ar":"كيف يعمل نظام الطاقة المشتركة","en":"How SharedPower works","yt":"cPoRx_cwKmI","len":"0:55","src":"assets/video/elgin/crosswind/shared-power.mp4","poster":"assets/video/elgin/crosswind/shared-power.jpg"},{"ar":"شرح صندوق التروس الكوكبي","en":"The planetary gearbox explained","yt":"31yGcRVtnho","len":"3:00","src":"assets/video/elgin/crosswind/planetary-gearbox.mp4","poster":"assets/video/elgin/crosswind/planetary-gearbox.jpg"}],"gallery":["media/img/chatgpt-image-sep-27-2026-05_15_26-am-2-6d92c645.png","assets/img/elgin/crosswind/g01.webp","assets/img/elgin/crosswind/g02.webp","assets/img/elgin/crosswind/g03.webp","assets/img/elgin/crosswind/g04.webp","assets/img/elgin/crosswind/g05.webp","assets/img/elgin/crosswind/g06.webp","assets/img/elgin/crosswind/g07.webp","assets/img/elgin/crosswind/g08.webp"],"related":["elgin-whirlwind","elgin-pelican"],"features":["Closed-loop regenerative air system with zero exhaust dust emission","Trapped particulate pick-up from porous and textured asphalt","Large 8-yard hopper allows extended shifts without frequent dumping","Dual trailing-arm gutter brooms with tilt adjustment"],"downloads":[{"href":"assets/img/elgin/crosswind/spec-sheet.pdf","label":"Crosswind¹ spec sheet (PDF)"},{"href":"assets/img/elgin/crosswind/brochure.pdf","label":"Crosswind 1 brochure (PDF)"},{"href":"assets/img/elgin/crosswind/spec-sheet-fsx.pdf","label":"Spec sheet — FSX version (PDF)"},{"href":"assets/img/elgin/crosswind/sell-sheet-grs.pdf","label":"Sell sheet — GRS version (PDF)"}],"applications":["Municipal boulevards & wide avenues","Airport runways and aprons","Porous asphalt & stormwater environmental compliance","Logistics hubs"],"specifications":[{"k":"Sweeping technology","v":"Regenerative air — closed-loop circuit"},{"k":"Sweep path — pickup head only","v":"2,286 mm (90 in)"},{"k":"Sweep path — head + one broom","v":"2,971 mm (117 in)"},{"k":"Sweep path — head + two brooms","v":"3,658 mm (144 in)"},{"k":"Hopper volume","v":"6 m³ (8 cu yd)"},{"k":"Dump angle","v":"50°"},{"k":"Hopper lifting","v":"Hydraulic, two-stage telescoping cylinder"},{"k":"Dust separator","v":"Self-cleaning centrifugal"},{"k":"Chassis engine","v":"Cummins ISB 6.7 — in-line 6 turbo diesel"},{"k":"Engine output","v":"200 hp (150 kW) @ 2400 rpm"},{"k":"Engine torque","v":"708 Nm (520 ft-lb) @ 1600 rpm"},{"k":"Fuel tank capacity","v":"189 L (50 gal)"},{"k":"Variable speed device","v":"Planetary gearbox — replaces the auxiliary engine"},{"k":"Water tank capacity","v":"908 L (240 gal)"},{"k":"Water pump","v":"Diaphragm, run-dry — 30 L/min at 2.7 bar"},{"k":"Spray nozzles","v":"16 (21 with the optional centre broom)"},{"k":"Blower construction","v":"Hardox steel, 3.4 mm housing, urethane-lined"},{"k":"Electrical system","v":"12 V — 1000 CCA battery, 160 A alternator"},{"k":"Travel speed","v":"Up to highway speed"},{"k":"Chassis"}]}', '2026-09-30 22:47:02', '2026-10-06 06:59:30', NULL, 0),
(2, 'elgin-whirlwind', 'elgin-whirlwind', 2, 'environmental', 'Vacuum Sweepers', 1, 1, 'Whirlwind', NULL, 'Truck-mounted pure vacuum street sweeper', 'مكنسة شوارع بالشفط الخالص مركّبة على شاسيه شاحنة', 'The Elgin Whirlwind has revolutionized truck-mounted vacuum sweeping performance with its advanced design and exceptional flexibility. Its low-maintenance design combines a wide sweeping path with a short wheelbase, providing outstanding maneuverability and versatility across a wide range of applications.\r\nSince 1969, Whirlwind has remained at the forefront of the vacuum sweeping market, featuring a unique vacuum nozzle and robust, durable construction that delivers dependable performance across a variety of street cleaning and maintenance applications.\r\nFeatures:\r\n-High-velocity 9-vane Blower with Hardox® steel vanes. \r\n-High-volume, high-velocity airflow for efficient one-pass pickup.\r\n-32-inch (813 mm) abrasion-resistant suction nozzle for improved curbside cleaning.\r\n-8 yd³ (6 m³) high-capacity hopper with abrasion-resistant steel deflectors for efficient debris loading and maximum capacity utilization.\r\n-hopper with 10-gauge steel walls, a ¼-inch (6.35 mm) floor, and a 50° dump angle for fast, complete unloading and easy cleanup.', 'أحدثت الجين Whirlwind نقلة نوعية في أداء مكانس الشفط المثبتة على الشاحنات، بفضل تصميمها المتطور ومرونتها العالية. ويجمع تصميمها منخفض الصيانة وبين مسار كنس واسع وقاعدة عجلات قصيرة، مما يوفر قدرة فائقة على المناورة والتكيف مع مختلف التطبيقات.\r\nمنذ عام 1969، تواصل Whirlwind ريادتها في مجال مكانس الشفط، بفضل فوهة الشفط الفريدة وتصميمها القوي والمتين، لتوفر أداءً موثوقًا في مختلف تطبيقات تنظيف وصيانة الشوارع.\r\nالمميزات:\r\n- وحدة شفط عالية السرعة ذات تسع ريش مصنوعة من فولاذ Hardox لمتانة عالية وتدفق هواء قوي.\r\n- تدفق هواء عالي الحجم والسرعة لالتقاط المخلفات بكفاءة من المرور الأول.\r\n- فوهة شفط مقاومة للتآكل مقاس 32 بوصة (813 مم) لتنظيف أكثر كفاءة بجوار الأرصفة.\r\n- خزان مخلفات عالي السعة 8 ياردة³ (6 م³) مع حواجز من الفولاذ المقاوم للتآكل لتحميل المخلفات بكفاءة والاستفادة القصوى من السعة.\r\n- خزان مخلفات متين بجدران من فولاذ 10  درجات وأرضية بسُمك ¼ بوصة (6.35 مم) وزاوية تفريغ 50° لتفريغ سريع وكامل وسهولة التنظيف.', 'assets/img/elgin/whirlwind/hero.webp', '{"meta":[{"k":"Application","v":"Street Sweeping"},{"k":"Product Type","v":"Pure Vacuum Sweeper"}],"videos":[{"ar":"اختبار رفع الأحجار","en":"Street sweeper rock demo","yt":"YR9GGTMsNog","len":"0:47","src":"assets/video/elgin/whirlwind/rock-show.mp4","poster":"assets/video/elgin/whirlwind/rock-show.jpg"},{"ar":"كيف يعمل نظام الطاقة المشتركة","en":"How SharedPower works","yt":"cPoRx_cwKmI","len":"0:55","src":"assets/video/elgin/whirlwind/shared-power.mp4","poster":"assets/video/elgin/whirlwind/shared-power.jpg"}],"gallery":["assets/img/elgin/whirlwind/hero.webp","assets/img/elgin/whirlwind/g01.webp","assets/img/elgin/whirlwind/g02.webp","assets/img/elgin/whirlwind/g03.webp","assets/img/elgin/whirlwind/g04.webp","assets/img/elgin/whirlwind/g05.webp","assets/img/elgin/whirlwind/g06.webp","assets/img/elgin/whirlwind/g07.webp","assets/img/elgin/whirlwind/g08.webp"],"related":["elgin-crosswind","elgin-pelican"],"features":["High-velocity vacuum pick-up for dense sand and debris","Wide sweep path with short wheelbase for tight urban navigation","Articulating side brooms with in-cab tilt control","Heavy-duty abrasion-resistant stainless steel hopper"],"downloads":[{"href":"assets/img/elgin/whirlwind/spec-sheet.pdf","label":"Whirlwind spec sheet (PDF)"},{"href":"assets/img/elgin/whirlwind/brochure.pdf","label":"Whirlwind brochure (PDF)"}],"applications":["Municipal roads and highways","Urban arterial thoroughfares","Construction site clean-up","Industrial compounds"],"specifications":[{"k":"Sweeping technology","v":"Pure vacuum — direct suction"},{"k":"Suction nozzle width","v":"813 mm (32 in)"},{"k":"Sweep path — nozzle + extension broom","v":"1,981 mm (78 in)"},{"k":"Sweep path — maximum","v":"3,658 mm (144 in)"},{"k":"Extension broom diameter","v":"406 mm (16 in)"},{"k":"Hopper volume","v":"6 m³ (8 cu yd)"},{"k":"Dump angle","v":"50°"},{"k":"Hopper floor angle","v":"10°"},{"k":"Hopper lifting","v":"Double-acting hydraulic cylinder"},{"k":"Auxiliary engine","v":"4.5 L — 74 hp (55 kW) @ 2400 rpm"},{"k":"Engine torque","v":"304 Nm (224 ft-lb) @ 1600 rpm"},{"k":"Shared Power System","v":"Patented — chassis boosts the auxiliary engine"},{"k":"Water tank capacity","v":"1,268 L (335 gal) — dual tanks"},{"k":"Spray system flow","v":"30 L/min — two pumps"},{"k":"Water pump","v":"Twin diaphragm, run-dry capability"},{"k":"Hydraulic system","v":"31 L/min per section — 87 L reservoir"},{"k":"Hydraulic filter","v":"10 micron spin-on, in-cab indicator"},{"k":"Electrical system","v":"12 V — 1000 CCA"},{"k":"Blower construction","v":"Hardox steel, 3.4 mm housing, rubber-lined"},{"k":"Chassis"}]}', '2026-09-30 22:47:02', '2026-10-06 07:03:24', NULL, 0),
(3, 'elgin-pelican', 'elgin-pelican', 2, 'environmental', 'Mechanical Sweepers', 2, 1, 'Pelican', NULL, 'Mechanical Sweeper', 'مكنسة شوارع ميكانيكية بثلاث عجلات وفرشاة دوّارة', 'The Elgin Pelican broom sweeper is a three-wheel mechanical sweeper based on one of the original street sweeper designs, which has been continuously improved since 1914, meeting the highest sweeper standards. Maneuverability, visibility, economy, serviceability, and single-lane dumping with a sweep system that easily handles heavily compacted dirt and bulky debris are\r\nFeatures:\r\n• Market leader offering 360 degrees of operator visibility.\r\n• Rear steer for outstanding maneuverability.\r\n• Front mounted, variable high dump 3.6 yd3 (2.8 m3) hopper.\r\n• Elgin exclusive chevron conveyor belt.\r\n• Access to service points is simple with most accessible from ground level.\r\n• The unit is equipped with a combination of in-cab and site gauges to monitor.', 'تتمتع شركة الجين بخبرة تتجاوز قرنًا في تصنيع معدات كنس الشوارع، وتقدم مجموعة متكاملة من المكانس، تشمل الطرازات الميكانيكية، والهواء المتجدد، والشفط، مع التزامها بتقديم أفضل مستويات الخدمة والدعم لعملائها.\r\nتُعد بلكان مكنسة ميكانيكية ثلاثية العجلات، مبنية على أحد أقدم تصميمات مكانس الشوارع، والذي شهد تطويرًا مستمرًا منذ عام 1914 ليلبي أعلى معايير الكفاءة والأداء.\r\nوتجمع Pelican بين سهولة المناورة، ووضوح الرؤية، والكفاءة التشغيلية، وسهولة الصيانة، إلى جانب نظام كنس قوي قادر على التعامل بكفاءة مع المخلفات كبيرة الحجم والمتراكمة، مع إمكانية التفريغ في مسار واحد.\r\nالمميزات :\r\nرؤية شاملة بزاوية 360° للمشغل لتعزيز الأمان وسهولة التشغيل\r\nتوجيه خلفي يوفر قدرة استثنائية على المناورة في المساحات الضيقة.\r\nحاوية أمامية متغيرة الارتفاع للتفريغ بسعة 3.6 ياردة³ (2.8 م³).\r\nسير ناقل Chevron حصري من الجين مصمم لتحقيق كفاءة عالية في جمع ونقل المخلفات.\r\nسهولة الوصول إلى معظم نقاط الصيانة.\r\nعدادات ومؤشرات داخل كابينة القيادة وخارجها لمراقبة مستويات السوائل.', 'assets/img/elgin/pelican/hero.webp', '{"meta":[{"k":"Application","v":"Street Sweeping"},{"k":"Product Type","v":"Mechanical Broom Sweeper"}],"videos":[{"ar":"الإنتاجية في أفضل صورها","en":"Productivity at its best","yt":"fMf374RZtR4","len":"1:00","src":"assets/video/elgin/pelican/productivity.mp4","poster":"assets/video/elgin/pelican/productivity.jpg"},{"ar":"قوة أداء الالتقاط","en":"Powerful pick-up performance","yt":"2QUDTHiADg4","len":"0:32","src":"assets/video/elgin/pelican/pickup-performance.mp4","poster":"assets/video/elgin/pelican/pickup-performance.jpg"},{"ar":"لوحة الوصول السريع للتنظيف","en":"Quick-Clean access panel","yt":"hHU0R5e05wI","len":"0:18","src":"assets/video/elgin/pelican/quick-clean-panel.mp4","poster":"assets/video/elgin/pelican/quick-clean-panel.jpg"},{"ar":"تكوين المنظومة","en":"System configuration","yt":"EI_oatRFw9A","len":"1:15","src":"assets/video/elgin/pelican/system-configuration.mp4","poster":"assets/video/elgin/pelican/system-configuration.jpg"}],"gallery":["assets/img/elgin/pelican/hero.webp","assets/img/elgin/pelican/g01.webp","assets/img/elgin/pelican/g02.webp","assets/img/elgin/pelican/g03.webp","assets/img/elgin/pelican/g04.webp","assets/img/elgin/pelican/g05.webp","assets/img/elgin/pelican/g06.webp","assets/img/elgin/pelican/g07.webp","assets/img/elgin/pelican/g08.webp","assets/img/elgin/pelican/g09.webp"],"related":["elgin-crosswind","elgin-whirlwind"],"features":["Unmatched turning radius for narrow residential and downtown streets","Front-mounted variable-height dump directly into standard dump trucks","Heavy-duty chevron-belt conveyor with no-jam reversible action","Full visibility panoramic cab engineered for driver safety"],"downloads":[{"href":"assets/img/elgin/pelican/spec-sheet.pdf","label":"Pelican export spec sheet (PDF)"},{"href":"assets/img/elgin/pelican/brochure.pdf","label":"Pelican brochure 2026 (PDF)"},{"href":"assets/img/elgin/pelican/industrial-brochure.pdf","label":"Pelican industrial brochure (PDF)"},{"href":"assets/img/elgin/pelican/waterless-sell-sheet.pdf","label":"Waterless Pelican sell sheet (PDF)"},{"href":"assets/img/elgin/pelican/spec-sheet-ecoinfused.pdf","label":"Eco-Infused spec sheet (PDF)"},{"href":"assets/img/elgin/pelican/quick-clean-panel.pdf","label":"Quick-Clean access panel (PDF)"}],"applications":["Historic & dense urban quarters","Residential neighbourhoods","Curb and gutter maintenance","Compacted sand and gravel collection"],"specifications":[{"k":"Sweeping technology","v":"Mechanical broom with vertical digger"},{"k":"Sweep path — one side broom","v":"2,438 mm (8 ft)"},{"k":"Sweep path — two side brooms","v":"3,048 mm (10 ft)"},{"k":"Hopper volume","v":"2.8 m³ (3.6 cu yd)"},{"k":"Maximum dump height","v":"2,896 mm (9 ft 6 in)"},{"k":"Hopper tilt time","v":"17 seconds"},{"k":"Design lift capacity","v":"4,080 kg (9,000 lb)"},{"k":"Dumping","v":"Frontal — standard"},{"k":"Engine output","v":"99 hp (74 kW) @ 2500 rpm"},{"k":"Fuel tank capacity","v":"132.5 L (35 gal)"},{"k":"Drive system","v":"Hydrostatic — single pedal forward/reverse"},{"k":"Travel speed","v":"Up to 32 km/h (20 mph)"},{"k":"Turning radius","v":"4,572 mm (15 ft) curb to curb"},{"k":"Weight — one side broom","v":"6,170 kg (13,590 lb)"},{"k":"Weight — two side brooms","v":"6,482 kg (14,290 lb)"},{"k":"Water tank capacity","v":"832 L (220 gal)"},{"k":"Hydraulic reservoir","v":"106 L (33 gal), externally readable"},{"k":"Front tyres","v":"11R22.5 14-ply"},{"k":"Cab","v":"Sealed, 100% filtered air, sound insulated, heated"},{"k":"Dust control"}]}', '2026-09-30 22:47:02', '2026-10-06 07:09:11', NULL, 0),
(4, 'vactor-2100i', 'vactor-2100i', 3, 'environmental', 'Combination Units', 3, 1, '2100i', NULL, 'Combination sewer cleaner & jetting truck', 'وحدة مشتركة لتنظيف الصرف والضخ بالمياه عالية الضغط', 'The global benchmark for combination sewer cleaners, pairing powerful positive-displacement vacuum recovery with high-pressure jetting operated via IntuiTouch controls.', 'المرجع العالمي لوحدات تنظيف الصرف المشتركة، تجمع بين شفط قوي بالإزاحة الموجبة وضخ مائي عالي الضغط، بتحكّم عبر نظام IntuiTouch.', 'assets/img/vactor/2100i/g01.webp', '{"meta":[{"k":"Application","v":"Sewer & Infrastructure"},{"k":"Product Type","v":"Combination Jet/Vac Unit"}],"videos":[{"ar":"الـ 2100i في الميدان","en":"The 2100i in the field","yt":"jfrFUDeUDJE","poster":"assets/video/vactor/2100i/overview.jpg"},{"ar":"الـ 2100i أثناء الشغل","en":"The 2100i at work","yt":"QPx_ChSYSX4","poster":"assets/video/vactor/2100i/at-work.jpg"}],"gallery":["assets/img/vactor/2100i/g01.webp","assets/img/vactor/2100i/g02.webp","assets/img/vactor/2100i/g03.webp","assets/img/vactor/2100i/g04.webp","assets/img/vactor/2100i/g05.webp","assets/img/vactor/2100i/g06.webp","assets/img/vactor/2100i/g07.webp"],"features":["Exclusive Modul-Flex design: modules configured around the job, not the other way round","IntuiTouch controls with a screen that swivels on a 90° arc, plus joystick hose-reel and boom control","Jet Rodder Multi-Flow pump: continuous flow or Jack Hammer action, run-dry protected for 30 minutes","RDB 1015 Rapid Deployment Boom telescopes 10 ft out and pays 15 ft of hose down the manhole","Water recycling recovers jetting water on site, so the tank is refilled far less often","Aluminium water tanks carrying a 10-year warranty"],"downloads":[{"href":"assets/img/vactor/2100i/brochure.pdf","label":"2100i brochure 2025 (PDF)"},{"href":"assets/img/vactor/2100i/rdb-1015.pdf","label":"RDB 1015 rapid deployment boom (PDF)"}],"applications":["Municipal sanitary sewer mains","Stormwater culverts and catch basins","Utility daylighting and slot trenching","Emergency water-main break remediation"],"specifications":[{"k":"Air mover","v":"Single or dual-stage hydrostatic fan, or Roots positive-displacement blower"},{"k":"Vacuum rating (PD)","v":"Up to 27 in (685 mm) Hg"},{"k":"Inlet volume (PD)","v":"Up to 5,000 CFM"},{"k":"Debris body capacity","v":"5 – 15 cu yd (3.8 – 11.5 m³)"},{"k":"Water tank capacity","v":"1,000 – 1,500 gal (3,785 – 5,678 L) aluminium, 10-year warranty"},{"k":"Water pump","v":"Vactor Jet Rodder Multi-Flow, 60 – 100 gpm at 2,000 – 3,000 psi"},{"k":"Hose reel","v":"15 in telescope, 270° rotation, 800 ft × 1 in (244 m) — up to 1,000 ft (305 m)"},{"k":"Boom","v":"Fully hydraulic, proportional controls, 180° rotation; RDB 1015 optional"},{"k":"Pickup hose","v":"7 in or 8 in diameter"},{"k":"Water recycling","v":"Available on the PD model"}]}', '2026-09-30 22:47:02', '2026-10-04 15:14:02', NULL, 0),
(5, 'guzzler-classic', 'guzzler-classic', 4, 'environmental', 'Industrial Vacuums', 6, 1, 'Classic', NULL, 'Heavy-duty industrial vacuum loader', 'محمّلة شفط صناعي للخدمة الشاقة', 'The proven industrial standard for extracting solids, dry bulk powders, heavy slurries, and viscous industrial sludge over extreme suction distances.', 'المعيار الصناعي المُثبَت لسحب المواد الصلبة والمساحيق الجافة والمخاليط الثقيلة والحمأة الصناعية اللزجة عبر مسافات شفط بعيدة.', 'assets/img/guzzler/classic/gz-refinery.jpg', '{"meta":[{"k":"Application","v":"Industrial Vacuum"},{"k":"Product Type","v":"Heavy-Duty Vacuum Loader"}],"videos":[{"ar":"Guzzler — المتانة التي تثق بها","en":"Guzzler — The Tough You Trust","len":"0:32","src":"assets/video/guzzler/classic/tough-you-trust.mp4","poster":"assets/img/guzzler/classic/gz-hose.jpg"},{"ar":"الـ Guzzler Classic في الميدان","en":"The Guzzler Classic in the field","yt":"x-VBxoKowYA","poster":"assets/video/guzzler/classic/in-the-field.jpg"},{"ar":"الـ Guzzler Classic أثناء الشغل","en":"The Guzzler Classic at work","yt":"v0rG7jM1JuM","poster":"assets/video/guzzler/classic/offloading.jpg"}],"gallery":["assets/img/guzzler/classic/gz-quarry-load.jpg","assets/img/guzzler/classic/gz-hose.jpg","assets/img/guzzler/classic/gz-dump.jpg","assets/img/guzzler/classic/gz-rear-plant.jpg","assets/img/guzzler/classic/gz-side.jpg","assets/img/guzzler/classic/gz-blower.jpg","assets/img/guzzler/classic/gz-refinery.jpg","assets/img/guzzler/classic/gz-white-front.jpg","assets/img/guzzler/classic/gz-white-side.jpg","assets/img/guzzler/classic/gz-white-front-2.jpg","assets/img/guzzler/classic/gz-white-rear.jpg"],"features":["Recovers solids, dry bulk powders, liquids and heavy slurries without reconfiguring the machine","Four-stage filtration: the first two stages alone remove 98% of material from the airstream","Cyclone doubles as a demister on wet work, and empties together with the main payload","All filter components fully accessible, with a single central hydraul