INSERT INTO `sections` (`id`, `page_id`, `type`, `anchor`, `position`, `published`, `content`, `created_at`, `updated_at`) VALUES
(1, 1, 'feature', 'elgin', 1, 1, '{"cta":{"href":"elgin-sweepers.html","label":{"ar":"اعرض المعدة","en":"See the equipment"}},"img":"media/img/chatgpt-image-sep-27-2026-05_15_19-am-1-efa77279.png","flip":true,"text":{"ar":"تتمتع شركة الجين بخبرة تتجاوز قرنًا في تصنيع معدات كنس الشوارع، وتقدم مجموعة متكاملة من المكانس، تشمل الطرازات الميكانيكية، والهواء المتجدد، والشفط، مع التزامها بتقديم أفضل مستويات الخدمة والدعم لعملائها.","en":"Elgin Sweepers has been manufacturing street sweepers for over a century, the company offers a wide range of sweepers, including mechanical, regenerative and vacuum models with commitment to providing the best service and support to customers."},"title":{"ar":"مكانس الطرق","en":"Road sweepers"},"brandId":"elgin"}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(2, 1, 'feature', 'vactor', 2, 1, '{"cta":{"href":"vactor-units.html","label":{"ar":"اعرض المعدة","en":"See the equipment"}},"img":"assets/img/range/env-vactor.jpg","text":{"ar":"تُعد Vactor من الشركات الرائدة في تصنيع معدات تنظيف خطوط الصرف الصحي منذ عام 1911، حيث تقدم أداءً عاليًا وموثوقًا مدعومًا بمجموعة متطورة من الخصائص التي تسهّل التشغيل وتعزز الإنتاجية. وبالإضافة إلى أنظمة الشفط عالية التدفق وتنظيف خطوط الصرف بالمياه عالية الضغط، تتيح Vactor إمكانية تخصيص المعدات لتلبية مختلف الاحتياجات التشغيلية وتحقيق أعلى مستويات الكفاءة والأداء. ","en":"Vactor is a Leading manufacturer of sewer cleaning equipment which founded in 1911, offers a proven high performance with an array of advanced features to simplify operation and productivity\\n Beyond high-flow vacuum and high-pressure water jetting, Vactor allow you to customize your machine to meet your unique needs and exceed your expectations.\\n"},"title":{"ar":"وحدات الطرق والبنية التحتية","en":"Road & infrastructure units"},"brandId":"vactor"}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(3, 1, 'feature', 'guzzler', 3, 1, '{"cta":{"href":"guzzler-vacuums.html","label":{"ar":"اعرض المعدة","en":"See the equipment"}},"img":"assets/img/range/env-guzzler.jpg","flip":true,"text":{"ar":"حلول شفط عالية الأداء للتطبيقات الصناعية والبيئية واستعادة المواد في ظروف التشغيل الصعبة.","en":"High-performance vacuum solutions for industrial, environmental and demanding material recovery applications."},"title":{"ar":"معدات الشفط الصناعي","en":"Industrial & Environmental Equipment"},"brandId":"guzzler"}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(4, 2, 'feature', 'generators', 1, 1, '{"cta":{"href":"generators.html","label":{"ar":"اعرف تفاصيل","en":"EXPLORE"}},"img":"assets/img/photos/card-generators.jpg","text":{"ar":"بدءًا من احتياجات الطاقة الأساسية وحتى أكثر التطبيقات تطلبًا وحساسية، تم تصميم حلول توليد الطاقة لتوفير القدرة والأداء واستمرارية التشغيل بما يتناسب مع متطلبات كل تطبيق. مجموعة متكاملة من المولدات الكهربائية الديزل بقدرات من 10 إلى 2,500 kVA، إلى جانب مولدات الغاز وحلول تأجير المولدات بقدرات من 20 إلى 1,000 kVA، لتلبية احتياجات مختلف القطاعات، بما في ذلك القطاعات الصناعية، الزراعية، الإنشاءات، البنية التحتية والتجارية. يتم اختيار كل نظام وفقًا لـ متطلبات الأحمال وظروف التشغيل واحتياجات الموقع. ","en":"GENERATOR SETS Designed to deliver consistent performance under high temperatures, dust, humidity, and varying site conditions, supporting prime, standby, and temporary power applications across diverse sectors. "},"title":{"ar":"المولدات الكهربائية الجديدة والايجار ","en":"POWER GENERATION"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(5, 2, 'feature', 'efficiency', 2, 1, '{"cta":{"href":"overhaul.html","label":{"ar":"اعرف تفاصيل","en":"Upgrades and overhauls"}},"img":"assets/img/photos/card-overhaul.jpg","flip":true,"text":{"ar":"توفر حلول استبدال المحركات والعمرات الشاملة كفاءة تشغيلية عالية، من خلال استعادة أداء المولدات المستهلكة وإطالة عمرها التشغيلي.","en":"Engine replacement and complete overhaul solutions deliver enhanced operating performance by restoring the efficiency of generator sets and extending their service life."},"title":{"ar":"رفع الكفاءة وأعمال العمرات","en":"Repowering and Overhauls"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(6, 2, 'cards', NULL, 3, 1, '{"cards":[{"img":"assets/img/range/canopy.jpg","href":"fabrication.html#canopies","text":{"ar":"كبائن عازلة للصوت ومقاومة للعوامل الجوية من أعمال الصاج لدينا.","en":"Sound-proof and weather canopies made in our sheet metal works."},"title":{"ar":"هياكل حماية المولدات","en":"Installation & Commissioning"}},{"img":"assets/img/range/ats-panel.jpg","href":"fabrication.html#panels","text":{"ar":"لوحات ATS والتزامن والتوزيع والتحكم.","en":"ATS, synchronization, distribution and control panels."},"title":{"ar":"تصنيع اللوحات الكهربائية","en":"Electrical Panels"}},{"img":"assets/img/range/fuel-tank.jpg","href":"fabrication.html#tanks","text":{"ar":"خزانات متنقلة وثابتة، ومعها أنظمة طلمبات الوقود.","en":"Mobile and stationary tanks, with fuel pump systems."},"title":{"ar":"خزانات الوقود والملحقات","en":"Fuel Tanks & Accessories"}},{"img":"assets/img/photos/site-installation.jpg","href":"fabrication.html#installation","text":{"ar":"أنظمة مولدات جاهزة للتشغيل، تُركَّب وتُجهَّز في موقعك.","en":"Ready-to-operate generator systems, installed and commissioned at your site."},"title":{"ar":"التركيب والتشغيل","en":"On-site installation & commissioning"}}],"title":{"ar":"التصنيع والتركيبات ","en":"Fabrication & installation"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(7, 3, 'feature', 'sales', 2, 1, '{"img":"assets/img/products/genset-open-skid.webp","text":{"ar":"المولدات الكهربائية المفتوحة، والمعروفة أيضًا بالمولدات المثبتة على قاعدة ، تتكون من المحرك والموبينة ووحدة التحكم مثبتة على قاعدة معدنية، دون وجود كابينة خارجية، مما يوفر تصميمًا عمليًا ومرونة أكبر في التركيب وفقًا لمتطلبات الموقع.","en":"Open type generators also known as skid-mounted generators, are units without any enclosure. They consist of just the engine, alternator, and control systems mounted on a frame or skid"},"title":{"ar":"المولدات الكهربائية المكشوفة (20-3000)ك.ف.أ ","en":"OPEN TYPE GENERATORS (20-3000) KVA"},"alsoId":"rental","design":{"titleSize":40}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(8, 3, 'products', NULL, 6, 0, '{"ids":["genset-canopy","genset-open-skid","genset-containerized","genset-mobile-trailer"],"note":{"ar":"كل مولد يُبنى بمكونات عالية الجودة بالكامل، بمحركات أصلية من Baudouin وPerkins وHyundai وCummins وDoosan وDevelon وVolvo.","en":"Every set is built with premium components throughout, on genuine Baudouin, Perkins, Hyundai, Cummins, Doosan, Develon and Volvo engines."},"title":{"ar":"المولدات","en":"Generators"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(9, 3, 'cta', NULL, 7, 1, '{"text":{"ar":"أرسل لنا هذه البيانات، وسيعود إليك فريقنا بالمولد المناسب وعرض السعر، للشراء أو الإيجار.","en":"Send us all three and our team will come back with the right set and a price — for purchase or rental."},"title":{"ar":"أخبرنا بالأحمال والموقع والمدة","en":"Tell us the load, the site and the duration"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(10, 5, 'compare', 'before-after', 1, 1, '{"after":"assets/img/photos/repower-after.jpg","title":{"ar":"نفس المولد، قبل وبعد","en":"The same set, before and after"},"before":"assets/img/photos/repower-before.jpg","afterLabel":{"ar":"محرك جديد","en":"New engine"},"beforeLabel":{"ar":"محرك قديم","en":"Old engine"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(11, 5, 'feature', 'repower', 2, 1, '{"img":"assets/img/photos/card-repower.jpg","text":{"ar":"تُعد عملية رفع كفاءة المولدات الكهربائية حلًا اقتصاديًا وفعّالًا مقارنةً باستبدال المولد بالكامل. وتتضمن العملية استبدال المحرك القديم بمحرك جديد، مع إعادة استخدام المكونات الرئيسية مثل وحدة التوليد (الموبينة)، ونظام التحكم، والشاسيه بعد إجراء الفحص والاختبارات اللازمة.","en":"Repowering is a cost-effective alternative to replacing an existing generator. The process replaces the old engine with a new engine, while retaining the alternator, control system, and chassis following thorough inspection and testing."},"when":{"ar":"عندما يكون المحرك وحده هو المشكلة، وتكون بقية مكونات المولد صالحة لإعادة الاستخدام بعد اختبارها.","en":"When the engine itself is the problem and the rest of the set is still sound enough to be reused after testing."},"title":{"ar":"رفع كفاءة المولدات","en":"Repowering"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(12, 5, 'feature', 'overhaul', 3, 1, '{"img":"assets/img/photos/card-overhaul.jpg","flip":true,"text":{"ar":"تُنفذ أعمال العمرات المتخصصة وفقًا لتوصيات الشركة المُصنّعة وعدد ساعات التشغيل، مع توفير حلول مخصصة تهدف إلى استعادة المعدات إلى أفضل مستويات الأداء وإطالة العمر الافتراضي. تُنفذ جميع الأعمال داخل مركز الخدمة على يد فريق متخصص من المهندسين والفنيين، بما يضمن الجودة والدقة وكفاءة أداء المحرك.\\nأنواع عمليات العمرة:\\n– عمرة الصيانة.\\n– عمرة جزئية.\\n– عمرة شاملة (رئيسية).","en":"Customized overhaul services are performed in accordance with manufacturer recommendations and operating-hour intervals, with tailored solutions designed to restore equipment to optimal performance and extend lifespan. All work is carried out at the service center by a qualified team of engineers and technicians, ensuring quality, precision, and optimal engine performance.\\nTypes of overhaul:\\n– Maintenance overhaul.\\n– Partial overhaul.\\n– Major overhaul."},"title":{"ar":"أعمال العمرات الشاملة","en":"Overhauls"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(13, 5, 'cta', NULL, 4, 1, '{"text":{"ar":"أرسل لنا نوع المحرك والقدرة، وسنحدّد لك الأنسب: رفع الكفاءة أم العمرة الشاملة.","en":"Send us the engine model and its rating, and we will tell you whether an upgrade or an overhaul is the right choice."},"title":{"ar":"اطلب معاينة لمولدك","en":"Ask for an inspection of your generator"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(14, 6, 'feature', 'canopies', 1, 1, '{"img":"assets/img/range/canopy.jpg","text":{"ar":"تتوفر هياكل الحماية بمجموعة متنوعة من الخيارات المصممة لتلبية متطلبات التشغيل واحتياجات الموقع، بدءًا من التصميمات المقاومة للعوامل الجوية التي توفر حماية فعّالة للمولد من الأمطار وأشعة الشمس والرياح، وصولًا إلى الحلول العازلة للصوت وفائقة العزل التي تضمن تشغيلًا أكثر هدوءً في التطبيقات الحساسة والأماكن الحيوية، إلى جانب الحاويات المعدلة ISO للمولدات ذات القدرات الكبيرة، والتي توفر حماية متكاملة ومتانة عالية ومرونة تشغيلية للتطبيقات الصناعية والمشروعات التي تتطلب حلولًا متخصصة.","en":"Generator enclosures are available in a wide range of options designed to meet operating requirements and site conditions, from weatherproof designs that provide effective protection against rain, sunlight, and wind, to silent and super-silent solutions that ensure quieter operation in noise-sensitive applications and critical environments. Modified ISO containers are also available for high-capacity generators, providing comprehensive protection, high durability, and operational flexibility for industrial applications and projects requiring specialized solutions"},"title":{"ar":"هياكل حماية المولدات","en":"Generator Enclosures"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(15, 6, 'feature', 'panels', 2, 1, '{"img":"assets/img/range/ats-panel.jpg","flip":true,"text":{"ar":"يتم تصميم وتصنيع وتجميع مجموعة متكاملة من لوحات التوزيع والتحكم ولوحات التحويل الأوتوماتيكي (ATS)، إلى جانب لوحات المزامنة وتصحيح تتابع الفازات واللوحات السكنية والإنشائية ولوحات أنظمة التكييف والتهوية (HVAC). ويعمل فريق متخصص في التصميم الكهربائي على تطوير وتنفيذ كل نظام وفقًا لمتطلبات العميل وطبيعة التطبيق، باستخدام مكونات عالية الجودة من علامات تجارية عالمية مثل Schneider Electric وABB وDSE.","en":"A wide range of distribution and control panels and Automatic Transfer Switch (ATS) panels is designed, manufactured, and assembled, along with synchronization panels, phase sequence correction panels, residential and construction panels, and HVAC panels. A specialized electrical design team develops and implements each system according to client requirements and application needs, using high-quality components from leading global brands such as Schneider Electric, ABB, and DSE."},"title":{"ar":"تصنيع اللوحات الكهربائية","en":"Electrical Panels"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(16, 6, 'feature', 'tanks', 3, 1, '{"img":"assets/img/range/fuel-tank.jpg","text":{"ar":"تتوفر خزانات الوقود الثابتة والمتحركة، ويتم تصنيعها باستخدام مواد وسماكات مختلفة بما يتناسب مع السعة ومتطلبات التشغيل وظروف الموقع. كما يمكن تجهيزها بمجموعة من ملحقات وأنظمة إدارة الوقود، مثل مضخات نقل ورفع الوقود، وذراع التحضير، ومؤشرات مستوى الوقود، وفتحات التعبئة والتهوية والصمامات، لتوفير حلول متكاملة لمختلف تطبيقات توليد الطاقة.","en":"Fuel tanks are available in stationary and mobile configurations, manufactured using different materials and thicknesses to suit capacity, operating requirements, and site conditions. They can be equipped with a range of fuel management accessories, including fuel transfer pumps, priming handles, fuel level indicators, filling and vent connections, and valves, providing a complete solution for various power generation applications."},"title":{"ar":"خزانات الوقود والملحقات","en":"Fuel Tanks & Accessories"},"design":{"bg":"#FFFFFF","titleSize":39}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(17, 6, 'feature', 'installation', 4, 1, '{"img":"assets/img/photos/site-installation.jpg","flip":true,"text":{"ar":"يتم تنفيذ تركيب وتجهيز أنظمة المولدات وفقًا لمتطلبات كل موقع، بدءًا من التأكد من جاهزية الموقع والأساسات وقاعدة المولد، وصولًا إلى تنفيذ التركيبات الميكانيكية والكهربائية للمولد والأنظمة المساعدة، بما يشمل أنظمة الوقود والعادم والتهوية، وتمديد الكابلات وإنهائها وتوصيلها باللوحات الكهربائية.","en":"Generator systems are installed and prepared according to the requirements of each site, starting with foundation and base-frame, followed by mechanical and electrical installation of the generator and auxiliary systems, including fuel, exhaust, and ventilation systems, cable routing and termination, and panel connections."},"title":{"ar":"التركيب والتشغيل","en":"Installation & Commissioning"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(18, 6, 'gallery', NULL, 5, 1, '{"imgs":["assets/img/photos/fuel-tank-fab.jpg","assets/img/photos/cable-routing.jpg","assets/img/photos/exhaust-system.jpg","assets/img/photos/ventilation.jpg","assets/img/photos/fuel-system.jpg","assets/img/photos/card-service.jpg","assets/img/photos/genset-container.jpg","assets/img/photos/genset-workshop.jpg","assets/img/photos/card-sector-agri.jpg"],"title":{"ar":"من أعمالنا","en":"From our work"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(19, 6, 'cta', NULL, 6, 1, '{"text":{"ar":"كابينة أو لوحة أو تانك أو تركيب كامل في الموقع — قول لنا محتاج إيه، وفريقنا هيرجعلك بنطاق العمل وعرض السعر.","en":"Canopy, panel, tank or a full site installation — tell us what you need and our team will come back with a scope and a price."},"title":{"ar":"ابعتلنا الرسم، أو المشكلة","en":"Send us the drawing, or the problem"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(20, 7, 'story', 'team', 2, 1, '{"img":"assets/img/photos/field-service.jpg","text":{"ar":"يقدم فريق الخدمة المؤهل والمعتمد، بدعم من مهندسين وفنيين ذوي خبرة، خدمات الصيانة والدعم الفني من خلال مركز الخدمة وفرق العمل الميدانية، مع تغطية شاملة لجميع أنحاء الجمهورية. وتشمل الخدمات الصيانة الوقائية، وتشخيص الأعطال، والاستجابة للأعطال الطارئة، بما يساهم في الحفاظ على أداء المعدات وتقليل فترات التوقف. كما تتوفر عقود الصيانة، وتشمل برامج صيانة مجدولة، وقطع غيار أصلية، ودعمًا فنيًا مستمرًا، واستجابة ميدانية سريعة وفقًا لمتطلبات المعدات.","en":"Our qualified and certified service team, supported by experienced engineers and technicians, provides maintenance and technical support through our service center and on-site field teams, with comprehensive coverage across Egypt. Services include preventive maintenance, troubleshooting, and emergency breakdown response, helping maintain equipment performance and minimize downtime.\\nMaintenance contracts are also available, including scheduled maintenance, genuine spare parts, continuous technical support, and responsive field service tailored to equipment requirements."},"title":{"ar":"الخدمات الميدانية والصيانة","en":"Field Service & Maintenance"},"design":{"imgShare":60},"eyebrowStyle":"none"}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(21, 7, 'story', 'parts', 1, 1, '{"img":"assets/img/photos/filters-develon.jpg","flip":true,"text":{"ar":"بصفتنا الوكيل المعتمد لمعدات Elgin وVactor وGuzzler، تحرص الشركة على توفير مخزون مخصص من قطع الغيار الأصلية والمستهلكات، بما يضمن سرعة توافر القطع اللازمة للحفاظ على أداء المعدات، وتقليل فترات التوقف، واستمرارية التشغيل. كما توفر الشركة قطع الغيار الأصلية لمولدات Doosan وCummins وPerkins، إلى جانب الفلاتر الأصلية التي تساهم في إطالة العمر التشغيلي للمعدات. وبالنسبة إلى حفارات DEVELON، تتوفر قطع غيار المحركات والمكونات الهيدروليكية لتلبية مختلف احتياجات الصيانة والإصلاح..","en":"As the authorized dealer for Elgin, Vactor, and Guzzler, a dedicated stock of genuine spare parts and consumables is always available, ensuring customers have timely access to the parts required to maintain equipment performance, minimize downtime, and ensure operational continuity. We also provide genuine spare parts for Doosan, Cummins, and Perkins generator sets, along with genuine filters to extend equipment operating life. For DEVELON excavators, engine spare parts and hydraulic components are available to support a wide range of maintenance and repair requirements."},"title":{"ar":"قطع الغيار الأصلية والفلاتر","en":"Genuine spare parts & filters"},"design":{"imgShare":53,"textSize":17},"eyebrowStyle":"none"}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(22, 7, 'story', 'maintenance', 4, 0, '{"cta":{"href":"maintenance.html","label":{"ar":"اعرف المزيد","en":"Learn more"}},"img":"assets/img/photos/site-installation.jpg","text":{"ar":"فريق الخدمة الميدانية يحافظ على معداتك تعمل في مكانها: صيانة دورية ووقائية وتصحيحية في موقعك، وتشخيص الأعطال في الموقع، واستجابة سريعة للأعطال الطارئة. ومن خلال عقد الصيانة يتم كل ذلك وفق جدول محدد، بقطع غيار أصلية ودعم فني مستمر.","en":"Our field service team keeps your equipment running where it works: periodic, preventive and corrective maintenance at your site, on-site troubleshooting and emergency breakdown response. Under a maintenance contract, all of it runs on a set schedule, with genuine parts and continuous technical support."},"title":{"ar":"صيانة المواقع وعقود الصيانة","en":"Site maintenance & maintenance contracts"},"design":{"imgShare":65},"eyebrowStyle":"none"}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(23, 7, 'story', 'warranty', 3, 1, '{"img":"assets/img/range/genset-canopy.webp","flip":true,"text":{"ar":"جميع المنتجات والخدمات التي تقدمها الشركة يطبق عليها الضمان وفقًا للشروط، بما يغطي عيوب التصنيع، إلى جانب توفير الدعم الفني السريع، وقطع الغيار الأصلية، وخدمات ما بعد البيع الاحترافية. ويحرص فريقنا على التعامل مع متطلبات الضمان بكفاءة وتوفير الدعم اللازم طوال فترة الضمان، بما يساهم في الحفاظ على أداء المعدات واستمرارية التشغيل.","en":"Every product and service is backed by applicable warranty coverage against manufacturing defects, supported by prompt technical assistance, genuine spare parts availability, and professional after-sales service. Our team is committed to handling warranty requirements efficiently and providing the necessary support throughout the warranty period, helping customers maintain equipment performance and operational continuity."},"title":{"ar":"الضمان","en":"Warranty"},"eyebrowStyle":"none"}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(24, 8, 'story', 'field-service', 1, 1, '{"img":"assets/img/photos/field-service.jpg","tag":{"ar":"زيارة خدمة ميدانية","en":"Service field visit"},"text":{"ar":"بخبرة عالية، يشرف فريق الخدمة الميدانية لدينا على تركيب الوحدات وتشغيلها، ويقدّم تشخيص الأعطال والدعم الفني في الموقع، ويستجيب للأعطال الطارئة، ويقدّم خدمات الصيانة الدورية والوقائية والتصحيحية.","en":"Our experienced field service team supervises the installation and commissioning of the units, provides on-site troubleshooting and technical support, responds to emergency breakdowns, and carries out periodic, preventive and corrective maintenance."},"title":{"ar":"الخدمات الميدانية","en":"Field services"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(25, 8, 'story', 'contracts', 2, 1, '{"img":"assets/img/photos/card-overhaul.jpg","tag":{"ar":"عقد صيانة","en":"Maintenance contract"},"flip":true,"text":{"ar":"عقد الصيانة يضع معداتك على خطة واضحة: نحن نجدول الأعمال، ونورّد القطع، ونبقى جاهزين عند الطلب — لتكون المعدة جاهزة وقتما تحتاجها.","en":"A maintenance contract puts your equipment on a plan: we schedule the work, supply the parts and stay on call — so the set is ready whenever you need it."},"title":{"ar":"الصيانة","en":"Maintenance"},"points":[{"ar":"زيارات صيانة دورية مجدولة","en":"Scheduled periodic maintenance visits"},{"ar":"صيانة وقائية تكتشف الأعطال قبل أن توقف المعدة","en":"Preventive maintenance that catches faults before they stop the set"},{"ar":"صيانة تصحيحية واستجابة سريعة للأعطال الطارئة","en":"Corrective maintenance and emergency breakdown response"},{"ar":"تشخيص الأعطال والدعم الفني في الموقع","en":"On-site troubleshooting and technical support"},{"ar":"قطع غيار وفلاتر أصلية من مخزوننا","en":"Genuine spare parts and filters, supplied from our stock"},{"ar":"دعم مستمر طوال العمر التشغيلي للمعدة","en":"Continuous support throughout the equipment lifecycle"}],"pointsTitle":{"ar":"ما يشمله عقد الصيانة","en":"What a maintenance contract covers"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(26, 9, 'story', 'agri', 1, 1, '{"img":"media/img/g04-cab569d8.webp","text":{"ar":"دعماً للمشروعات القومية والمساهمة في نمو القطاع الزراعي في مصر، تم توريد وتركيب وتشغيل مجموعة من المولدات الكهربائية بقدرات 200، 250، 300، 350، 500 و1,000 kVA في مواقع متعددة بمختلف أنحاء الجمهورية، لخدمة مشروعات استصلاح الأراضي الصحراوية والتنمية الزراعية.","en":"Supporting national projects and the growth of Egypt’s agricultural sector, a range of 200, 250, 300, 350, 500, and 1,000 kVA generator sets have been supplied, installed, and commissioned across multiple locations throughout Egypt, supporting desert land reclamation and agricultural development projects."},"title":{"ar":"قطاع التنمية الزراعية","en":"Agricultural development"},"design":{"imgZoom":125},"eyebrow":{"ar":"مشروعاتنا","en":"Our projects"},"eyebrowStyle":"none"}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(27, 9, 'story', 'oil', 2, 1, '{"img":"media/img/hero-service-01-e3494aee.jpg","flip":true,"text":{"ar":"تم توريد وتشغيل العديد من المولدات الكهربائية المؤجرة بمختلف القدرات في مواقع متعددة، لدعم احتياجات الطاقة واستمرارية التشغيل في قطاعات البترول، والزراعة، والمحاجر، ومواقع الإنشاءات، وفقًا لمتطلبات الأحمال وظروف وطبيعة كل موقع.","en":"Multiple rental generators sets in various capacities have been supplied and commissioned across multiple sites, supporting power requirements and operational continuity across the oil & gas, agricultural, quarrying, and construction sectors, based on the load requirements and specific conditions of each site."},"title":{"ar":"قطاع البترول","en":"Oil & gas"},"eyebrow":{"ar":"مشروعاتنا","en":"Our projects"},"eyebrowStyle":"none"}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(28, 9, 'story', 'industry', 3, 1, '{"img":"assets/img/photos/card-sector-industry.jpg","text":{"ar":"تنفيذ أعمال الحفر ومد كابلات أرضية بجهد 22 ك.ف من نوع XLPE بمقطع 3×400 مم² بطول 5 كم وعلى عمق 1 متر، لربط محطة محولات غرب الشروق بنطاق مشروع المنطقة اللوجستية بطريق السويس. وشملت الأعمال الحفر الميكانيكي واليدوي، وتجهيز مسار الكابلات بطبقات الرمل والطوب، ومد الكابلات ووضع الأشرطة التحذيرية، وفقًا لمتطلبات المشروع.","en":"Execution of excavation and installation works for 5 km of 22 kV XLPE underground cables (3×400 mm²), laid at a depth of 1 meter, connecting West El Shorouk Substation to the Logistics Zone Project along Suez Road. The scope included mechanical and manual excavation, soil preparation with sand and brick layers, cable installation, and warning tape placement, in accordance with project requirements."},"title":{"ar":"قطاع الصناعة","en":"Industry"},"eyebrow":{"ar":"مشروعاتنا","en":"Our projects"},"eyebrowStyle":"none"}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(29, 9, 'story', 'rental', 4, 1, '{"img":"assets/img/range/genset-rental.jpg","flip":true,"text":{"ar":"تركيب المولدات الكهربائية ولوحات المزامنة ولوحات التحويل الأوتوماتيكي (ATS) في مجموعة متنوعة من المنشآت، بما في ذلك المستشفيات والمصانع والمجمعات التجارية والمؤسسات، إلى جانب تنفيذ متطلبات السلامة والعزل الصوتي وأنظمة إمداد الوقود وفقًا لاحتياجات التشغيل. وتدعم هذه الحلول استمرارية التشغيل والإنتاجية، مع توفير الحماية من الضوضاء والعوامل الجوية لتعزيز الراحة وحماية المعدات.","en":"Generator sets, synchronization panels, and Automatic Transfer Switch (ATS) panels have been installed across a wide range of facilities, including hospitals, factories, commercial complexes, and institutions, along with safety requirements, acoustic insulation, and fuel supply systems tailored to operational needs. These solutions support continuous operation and productivity, while providing noise and weather protection for enhanced comfort and equipment protection."},"title":{"ar":"إيجار المولدات في مختلف القطاعات","en":"Generator rental across sectors"},"eyebrow":{"ar":"مشروعاتنا","en":"Our projects"},"eyebrowStyle":"none"}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(30, 10, 'story', 'company', 1, 1, '{"img":"media/img/chatgpt-image-oct-6-2026-02_33_52-pm-94eda929-70f50b8f.webp","facts":[{"k":{"ar":"اسم الشركة","en":"Company Name"},"v":{"ar":"5A&M للاستيراد والتصدير والمقاولات.","en":"5A&M for Import, Export and Contracting."}},{"k":{"ar":"تأسست","en":"Established"},"v":{"ar":"2022","en":"2022"}},{"k":{"ar":"النشاط","en":"Business Activity"},"v":{"ar":"نشاط 3S للمولدات والمعدات الثقيلة.","en":"3S — sales, spare parts and service — for generators and heavy equipment."}}],"title":{"ar":"وصف الشركة","en":"Company Description"},"design":{"imgZoom":115},"eyebrow":{"ar":"من نحن","en":"About us"},"eyebrowStyle":"none"}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
(31, 10, 'vmv', 'vmv', 2, 1, '{"cards":[{"d":{"ar":"أن نكون شريكًا رائدًا في مجال معدات البيئة وحلول الطاقة، مدفوعين بالنمو المستمر، والشراكات القائمة على الثقة، وصناعة قيمة مستدامة. ","en":"To be a leading partner in Environmental Equipment and Power Solutions, driven by continuous growth, trusted partnerships, and sustainable value creation. "},"t":{"ar":"رؤيتنا ","en":"Vision"},"icon":"eye"},{"d":{"ar":"تقديم حلولًا متكاملة في مجال معدات البيئة وحلول الطاقة، تجمع بين جودة المنتجات والخبرة الفنية والخدمات الاحترافية لتلبية احتياجات العملاء وتحقيق قيمة مستدامة. ","en":"TO deliver integrated Environmental Equipment and Power Solutions, combining quality products, technical expertise, and professional services to meet customer needs and deliver lasting value. "},"t":{"ar":"هدفنا ","en":"Mission"},"icon":"target"},{"d":{"ar":"من خلال التزامنا بالجودة والاعتمادية والشفافية والتحسين المستمر، وتقديم ضمان قوي وخدمات احترافية، نبني علاقات طويلة الأمد مع عملائنا وشركائنا من خلال تقديم حلول فعّالة. ","en":"With our commitment to quality, reliability, transparency, and continuous improvement, supported by strong warranty coverage and professional service, we build lasting relationships with our customers and partners through effective solutions. "},"t":{"ar":"القيم ","en":"Values"},"icon":"gem"}],"title":{"ar":"رؤية ورسالة وقيم 5A&M","en":"5A&M Vision, Mission and Values"}}', '2026-10-01 02:31:16', '2026-10-20 03:41:34'),
(32, 11, 'cards', NULL, 1, 1, '{"cards":[{"img":"assets/img/range/parts-engine.jpg","text":{"ar":"تورّد 5A&M قطع الغيار الأصلية لمولدات الديزل Hyundai Infracore، ومجموعة واسعة من قطع الغيار لماركات مثل Perkins وCummins وVolvo — للمحركات والمولدات الكهربائية ووحدات التحكم، وأنظمة المولد الميكانيكية والكهربائية والتبريد والوقود والتحكم.","en":"5A&M supplies genuine Hyundai Infracore diesel generator parts, and a wide range of parts for brands such as Perkins, Cummins and Volvo — for engines, alternators and controllers, and the generator’s mechanical, electrical, cooling, fuel and control systems."},"title":{"ar":"قطع غيار المولدات","en":"Generator parts"}},{"img":"assets/img/range/parts-heavy-equipment.jpg","text":{"ar":"قطع غيار أصلية لحفارات Hyundai Infracore، وقطع غيار لصيانة الحفارات والمعدات الثقيلة الأخرى من Develon وغيرها.","en":"Genuine Hyundai Infracore excavator parts, and parts supporting the maintenance of excavators and other heavy equipment from Develon and other makes."},"title":{"ar":"قطع غيار المعدات الثقيلة","en":"Heavy equipment parts"}},{"img":"assets/img/range/env-elgin.jpg","text":{"ar":"دعم قطع الغيار والصيانة لمعدات Elgin وVactor وGuzzler، بصفتنا الوكيل الحصري المعتمد في مصر.","en":"Parts and maintenance support for the Elgin, Vactor and Guzzler units, as the exclusive authorized dealer in Egypt."},"title":{"ar":"قطع غيار الوحدات البيئية","en":"Environmental unit parts"}},{"img":"assets/img/range/parts-filters.jpg","text":{"ar":"فلاتر Develon وFleetguard الأصلية لضمان تشغيل آمن وعمر أطول للمولد، إلى جانب أطقم الصيانة وقطع الكهرباء والتبريد والوقود والميكانيكا — أصلية وبديلة.","en":"Genuine Develon and Fleetguard filters for safe operation and a longer generator life, plus maintenance kits and electrical, cooling, fuel and mechanical parts — genuine and replacement."},"title":{"ar":"الفلاتر وقطع الغيار العامة","en":"Filters & general spare parts"}}],"title":{"ar":"ماذا نورّد","en":"What we supply"}}', '2026-09-30 22:47:02', '2026-10-20 03:41:34'),
