('brandRoles', '{"abb":{"bio":{"ar":"مكونات كهربائية تُستخدم في اللوحات التي تصمّمها وتجمّعها 5A&M.","en":"Electrical components used in the panels 5A&M designs and assembles."},"role":{"ar":"مكونات اللوحات","en":"Panel components"}},"dse":{"bio":{"ar":"Deep Sea Electronics — وحدات التحكم والحماية المستخدمة في مولدات ولوحات 5A&M.","en":"Deep Sea Electronics — the control and protection modules used on 5A&M sets and panels."},"role":{"ar":"وحدات التحكم","en":"Controllers"}},"comap":{"bio":{"ar":"مصنّع وحدات تحكم تُستخدم في مولدات 5A&M ولوحات التزامن.","en":"Controller manufacturer used on 5A&M generator sets and synchronization panels."},"role":{"ar":"وحدات التحكم","en":"Controllers"}},"elgin":{"bio":{"ar":"ضمن مجموعة Federal Signal Environmental Solutions؛ و5A&M هي وكيلها الحصري المعتمد في مصر.","en":"Part of Federal Signal Environmental Solutions Group; 5A&M is its exclusive authorized dealer in Egypt."},"role":{"ar":"كنس الشوارع","en":"Street sweeping"}},"volvo":{"bio":{"ar":"مصنّع محركات ديزل؛ أحد المحركات التي تُبنى بها مولدات 5A&M.","en":"Diesel engine manufacturer; one of the engines 5A&M generator sets are built with."},"role":{"ar":"محركات الديزل","en":"Diesel engines"}},"doosan":{"bio":{"ar":"مصنّع محركات ديزل؛ الخط الذي بدأت 5A&M بتوريد قطع غياره.","en":"Diesel engine manufacturer; the line 5A&M started out supplying parts for."},"role":{"ar":"محركات الديزل","en":"Diesel engines"}},"fiveam":{"bio":{"ar":"5A&M تبني المنظومة: الكابينة والخزان واللوحة والتركيب في الموقع.","en":"5A&M builds the set: canopy, tank, panel and the installation on site."},"role":{"ar":"التجميع والتصنيع والتركيب","en":"Assembly, fabrication & installation"}},"vactor":{"bio":{"ar":"ضمن مجموعة Federal Signal Environmental Solutions؛ و5A&M هي وكيلها الحصري المعتمد في مصر.","en":"Part of Federal Signal Environmental Solutions Group; 5A&M is its exclusive authorized dealer in Egypt."},"role":{"ar":"تنظيف الصرف والبنية التحتية","en":"Sewer & infrastructure cleaning"}},"cummins":{"bio":{"ar":"مصنّع محركات ديزل؛ أحد المحركات التي تُبنى بها مولدات 5A&M.","en":"Diesel engine manufacturer; one of the engines 5A&M generator sets are built with."},"role":{"ar":"محركات الديزل","en":"Diesel engines"}},"develon":{"bio":{"ar":"معدات ثقيلة ومحركات؛ وتورّد 5A&M قطع غيارها وفلاترها الأصلية.","en":"Heavy equipment and engines; 5A&M supplies its genuine parts and filters."},"role":{"ar":"محركات ومعدات ثقيلة","en":"Engines & heavy equipment"}},"guzzler":{"bio":{"ar":"ضمن مجموعة Federal Signal Environmental Solutions؛ و5A&M هي وكيلها الحصري المعتمد في مصر.","en":"Part of Federal Signal Environmental Solutions Group; 5A&M is its exclusive authorized dealer in Egypt."},"role":{"ar":"الشفط الصناعي","en":"Industrial vacuum"}},"hyundai":{"bio":{"ar":"Hyundai Infracore — محركات وقطع غيار أصلية للحفارات تورّدها 5A&M.","en":"Hyundai Infracore — engines and genuine excavator parts supplied by 5A&M."},"role":{"ar":"محركات وقطع غيار الحفارات","en":"Engines & excavator parts"}},"perkins":{"bio":{"ar":"مصنّع محركات ديزل؛ أحد المحركات التي تُبنى بها مولدات 5A&M.","en":"Diesel engine manufacturer; one of the engines 5A&M generator sets are built with."},"role":{"ar":"محركات الديزل","en":"Diesel engines"}},"baudouin":{"bio":{"ar":"مصنّع محركات ديزل ضمن مكونات مولدات 5A&M.","en":"Diesel engine manufacturer listed among 5A&M\'s generator components."},"role":{"ar":"محركات الديزل","en":"Diesel engines"}},"stamford":{"bio":{"ar":"مصنّع مولدات كهربائية؛ وتُبنى مولدات 5A&M بمولدات Stamford.","en":"Alternator manufacturer; 5A&M sets are built with Stamford alternators."},"role":{"ar":"المولدات الكهربائية","en":"Alternators"}},"schneider":{"bio":{"ar":"مكونات كهربائية تُستخدم في اللوحات التي تصمّمها وتجمّعها 5A&M.","en":"Electrical components used in the panels 5A&M designs and assembles."},"role":{"ar":"مكونات اللوحات","en":"Panel components"}},"fleetguard":{"bio":{"ar":"ماركة فلاتر تورّدها 5A&M لحماية المحرك وإطالة عمره.","en":"Filter brand supplied by 5A&M to protect the engine and extend its life."},"role":{"ar":"الفلاتر","en":"Filtration"}},"leroysomer":{"bio":{"ar":"مصنّع مولدات كهربائية؛ وتُبنى مولدات 5A&M بمولدات Leroy-Somer.","en":"Alternator manufacturer; 5A&M sets are built with Leroy-Somer alternators."},"role":{"ar":"المولدات الكهربائية","en":"Alternators"}}}', 'content', NULL, 'أدوار الشركات في المنتج (غير معروضة)', '2026-09-30 22:47:13'),
('categories', '[{"id":"environmental","name":"Environmental Equipment","blurb":"Street sweeping, sewer and infrastructure cleaning, and industrial vacuum applications.","image":"assets/img/photos/environmental-triptych.jpg"},{"id":"power","name":"Power Generation","blurb":"Diesel generator sets from 10 to 2500 kVA for prime and standby duty, plus rental power.","image":"assets/img/photos/genset-5am-canopy.jpg"},{"id":"engineering","name":"Engineering & Installation","blurb":"Sheet metal works, fabrication, mechanical and electrical installation and commissioning.","image":"assets/img/photos/canopy-fabrication.jpg"},{"id":"repowering","name":"Repowering","blurb":"Replace the old engine, reuse the proven components, extend the life of the set.","image":"assets/img/photos/repower-after.jpg"},{"id":"parts","name":"Spare Parts","blurb":"Genuine engine, alternator, controller, filtration and maintenance parts.","image":"assets/img/photos/filters-range.jpg"},{"id":"service","name":"Service & After-Sales","blurb":"Installation, commissioning, maintenance, field service and warranty support.","image":"assets/img/photos/field-service.jpg"}]', 'content', NULL, 'التصنيفات', '2026-09-30 22:47:03'),
('chat', '{"model":"nvidia/nemotron-3-ultra-550b-a55b:free","ownUrl":"","enabled":true,"greeting":{"ar":"أهلًا بك في 5A&M 👋 اسألني عن المولدات أو المعدات البيئية أو قطع الغيار، أو اطلب التحدث مع موظف.","en":"Welcome to 5A&M 👋 Ask me about generators, environmental equipment or spare parts — or ask to talk to our team."},"ownModel":"","provider":"qwen","backupModel":"minimax/minimax-m3.1-flash:free","requireLogin":true,"deepseekModel":"deepseek-v4-pro"}', 'chat', 'Chat', 'المحادثة', '2026-10-26 10:21:43'),
('company', '{"hq":{"ar":"المستثمرين الجنوبية، التجمع الخامس، القاهرة الجديدة، مصر","en":"South Investors Area (El Mostasmereen El Ganobya), 5th Settlement, New Cairo, Egypt"},"geo":"30.005014419555664,31.472177505493164","email":"info@5a-eg.com","intro":"5A&M for Import, Export and Contracting is an Egyptian company established in 2022, specialised in power generation and industrial equipment. We provide high-quality products, reliable technical solutions and ongoing support across various sectors.","phone":"011 1397 4600","short":"5A&M","social":{"youtube":"#","facebook":"#","linkedin":"#"},"values":[{"k":"Quality","v":"Highest international standards"},{"k":"Reliability","v":"Durable and dependable"},{"k":"Innovation","v":"New technologies"},{"k":"Efficiency","v":"Creative, better-performing solutions"}],"vision":"To become a leading company in the Egyptian market for power generation and industrial equipment, through a portfolio of top agencies, by delivering high-quality products and reliable technical solutions to our clients across various sectors.","address":"83 El Mostasmereen, El Ganobya, 5th Settlement, New Cairo, Cairo, Egypt.","mission":"To \\"walk the talk\\". Our services must be efficient and effective to gain customer satisfaction by providing the best solutions.","tagline":"Powering a better tomorrow","activity":"3S activity for Generators and Heavy Equipment","legalName":"5A&M for Import, Export and Contracting","phoneIntl":"+201113974600","dealership":"Exclusive Authorized Dealer in Egypt for Federal Signal Environmental Solutions Group.","established":2022,"serviceCenter":{"ar":"المنطقة الصناعية، ترعة الإسماعيلية، مسطرد، القاهرة","en":"Industrial Zone, Ismailia Canal, Mostorod, Cairo","map":"Mostorod, Qalyubia, Egypt"},"valuesStatement":"We deliver products and services that meet the highest international standards, ensuring durability and reliability, meeting the new technologies and creative solutions to enhance efficiency."}', 'company', NULL, 'بيانات الشركة', '2026-09-30 22:47:02'),
('contact', '{"hq":{"ar":"المستثمرين الجنوبية، التجمع الخامس، القاهرة الجديدة، مصر","en":"South Investors Area (El Mostasmereen El Ganobya), 5th Settlement, New Cairo, Egypt"},"geo":"30.005014419555664,31.472177505493164","email":"info@5a-eg.com","phone":"011 1397 4600","address":"83 El Mostasmereen, El Ganobya, 5th Settlement, New Cairo, Cairo, Egypt.","phoneIntl":"+201113974600","serviceCenter":{"ar":"المنطقة الصناعية، ترعة الإسماعيلية، مسطرد، القاهرة","en":"Industrial Zone, Ismailia Canal, Mostorod, Cairo","map":"Mostorod, Qalyubia, Egypt"}}', 'contact', NULL, 'بيانات التواصل', '2026-09-30 22:47:02'),
('engineering', '[{"name":"Canopies","note":"Sound proof and weather enclosures fabricated in-house.","image":"assets/img/photos/canopy-fabrication.jpg"},{"name":"Fuel Tanks","note":"Mobile and stationary tanks sized to run time.","image":"assets/img/photos/fuel-tank-fab.jpg"},{"name":"Exhaust Systems","note":"Exhaust, mufflers and air pipes.","image":"assets/img/photos/exhaust-system.jpg"},{"name":"Genset Trailers","note":"Trailers for mobile and rental sets.","image":"assets/img/photos/genset-trailer.jpg"},{"name":"Control Panels","note":"Designed and assembled by our electrical team.","image":"assets/img/products/control-panel.jpg"},{"name":"Fuel Systems","note":"Transfer, pumping and day tank connection.","image":"assets/img/photos/fuel-system.jpg"},{"name":"Ventilation","note":"Air routing for generator rooms.","image":"assets/img/photos/ventilation.jpg"},{"name":"Installation","note":"Mechanical and electrical installation on site.","image":"assets/img/photos/site-installation.jpg"}]', 'content', NULL, 'الأعمال الهندسية', '2026-09-30 22:47:03'),
('equipmentEmpty', '{"text":{"ar":"جرّب كلمة أوسع، أو قول لنا التطبيق وإحنا نحدد المواصفة.","en":"Try a broader term, or tell us the application and we will specify it for you."},"title":{"ar":"مفيش موديل مطابق","en":"No model matches that"}}', 'content', NULL, 'نص «لا نتيجة» في كتالوج المعدات', '2026-09-30 22:47:13'),
('federal', '[{"d":"Street sweepers for municipal and contractor fleets — mechanical broom, regenerative air and pure vacuum.","alt":"An Elgin regenerative-air street sweeper","brand":"elgin","image":"assets/img/range/env-elgin.jpg","lines":["Mechanical Sweepers","Regenerative Air","Vacuum Sweepers"]},{"d":"Combination sewer cleaners, jetters and catch basin machines for water and wastewater networks.","alt":"A Vactor 2100i combination sewer cleaner","brand":"vactor","image":"assets/img/range/env-vactor.jpg","lines":["Combination Units","Sewer Cleaners","Catch Basin Cleaners","Water Recyclers"]},{"d":"Industrial vacuum trucks for plant clean-down, wet and dry recovery and purpose-built applications.","alt":"A Guzzler industrial vacuum truck","brand":"guzzler","image":"assets/img/range/env-guzzler.jpg","lines":["Industrial Vacuums","High-Capacity Units","Wet/Dry Units","Custom Solutions"]}]', 'home', NULL, 'سيكشن Federal Signal', '2026-09-30 22:47:03'),
('industries', '[{"d":"Municipal cleaning, roads, sewer infrastructure and public-service applications.","id":"government","icon":"building","name":"Government & Municipalities","image":"assets/img/products/elgin-whirlwind.jpg","products":["elgin-pelican","vactor-2100i","elgin-whirlwind"],"solutions":["environmental","service"]},{"d":"Specialised equipment and power solutions for major infrastructure and construction projects.","id":"infrastructure","icon":"crane","name":"Infrastructure & Construction","image":"assets/img/photos/site-installation.jpg","products":["genset-rental-fleet","genset-containerized","vactor-2100i"],"solutions":["power","engineering"]},{"d":"Heavy-duty cleaning, vacuum applications and power generation for industrial facilities, commercial sites and institutions.","id":"industrial","icon":"factory","name":"Industrial, Commercial & Institutional","image":"assets/img/photos/genset-container.jpg","products":["guzzler-classic","genset-containerized","ats-panel"],"solutions":["power","environmental","service"]},{"d":"Power generation solutions for farms, irrigation, pumping and agricultural operations.","id":"agriculture","icon":"leaf","name":"Agriculture","image":"assets/img/photos/repower-after.jpg","products":["genset-canopy","parts-engine","parts-filters"],"solutions":["power","parts"]},{"d":"Vacuum equipment for solid waste and residue handling at oil and gas sites, plus power generation for field and facility operations.","id":"oil-gas","icon":"drop","name":"Oil & Gas","image":"assets/img/products/guzzler-classic.jpg","products":["guzzler-classic","genset-containerized","genset-rental-fleet"],"solutions":["environmental","power"]},{"d":"Large-scale communities, compounds, facilities and property infrastructure.","id":"real-estate","icon":"home","name":"Real Estate & Developments","image":"assets/img/photos/genset-5am-canopy.jpg","products":["genset-canopy","elgin-pelican","sound-proof-canopy"],"solutions":["power","environmental","engineering"]}]', 'content', NULL, 'القطاعات', '2026-09-30 22:47:02'),
