('projects', '[{"d":"Generator sets delivered ready to operate, after making sure the location and foundation are suitable for the work.","id":"genset-installation","sub":"Installation","name":"Ready-to-operate generators on site","image":"assets/img/photos/site-installation.jpg"},{"d":"Generator sets delivered ready to operate, with the location, foundation and base frame checked before installation.","id":"genset-delivery","sub":"Site mobilisation","name":"Ready-to-operate delivery","image":"assets/img/photos/card-sector-agri.jpg"},{"d":"An old engine replaced with a new engine, with the alternator, control and chassis reused after testing.","id":"repowering","sub":"Extended equipment life","name":"Repowering","image":"assets/img/photos/repower-after.jpg"},{"d":"Metal enclosures for generators, made as part of the 5A&M sheet metal works.","id":"canopy-fabrication","sub":"Sheet metal works","name":"Generator canopies","image":"assets/img/photos/canopy-fabrication.jpg"},{"d":"Fuel tanks and transfer systems fabricated, installed and connected to the generator.","id":"fuel-systems","sub":"Tanks and transfer","name":"Fuel systems","image":"assets/img/photos/fuel-system.jpg"},{"d":"Cable routing, termination and panel connection as part of the installation scope.","id":"cable-routing","sub":"Electrical installation","name":"Cable routing & termination","image":"assets/img/photos/cable-routing.jpg"},{"d":"Field service visits covering troubleshooting, preventive and corrective maintenance.","id":"field-service","sub":"On-site support","name":"Field service","image":"assets/img/photos/field-service.jpg"}]', 'content', NULL, 'المشروعات', '2026-09-30 22:47:02'),
('repoweringSteps', '[{"d":"Inspect the existing set and confirm what can be reused.","t":"Assessment"},{"d":"Fit a new engine in place of the old one.","t":"Engine replacement"},{"d":"Reuse the alternator, control and chassis.","t":"Component reuse"},{"d":"Test the reused components to reach optimal performance.","t":"Testing"},{"d":"Recommission the set and hand it back ready to run.","t":"Commissioning"},{"d":"Extend the generator lifespan at a lower cost than replacement.","t":"Extended life"}]', 'content', NULL, 'خطوات رفع الكفاءة', '2026-09-30 22:47:03'),
('scope', '[{"d":"Diesel generator sets for prime and standby power, plus rental generators.","id":"power","icon":"power","name":"Power Generation","brands":["Perkins","Cummins","Hyundai","Volvo"],"points":["Diesel power generators from 10 to 2500 kVA","Built with genuine Perkins, Cummins, Hyundai and Volvo engines","Stamford and Leroy-Somer alternators","Rental power generators from 20 kVA up to 1000 kVA"]},{"d":"A cost-effective solution that gives an existing generator a longer life.","id":"repowering","icon":"repower","name":"Repowering","brands":[],"points":["Replacing the old engine with a new one","Reusing the alternator, control and chassis after testing","Reaching optimal performance","Extending the generator lifespan"]},{"d":"Metal fabrication for generators and their installations.","id":"fabrication","icon":"sheet","name":"Sheet Metal Works","brands":[],"points":["Metal enclosures — canopies and electrical panels","Mobile and stationary tanks","Exhausts, mufflers and air pipes","Genset trailers"]},{"d":"Reliable, ready-to-operate generator systems tailored to each site.","id":"installation","icon":"install","name":"Installation","brands":[],"points":["Checking that the location, foundation and base frame are suitable","Mechanical and electrical installation of generators and auxiliary systems","Fuel system, exhaust and ventilation setup","Cable routing, termination and panel connection"]},{"d":"Distribution, control and ATS panels designed and assembled to client requirements.","id":"panels","icon":"panel","name":"Control Panels & Controllers","brands":["Schneider Electric","DSE","ABB"],"points":["Automatic transfer switch (ATS) panels","Synchronization panels and phase sequence correction","Residential, construction and HVAC panels","Designed by an experienced electrical design department"]},{"d":"Genuine parts and filters for generators and heavy equipment.","id":"parts","icon":"gear","name":"Spare Parts & Filtration","brands":["Hyundai Infracore","Develon","Fleetguard"],"points":["Genuine Hyundai Infracore generator and excavator parts","Spare parts for brands such as Perkins, Cummins and Volvo","Genuine Develon and Fleetguard filters","Stocked inventory to minimise equipment downtime"]},{"d":"Continuous support from our after-sales and field service teams.","id":"aftersales","icon":"support","name":"After-Sales & Field Service","brands":[],"points":["Quick response and effective issue solution","Supervising installation and commissioning of the units","On-site troubleshooting and emergency breakdown response","Periodic, preventive and corrective maintenance"]},{"d":"All delivered generators and services are backed by a solid warranty.","id":"warranty","icon":"warranty","name":"Warranty","brands":[],"points":["Covers manufacturing defects","Prompt technical support","Spare parts availability","Reliable after-sales service"]}]', 'home', NULL, 'نطاق العمل', '2026-09-30 22:47:03'),
('services', '[{"d":"Field service team supervises installation and commissioning of the units.","icon":"wrench","name":"Installation & Commissioning"},{"d":"Periodic maintenance services on an agreed schedule.","icon":"calendar","name":"Preventive Maintenance"},{"d":"Corrective work to return equipment to service.","icon":"tool","name":"Corrective Maintenance"},{"d":"On-site attendance by an experienced field service team.","icon":"truck","name":"Field Service"},{"d":"On-site troubleshooting and technical support.","icon":"search","name":"Troubleshooting"},{"d":"Emergency breakdown response.","icon":"alert","name":"Emergency Response"},{"d":"Continuous support from the after-sales team.","icon":"headset","name":"Technical Support"},{"d":"Delivered generators and services are backed by warranty covering manufacturing defects.","icon":"shield","name":"Warranty"}]', 'content', NULL, 'الخدمات', '2026-09-30 22:47:02'),
('store', '{"closed":"home","enabled":false}', 'store', 'Store', 'المتجر', '2026-10-26 10:21:43'),
('story', '[{"text":"The business started mainly by supplying Doosan spare parts, particularly for the agricultural sector.","year":"01","title":"Where we started"},{"text":"Doosan engines in the agricultural sector were not delivering the expected operational lifespan.","year":"02","title":"The challenge"},{"text":"We started searching for a reliable alternative to Doosan engines. Instead of focusing on generator assemblers, we decided to approach engine manufacturers directly.","year":"03","title":"A direct approach"},{"text":"After evaluating several options, we identified an engine manufacturer to partner with.","year":"04","title":"A partner identified"},{"text":"By the end of 2025, we successfully finalized our engine supply agreement.","year":"2025","title":"Agreement finalized"}]', 'about', NULL, 'قصة الشركة', '2026-09-30 22:47:02'),
('storyShort', '[{"d":"A 3S business — sales, spare parts and service — for generators and heavy equipment, starting with Doosan spare parts for the agricultural sector.","k":"2022","t":"Founded"},{"d":"Doosan engines in the agricultural sector were not delivering the operational lifespan our customers expected.","k":"The problem","t":"Engines that did not last"},{"d":"Rather than shop among generator assemblers we went to the engine manufacturers themselves. The agreement was finalised at the end of 2025.","k":"2025","t":"Straight to the maker"}]', 'home', NULL, 'نبذة مختصرة', '2026-09-30 22:47:03'),
('whyUs', '[{"k":"Ability","v":"Technical knowledge and practical experience to understand each application and deliver the right solution."},{"k":"Accuracy","v":"Careful attention to specifications, equipment selection and customer requirements."},{"k":"Availability","v":"Reliable access to equipment, spare parts and technical support."},{"k":"Agility","v":"Quick response and flexible solutions adapted to project requirements."},{"k":"Assurance","v":"Reliable products, professional support and a commitment to long-term relationships."},{"k":"Mastery","v":"Specialised knowledge across environmental equipment, power generation, spare parts and technical support."}]', 'about', NULL, 'لماذا 5A&M', '2026-09-30 22:47:02');
